/**
 * Project Card Component
 * 
 * Reusable project card for portfolio showcase
 */

import React from "react";
import { Card, CardContent, Typography, Box, Chip, alpha } from "@mui/material";
import TrendingUpIcon from "@mui/icons-material/TrendingUp";
import { useTranslation } from "react-i18next";
import { Project } from "../../content/portfolio";

interface ProjectCardProps {
  project: Project;
  onClick?: () => void;
  className?: string;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project, onClick, className }) => {
  const { t } = useTranslation();
  const { title, shortDescription, category, techStack, year, results, features } = project;

  const categoryLabels = t("portfolio.card.categoryLabels", { returnObjects: true }) as Record<string, string>;

  return (
    <Card
      component="article"
      className={className}
      onClick={onClick}
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        bgcolor: "background.paper",
        border: "2px solid",
        borderColor: "divider",
        borderRadius: 3,
        cursor: onClick ? "pointer" : "default",
        transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
        position: "relative",
        overflow: "hidden",
        "&::before": {
          content: '""',
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: 3,
          background: `linear-gradient(90deg, ${alpha("#475569", 0.1)}, ${alpha("#64748b", 0.1)})`,
          opacity: 0,
          transition: "opacity 0.3s ease",
        },
        "&:hover": {
          borderColor: alpha("#475569", 0.4),
          boxShadow: "0 8px 24px rgba(0, 0, 0, 0.12)",
          transform: "translateY(-4px)",
          "&::before": {
            opacity: 1,
          },
        },
      }}
    >
      <CardContent sx={{ p: { xs: 2.5, md: 4 }, flexGrow: 1, display: "flex", flexDirection: "column" }}>
        {/* Category & Year - Year hidden on mobile */}
        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
          <Chip
            label={categoryLabels[category] || category}
            size="small"
            sx={{
              bgcolor: alpha("#f1f5f9", 0.8),
              color: "text.secondary",
              fontSize: { xs: "0.7rem", md: "0.75rem" },
              height: { xs: 22, md: 24 },
            }}
          />
          <Typography 
            variant="caption" 
            sx={{ 
              color: "text.secondary", 
              fontSize: "0.8125rem",
              display: { xs: "none", md: "block" }
            }}
          >
            {year}
          </Typography>
        </Box>

        {/* Title */}
        <Typography
          component="h3"
          variant="h5"
          sx={{
            fontWeight: 600,
            mb: { xs: 1.5, md: 2 },
            color: "text.primary",
            fontSize: { xs: "1rem", md: "1.375rem" },
            lineHeight: 1.3,
          }}
        >
          {title}
        </Typography>

        {/* Description - Hidden on mobile to reduce cognitive load */}
        <Typography
          component="p"
          sx={{
            color: "text.secondary",
            mb: features && features.length > 0 ? 2 : 3,
            lineHeight: 1.7,
            flexGrow: 1,
            fontSize: "0.9375rem",
            display: { xs: "none", md: "block" },
          }}
        >
          {shortDescription}
        </Typography>

        {/* Key Features List - Hidden on mobile to reduce cognitive load */}
        {features && features.length > 0 && (
          <Box sx={{ mb: 3, display: { xs: "none", md: "block" } }}>
            <Typography
              variant="caption"
              sx={{
                display: "block",
                color: "text.secondary",
                fontSize: "0.75rem",
                fontWeight: 600,
                textTransform: "uppercase",
                letterSpacing: "0.5px",
                mb: 1,
              }}
              >
                {t("portfolio.card.keyFeatures")}
              </Typography>
            <Box component="ul" sx={{ m: 0, pl: 2, listStyle: "none" }}>
              {features.slice(0, 3).map((feature, idx) => (
                <Box
                  key={idx}
                  component="li"
                  sx={{
                    display: "flex",
                    alignItems: "flex-start",
                    gap: 1,
                    mb: 0.75,
                    "&::before": {
                      content: '"•"',
                      color: "primary.main",
                      fontWeight: "bold",
                      fontSize: "1.2rem",
                      lineHeight: 1,
                      mt: 0.25,
                    },
                  }}
                >
                  <Typography
                    variant="caption"
                    sx={{
                      color: "text.secondary",
                      fontSize: "0.8125rem",
                      lineHeight: 1.5,
                      flex: 1,
                    }}
                  >
                    {feature}
                  </Typography>
                </Box>
              ))}
            </Box>
          </Box>
        )}

        {/* Tech Stack - Hidden on mobile to reduce cognitive load */}
        {techStack && techStack.length > 0 && (
          <Box sx={{ mb: 3, display: { xs: "none", md: "flex" }, flexWrap: "wrap", gap: 1 }}>
            {techStack.slice(0, 4).map((tech, idx) => (
              <Chip
                key={idx}
                label={tech}
                size="small"
                sx={{
                  bgcolor: alpha("#f8fafc", 0.8),
                  color: "text.secondary",
                  fontSize: "0.75rem",
                  height: 24,
                  border: "1px solid",
                  borderColor: "divider",
                }}
              />
            ))}
          </Box>
        )}

        {/* Results (if available) - Hidden on mobile to reduce cognitive load */}
        {results && results.length > 0 && (
          <Box
            sx={{
              mt: "auto",
              pt: 3,
              borderTop: "1px solid",
              borderColor: "divider",
              display: { xs: "none", md: "block" },
            }}
          >
            <Typography
              variant="caption"
              sx={{
                display: "block",
                color: "text.secondary",
                fontSize: "0.75rem",
                fontWeight: 600,
                textTransform: "uppercase",
                letterSpacing: "0.5px",
                mb: 1.5,
              }}
              >
                {t("portfolio.card.results")}
              </Typography>
            {results.slice(0, 3).map((result, idx) => (
              <Box
                key={idx}
                sx={{
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                  mb: 1,
                }}
              >
                <TrendingUpIcon
                  sx={{
                    fontSize: 16,
                    color: "primary.main",
                    opacity: 0.7,
                  }}
                />
                <Typography
                  variant="caption"
                  sx={{
                    color: "text.secondary",
                    fontSize: "0.8125rem",
                    lineHeight: 1.5,
                  }}
                >
                  {result}
                </Typography>
              </Box>
            ))}
          </Box>
        )}
      </CardContent>
    </Card>
  );
};

export default ProjectCard;
