/**
 * SEO Component
 * 
 * Dynamic SEO meta tags and structured data
 * Supports both traditional SEO and AI-first SEO
 */

import React from "react";
import { Helmet } from "react-helmet-async";
import { useLocation } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { PageContent } from "../content/types";
import {
  generateOrganizationSchema,
  generateWebSiteSchema,
  getOptimizedTitle,
  getOptimizedDescription,
} from "../utils/seo";

interface SEOProps {
  content: PageContent;
  structuredData?: Array<Record<string, unknown>>;
  ogImage?: string;
  noindex?: boolean;
}

const Seo: React.FC<SEOProps> = ({
  content,
  structuredData = [],
  ogImage,
  noindex = false,
}) => {
  const location = useLocation();
  const { i18n } = useTranslation();
  const baseUrl = globalThis.window !== undefined ? globalThis.window.location.origin : "";
  const currentUrl = `${baseUrl}${location.pathname}`;
  const title = getOptimizedTitle(content.meta.title);
  const description = getOptimizedDescription(content.meta.description);

  // Map language code to HTML lang and og:locale
  const langMap: Record<string, { lang: string; locale: string }> = {
    vi: { lang: "vi", locale: "vi_VN" },
    en: { lang: "en", locale: "en_US" },
    ja: { lang: "ja", locale: "ja_JP" },
  };
  const currentLang = langMap[i18n.language] || langMap.vi;

  // Default structured data
  const defaultStructuredData = [
    generateWebSiteSchema(),
    generateOrganizationSchema(),
  ];

  // Combine all structured data
  const allStructuredData = [...defaultStructuredData, ...structuredData];

  // Default OG image - use main logo by default
  const defaultOgImage = ogImage || `${baseUrl}/logo.png`;

  return (
    <Helmet>
      {/* Basic Meta Tags */}
      <html lang={currentLang.lang} />
      <title>{title}</title>
      <meta name="description" content={description} />
      {content.meta.keywords && (() => {
        let keywordsContent = "";
        if (Array.isArray(content.meta.keywords)) {
          keywordsContent = content.meta.keywords.join(", ");
        } else if (typeof content.meta.keywords === "string") {
          keywordsContent = content.meta.keywords;
        }
        return (
          <meta 
            name="keywords" 
            content={keywordsContent} 
          />
        );
      })()}

      {/* Canonical URL */}
      <link rel="canonical" href={currentUrl} />

      {/* Robots */}
      {noindex && <meta name="robots" content="noindex, nofollow" />}
      {!noindex && <meta name="robots" content="index, follow" />}

      {/* Open Graph Tags */}
      <meta property="og:type" content="website" />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={currentUrl} />
      <meta property="og:image" content={defaultOgImage} />
      <meta property="og:image:width" content="1200" />
      <meta property="og:image:height" content="630" />
      <meta property="og:locale" content={currentLang.locale} />
      <meta property="og:site_name" content="Nguyễn Văn An - Full Stack Developer" />

      {/* Twitter Card Tags */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={title} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={defaultOgImage} />

      {/* Structured Data (JSON-LD) */}
      {allStructuredData.map((data, index) => {
        const schemaId = `schema-${index}-${(data["@type"] as string) || "unknown"}`;
        return (
          <script
            key={schemaId}
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
          />
        );
      })}
    </Helmet>
  );
};

export default Seo;
