/**
 * Service Card Component
 * 
 * Reusable service card with content-driven approach
 * Displays service information with features and CTA
 */

import React from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  Card,
  CardContent,
  Typography,
  Button,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Box,
  alpha,
} from "@mui/material";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import Icon from "../Icon";
import { ServiceContent } from "../../content/types";
import { normalizeIconName } from "../../utils/iconMapping";

interface ServiceCardProps {
  service: ServiceContent;
  showFeatures?: number; // Number of features to show
  className?: string;
}

const ServiceCard: React.FC<ServiceCardProps> = ({
  service,
  showFeatures = 3,
  className,
}) => {
  const { t } = useTranslation();
  const { title, shortDescription, description, icon, features, link } = service;
  const displayDescription = shortDescription || description;

  return (
    <Card
      component="article"
      className={className}
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        bgcolor: "background.paper",
        border: "2px solid",
        borderColor: "divider",
        borderRadius: 3,
        transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
        position: "relative",
        overflow: "hidden",
        "&::before": {
          content: '""',
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: 3,
          background: `linear-gradient(90deg, ${alpha("#475569", 0.1)}, ${alpha("#64748b", 0.1)})`,
          opacity: 0,
          transition: "opacity 0.3s ease",
        },
        "&:hover": {
          borderColor: alpha("#475569", 0.4),
          boxShadow: "0 8px 24px rgba(0, 0, 0, 0.12)",
          transform: "translateY(-4px)",
          "&::before": {
            opacity: 1,
          },
          "& .service-icon-container": {
            transform: "scale(1.1) rotate(5deg)",
          },
        },
      }}
    >
      <CardContent
        sx={{
          p: { xs: 2.5, md: 4 },
          flexGrow: 1,
          display: "flex",
          flexDirection: "column",
        }}
      >
        {/* Enhanced Icon */}
        <Box
          className="service-icon-container"
          sx={{
            mb: { xs: 2, md: 3 },
            display: "inline-flex",
            width: { xs: 48, md: 64 },
            height: { xs: 48, md: 64 },
            borderRadius: 3,
            background: `linear-gradient(135deg, ${alpha("#475569", 0.08)} 0%, ${alpha("#64748b", 0.08)} 100%)`,
            alignItems: "center",
            justifyContent: "center",
            border: `1.5px solid ${alpha("#475569", 0.15)}`,
            transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
          }}
        >
          <Box sx={{ fontSize: { xs: "1.5rem", md: "2rem" } }}>
            <Icon
              name={normalizeIconName(icon)}
              size="xlarge"
              color="primary"
            />
          </Box>
        </Box>

        {/* Title */}
        <Typography
          component="h3"
          variant="h5"
          sx={{
            fontWeight: 600,
            mb: { xs: 1.5, md: 2 },
            color: "text.primary",
            fontSize: { xs: "1rem", md: "1.375rem" },
            lineHeight: 1.3,
          }}
        >
          {title}
        </Typography>

        {/* Description */}
        <Typography
          component="p"
          sx={{
            color: "text.secondary",
            mb: { xs: 2, md: 3 },
            lineHeight: 1.6,
            flexGrow: 1,
            fontSize: { xs: "0.8125rem", md: "0.9375rem" },
            display: { xs: "none", md: "block" },
          }}
        >
          {displayDescription}
        </Typography>

        {/* Features List - Hidden on mobile to reduce cognitive load */}
        {features && features.length > 0 && (
          <List
            component="ul"
            sx={{ 
              mb: { xs: 2, md: 3 }, 
              p: 0, 
              flexGrow: 1,
              display: { xs: "none", md: "block" }
            }}
            aria-label={`Features of ${title}`}
          >
            {features.slice(0, showFeatures).map((feature, idx) => (
              <ListItem key={`${service.id}-feature-${idx}`} sx={{ px: 0, py: 0.75 }}>
                <ListItemIcon sx={{ minWidth: 28 }}>
                  <CheckCircleIcon
                    sx={{
                      fontSize: 18,
                      color: "accent.main",
                    }}
                    aria-hidden="true"
                  />
                </ListItemIcon>
                <ListItemText
                  primary={feature}
                  primaryTypographyProps={{
                    component: "li",
                    sx: {
                      fontWeight: 400,
                      color: "text.secondary",
                      fontSize: "0.875rem",
                      lineHeight: 1.6,
                    },
                  }}
                />
              </ListItem>
            ))}
          </List>
        )}

        {/* Enhanced CTA Button */}
        <Button
          component={Link}
          to={link}
          endIcon={<ArrowForwardIcon sx={{ fontSize: { xs: 16, md: 18 } }} />}
          sx={{
            color: "text.primary",
            fontWeight: 600,
            mt: "auto",
            fontSize: { xs: "0.8125rem", md: "0.9375rem" },
            justifyContent: "flex-start",
            px: 0,
            py: { xs: 0.75, md: 1 },
            borderRadius: 2,
            transition: "all 0.3s ease",
            "&:hover": {
              color: "primary.main",
              bgcolor: alpha("#475569", 0.05),
              "& .MuiSvgIcon-root": {
                transform: "translateX(6px)",
              },
            },
            "& .MuiSvgIcon-root": {
              transition: "transform 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
            },
          }}
          aria-label={`Learn more about ${title}`}
        >
          {t("common.viewDetails")}
        </Button>
      </CardContent>
    </Card>
  );
};

export default ServiceCard;
