/**
 * Get translated portfolio page content
 */
export const usePortfolioContent = () => {
  const { t } = useTranslation();
  
  // Import portfolio projects from content file (fallback to content if translations empty)
  const translatedProjects = t("portfolio.projects", { returnObjects: true });
  const { portfolioProjects } = require("../content/portfolio");
  
  // Ensure projects is always an array
  let projects: Project[];
  if (Array.isArray(translatedProjects) && translatedProjects.length > 0) {
    projects = translatedProjects as Project[];
  } else {
    projects = portfolioProjects as Project[];
  }

  return {
    meta: {
      title: t("portfolio.meta.title"),
      description: t("portfolio.meta.description"),
      keywords: t("portfolio.meta.keywords", { returnObjects: true }) as string[],
    },
    section: {
      badge: t("portfolio.section.badge"),
      title: t("portfolio.section.title"),
      description: t("portfolio.section.description"),
      alignment: "center" as const,
    },
    emptyState: t("portfolio.emptyState"),
    categories: t("portfolio.categories", { returnObjects: true }) as Record<string, string>,
    projects,
  };
};

/**
 * Get translated blog page content
 */
export const useBlogContent = () => {
  const { t, i18n } = useTranslation();
  const [articles, setArticles] = React.useState<BlogArticle[]>([]);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    const loadArticles = async () => {
      try {
        setLoading(true);
        const language = i18n.language === "vi" ? "vi" : i18n.language === "ja" ? "ja" : "en";
        const loadedArticles = await blogService.getArticles(language);
        setArticles(loadedArticles);
      } catch (error) {
        console.error("Error loading blog articles:", error);
        // Fallback to empty array
        setArticles([]);
      } finally {
        setLoading(false);
      }
    };

    loadArticles();
  }, [i18n.language]);

  return {
    meta: {
      title: t("blog.meta.title"),
      description: t("blog.meta.description"),
      keywords: t("blog.meta.keywords", { returnObjects: true }) as string[],
    },
    section: {
      badge: t("blog.section.badge"),
      title: t("blog.section.title"),
      description: t("blog.section.description"),
      alignment: "center" as const,
    },
    emptyState: t("blog.emptyState"),
    categories: t("blog.categories", { returnObjects: true }) as Record<string, string>,
    articles,
    loading,
  };
};

