/**
 * Date Utility Functions
 * 
 * Smart date formatting for blog posts and articles
 */

/**
 * Format date with smart relative time display
 * - Recent posts (within 7 days): "2 ngày trước", "1 tuần trước"
 * - Older posts: Full date format based on locale
 */
export const formatBlogDate = (dateString: string, locale: string = "vi-VN"): string => {
  const date = new Date(dateString);
  const now = new Date();
  const diffInMs = now.getTime() - date.getTime();
  const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
  const diffInHours = Math.floor(diffInMs / (1000 * 60 * 60));
  const diffInMinutes = Math.floor(diffInMs / (1000 * 60));

  // Invalid date check
  if (isNaN(date.getTime())) {
    return dateString; // Return original if invalid
  }

  // Determine locale for translations
  const lang = locale.split("-")[0] || "vi";

  // Recent posts - show relative time
  if (diffInMinutes < 60) {
    // Less than 1 hour ago
    if (lang === "vi") {
      return diffInMinutes <= 1 ? "Vừa xong" : `${diffInMinutes} phút trước`;
    } else if (lang === "ja") {
      return diffInMinutes <= 1 ? "たった今" : `${diffInMinutes}分前`;
    } else {
      return diffInMinutes <= 1 ? "Just now" : `${diffInMinutes} minutes ago`;
    }
  } else if (diffInHours < 24) {
    // Less than 24 hours ago
    if (lang === "vi") {
      return diffInHours === 1 ? "1 giờ trước" : `${diffInHours} giờ trước`;
    } else if (lang === "ja") {
      return diffInHours === 1 ? "1時間前" : `${diffInHours}時間前`;
    } else {
      return diffInHours === 1 ? "1 hour ago" : `${diffInHours} hours ago`;
    }
  } else if (diffInDays === 1) {
    // Yesterday
    if (lang === "vi") {
      return "Hôm qua";
    } else if (lang === "ja") {
      return "昨日";
    } else {
      return "Yesterday";
    }
  } else if (diffInDays < 7) {
    // Within a week
    if (lang === "vi") {
      return `${diffInDays} ngày trước`;
    } else if (lang === "ja") {
      return `${diffInDays}日前`;
    } else {
      return `${diffInDays} days ago`;
    }
  } else if (diffInDays < 30) {
    // Within a month
    const weeks = Math.floor(diffInDays / 7);
    if (lang === "vi") {
      return weeks === 1 ? "1 tuần trước" : `${weeks} tuần trước`;
    } else if (lang === "ja") {
      return weeks === 1 ? "1週間前" : `${weeks}週間前`;
    } else {
      return weeks === 1 ? "1 week ago" : `${weeks} weeks ago`;
    }
  } else if (diffInDays < 365) {
    // Within a year - show month and day
    const localeMap: Record<string, string> = {
      vi: "vi-VN",
      ja: "ja-JP",
      en: "en-US",
    };
    const dateLocale = localeMap[lang] || "vi-VN";
    return date.toLocaleDateString(dateLocale, {
      month: "long",
      day: "numeric",
    });
  } else {
    // Older than a year - show full date
    const localeMap: Record<string, string> = {
      vi: "vi-VN",
      ja: "ja-JP",
      en: "en-US",
    };
    const dateLocale = localeMap[lang] || "vi-VN";
    return date.toLocaleDateString(dateLocale, {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  }
};

/**
 * Format date for display (full format with time if needed)
 */
export const formatFullDate = (dateString: string, locale: string = "vi-VN"): string => {
  const date = new Date(dateString);
  
  if (isNaN(date.getTime())) {
    return dateString;
  }

  const localeMap: Record<string, string> = {
    vi: "vi-VN",
    ja: "ja-JP",
    en: "en-US",
  };
  const lang = locale.split("-")[0] || "vi";
  const dateLocale = localeMap[lang] || "vi-VN";

  return date.toLocaleDateString(dateLocale, {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};
