/**
 * Promotional Banner Component
 * 
 * Displays promotional discounts and savings
 */

import React from "react";
import { Box, Container, Typography, Chip, alpha } from "@mui/material";
import { useTranslation } from "react-i18next";
import LocalOfferIcon from "@mui/icons-material/LocalOffer";

const PromotionalBanner: React.FC = () => {
  const { t } = useTranslation();

  return (
    <Box
      sx={{
        py: { xs: 4, md: 6 },
        bgcolor: alpha("#0ea5e9", 0.1),
        borderTop: "1px solid",
        borderBottom: "1px solid",
        borderColor: "divider",
      }}
    >
      <Container maxWidth="lg">
        <Box
          sx={{
            display: "flex",
            flexDirection: { xs: "column", md: "row" },
            alignItems: "center",
            justifyContent: "space-between",
            gap: 3,
          }}
        >
          <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
            <LocalOfferIcon sx={{ fontSize: 40, color: "primary.main" }} />
            <Box>
              <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
                {t("pricing.promotions.title")}
              </Typography>
              <Typography variant="body2" sx={{ color: "text.secondary" }}>
                {t("pricing.promotions.totalSavings")}
              </Typography>
            </Box>
          </Box>

          <Box
            sx={{
              display: "flex",
              flexWrap: "wrap",
              gap: 2,
              justifyContent: { xs: "center", md: "flex-end" },
            }}
          >
            <Chip
              label={t("pricing.promotions.firstMonth.title")}
              sx={{
                bgcolor: "primary.main",
                color: "white",
                fontWeight: 600,
                fontSize: "0.875rem",
                px: 1,
              }}
            />
            <Chip
              label={t("pricing.promotions.6Month.title")}
              sx={{
                bgcolor: "primary.main",
                color: "white",
                fontWeight: 600,
                fontSize: "0.875rem",
                px: 1,
              }}
            />
            <Chip
              label={t("pricing.promotions.12Month.title")}
              sx={{
                bgcolor: "primary.main",
                color: "white",
                fontWeight: 600,
                fontSize: "0.875rem",
                px: 1,
              }}
            />
          </Box>
        </Box>
      </Container>
    </Box>
  );
};

export default PromotionalBanner;
