export type SheetFormId = "contact" | "job-request";

export interface SheetSubmissionPayload {
  form: SheetFormId;
  data: Record<string, unknown>;
}

export async function submitFormToSheet(
  payload: SheetSubmissionPayload
): Promise<{ ok: true } | { ok: false; error: string }> {
  const url = process.env.REACT_APP_GOOGLE_SHEETS_WEB_APP_URL?.trim();

  if (!url) {
    console.warn(
      "[form submission] REACT_APP_GOOGLE_SHEETS_WEB_APP_URL is not set; skipping remote POST."
    );
    await new Promise((r) => setTimeout(r, 400));
    return { ok: true };
  }

  const body: Record<string, unknown> = {
    submittedAt: new Date().toISOString(),
    form: payload.form,
    data: payload.data,
  };
  const secret = process.env.REACT_APP_FORM_WEBHOOK_SECRET?.trim();
  if (secret) body.secret = secret;

  try {
    // text/plain avoids a CORS preflight; application/json triggers OPTIONS,
    // which Google Apps Script web apps often answer with 405 Method Not Allowed.
    const res = await fetch(url, {
      method: "POST",
      redirect: "follow",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify(body),
    });

    const text = await res.text();
    if (!res.ok) {
      return { ok: false, error: `http_${res.status}` };
    }

    try {
      const json = JSON.parse(text) as { ok?: boolean; error?: string };
      if (json?.ok === false) {
        return { ok: false, error: json.error || "sheet_rejected" };
      }
    } catch {
      /* Apps Script may return non-JSON; treat HTTP 2xx as success */
    }

    return { ok: true };
  } catch {
    return { ok: false, error: "network" };
  }
}
