/**
 * Currency Context
 * 
 * Provides currency state and conversion utilities across the app
 */

import React, { createContext, useContext, useState, ReactNode } from "react";
import { CurrencyCode, CURRENCIES } from "../components/CurrencySwitcher";

interface CurrencyContextType {
  currency: CurrencyCode;
  setCurrency: (currency: CurrencyCode) => void;
  convertPrice: (priceInJPY: number) => number;
  formatPrice: (priceInJPY: number, options?: { min?: number; max?: number }) => string;
  formatPriceRange: (range: { min: number; max: number }) => string;
  getCurrencySymbol: () => string;
}

const CurrencyContext = createContext<CurrencyContextType | undefined>(undefined);

export const useCurrency = () => {
  const context = useContext(CurrencyContext);
  if (!context) {
    throw new Error("useCurrency must be used within CurrencyProvider");
  }
  return context;
};

interface CurrencyProviderProps {
  children: ReactNode;
}

export const CurrencyProvider: React.FC<CurrencyProviderProps> = ({ children }) => {
  const [currency, setCurrencyState] = useState<CurrencyCode>(() => {
    // Load from localStorage or infer from language, fallback to JPY
    if (typeof window !== "undefined") {
      const saved = localStorage.getItem("preferredCurrency") as CurrencyCode | null;
      if (saved && CURRENCIES.some((c) => c.code === saved)) {
        return saved;
      }

      // Infer default currency from current language (stored by i18next)
      try {
        const storedLang = window.localStorage.getItem("i18nextLng") || navigator.language || "vi";
        const langCode = storedLang.slice(0, 2);

        if (langCode === "vi") return "VND";
        if (langCode === "en") return "USD";
        if (langCode === "ja") return "JPY";
      } catch {
        // Ignore detection errors and fall back below
      }
    }
    return "JPY";
  });

  const setCurrency = (newCurrency: CurrencyCode) => {
    setCurrencyState(newCurrency);
    if (typeof window !== "undefined") {
      localStorage.setItem("preferredCurrency", newCurrency);
    }
  };

  // Get current currency object
  const currentCurrency = CURRENCIES.find((c) => c.code === currency) || CURRENCIES[2]; // Default to JPY

  // Convert JPY price to selected currency
  const convertPrice = (priceInJPY: number): number => {
    if (currency === "JPY") return priceInJPY;
    
    // JPY is base currency for pricing
    // BUSINESS RATE: tuned to Da Nang market (not real FX)
    // Convert: JPY -> VND -> Target Currency
    const JPY_TO_VND = 37.5;
    const priceInVND = priceInJPY * JPY_TO_VND;
    
    if (currency === "VND") return priceInVND;
    if (currency === "USD") {
      const VND_TO_USD = 25000; // Approximate rate
      return priceInVND / VND_TO_USD;
    }
    
    return priceInJPY;
  };

  // Format single price
  const formatPrice = (priceInJPY: number, options?: { min?: number; max?: number }): string => {
    const convertedPrice = convertPrice(priceInJPY);
    
    if (options?.min !== undefined && options?.max !== undefined) {
      const minConverted = convertPrice(options.min);
      const maxConverted = convertPrice(options.max);
      return formatPriceRange({ min: minConverted, max: maxConverted });
    }

    if (currency === "JPY") {
      if (convertedPrice >= 1000000) {
        return `¥${(convertedPrice / 1000000).toFixed(1)}M`;
      }
      return `¥${(convertedPrice / 1000).toFixed(0)}K`;
    }

    if (currency === "USD") {
      // For clarity, show full amount in USD (no K/M)
      return `$${convertedPrice.toLocaleString("en-US", {
        maximumFractionDigits: 0,
      })}`;
    }

    if (currency === "VND") {
      // For Vietnamese users, show full number with thousand separators (no M/K)
      return `${convertedPrice.toLocaleString("vi-VN", {
        maximumFractionDigits: 0,
      })} ₫`;
    }

    return `${convertedPrice.toFixed(0)}`;
  };

  // Format price range
  const formatPriceRange = (range: { min: number; max: number }): string => {
    const minConverted = convertPrice(range.min);
    const maxConverted = convertPrice(range.max);

    if (currency === "JPY") {
      const formatNumber = (num: number): string => {
        if (num >= 1000000) {
          return `¥${(num / 1000000).toFixed(1)}M`;
        }
        return `¥${(num / 1000).toFixed(0)}K`;
      };
      return `${formatNumber(minConverted)}-${formatNumber(maxConverted)}`;
    }

    if (currency === "USD") {
      const formatNumber = (num: number): string => {
        return `$${num.toLocaleString("en-US", {
          maximumFractionDigits: 0,
        })}`;
      };
      return `${formatNumber(minConverted)}-${formatNumber(maxConverted)}`;
    }

    if (currency === "VND") {
      const formatNumber = (num: number): string => {
        return `${num.toLocaleString("vi-VN", {
          maximumFractionDigits: 0,
        })} ₫`;
      };
      return `${formatNumber(minConverted)}-${formatNumber(maxConverted)}`;
    }

    return `${minConverted.toFixed(0)}-${maxConverted.toFixed(0)}`;
  };

  const getCurrencySymbol = (): string => {
    return currentCurrency.symbol;
  };

  return (
    <CurrencyContext.Provider
      value={{
        currency,
        setCurrency,
        convertPrice,
        formatPrice,
        formatPriceRange,
        getCurrencySymbol,
      }}
    >
      {children}
    </CurrencyContext.Provider>
  );
};
