/**
 * Generate Service Schema for individual service
 */
export const generateServiceSchema = (
  serviceName: string,
  description: string,
  serviceType: string,
  options?: {
    aggregateRating?: {
      ratingValue: number;
      reviewCount: number;
      bestRating?: number;
      worstRating?: number;
    };
    offers?: {
      price?: string;
      priceCurrency?: string;
      availability?: string;
    };
  }
): StructuredData => {
  const baseSchema: StructuredData = {
    "@context": "https://schema.org",
    "@type": "Service",
    name: serviceName,
    description: description,
    serviceType: serviceType,
    provider: {
      "@type": "Person",
      name: "Nguyễn Văn An",
    },
    areaServed: {
      "@type": "Country",
      name: "Vietnam",
    },
    availableChannel: {
      "@type": "ServiceChannel",
      serviceUrl: typeof window !== "undefined" ? window.location.href : "",
    },
  };

  // Add AggregateRating if provided
  if (options?.aggregateRating) {
    baseSchema.aggregateRating = {
      "@type": "AggregateRating",
      ratingValue: options.aggregateRating.ratingValue,
      reviewCount: options.aggregateRating.reviewCount,
      bestRating: options.aggregateRating.bestRating || 5,
      worstRating: options.aggregateRating.worstRating || 1,
    };
  }

  // Add Offers if provided
  if (options?.offers) {
    baseSchema.offers = {
      "@type": "Offer",
      price: options.offers.price || "Contact for pricing",
      priceCurrency: options.offers.priceCurrency || "VND",
      availability: options.offers.availability || "https://schema.org/InStock",
    };
  }

  return baseSchema;
};

/**
 * Generate Article Schema for blog posts
 */
export const generateArticleSchema = (
  title: string,
  description: string,
  author: string,
  publishedAt: string,
  url: string,
  image?: string
): StructuredData => {
  const baseUrl = typeof window !== "undefined" ? window.location.origin : "";
  
  return {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    headline: title,
    description: description,
    author: {
      "@type": "Person",
      name: author,
    },
    datePublished: publishedAt,
    dateModified: publishedAt,
    publisher: {
      "@type": "Person",
      name: "Nguyễn Văn An",
    },
    ...(image && {
      image: {
        "@type": "ImageObject",
        url: image.startsWith("http") ? image : `${baseUrl}${image}`,
      },
    }),
    mainEntityOfPage: {
      "@type": "WebPage",
      "@id": url.startsWith("http") ? url : `${baseUrl}${url}`,
    },
  };
};

/**
 * Generate BreadcrumbList Schema
 */
export const generateBreadcrumbSchema = (
  items: Array<{ name: string; url: string }>
): StructuredData => {
  const baseUrl = typeof window !== "undefined" ? window.location.origin : "";
  
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((item, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: item.name,
      item: item.url.startsWith("http") ? item.url : `${baseUrl}${item.url}`,
    })),
  };
};

/**
 * Generate FAQPage Schema
 */
export const generateFAQSchema = (
  faqs: Array<{ question: string; answer: string }>
): StructuredData => {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((faq) => ({
      "@type": "Question",
      name: faq.question,
      acceptedAnswer: {
        "@type": "Answer",
        text: faq.answer,
      },
    })),
  };
};

