/**
 * Generate Review/AggregateRating Schema
 */
export const generateReviewSchema = (
  ratingValue: number,
  reviewCount: number,
  bestRating: number = 5,
  worstRating: number = 1
): StructuredData => {
  return {
    "@context": "https://schema.org",
    "@type": "AggregateRating",
    ratingValue: ratingValue.toString(),
    reviewCount: reviewCount.toString(),
    bestRating: bestRating.toString(),
    worstRating: worstRating.toString(),
  };
};

/**
 * Get optimized title (ensure < 60 chars)
 */
export const getOptimizedTitle = (title: string, maxLength = 60): string => {
  if (title.length <= maxLength) return title;
  return title.substring(0, maxLength - 3) + "...";
};

/**
 * Get optimized description (ensure 120-160 chars)
 */
export const getOptimizedDescription = (
  description: string,
  minLength = 120,
  maxLength = 160
): string => {
  if (description.length >= minLength && description.length <= maxLength) {
    return description;
  }
  if (description.length < minLength) {
    return description + " | Liên hệ ngay để được tư vấn miễn phí.";
  }
  return description.substring(0, maxLength - 3) + "...";
};
