/**
 * Trust Badges Section Component
 * 
 * Displays certifications, awards, and trust indicators
 */

import React from "react";
import { Box, Container, Grid, Typography, alpha } from "@mui/material";
import SectionHeader from "./SectionHeader";
import { SectionHeader as SectionHeaderType } from "../../content/types";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import VerifiedIcon from "@mui/icons-material/Verified";
import AwardIcon from "@mui/icons-material/EmojiEvents";
import SchoolIcon from "@mui/icons-material/School";

interface TrustBadge {
  id: string;
  type: "certification" | "award" | "experience" | "achievement";
  title: string;
  issuer?: string;
  year?: string;
  icon?: React.ReactNode;
  description?: string;
}

interface TrustBadgesSectionProps {
  header: SectionHeaderType;
  badges: TrustBadge[];
  className?: string;
}

const TrustBadgesSection: React.FC<TrustBadgesSectionProps> = ({
  header,
  badges,
  className,
}) => {
  const getIcon = (badge: TrustBadge) => {
    if (badge.icon) return badge.icon;
    
    switch (badge.type) {
      case "certification":
        return <VerifiedIcon sx={{ fontSize: 32, color: "primary.main" }} />;
      case "award":
        return <AwardIcon sx={{ fontSize: 32, color: "primary.main" }} />;
      case "experience":
        return <CheckCircleIcon sx={{ fontSize: 32, color: "primary.main" }} />;
      case "achievement":
        return <SchoolIcon sx={{ fontSize: 32, color: "primary.main" }} />;
      default:
        return <CheckCircleIcon sx={{ fontSize: 32, color: "primary.main" }} />;
    }
  };

  return (
    <Box
      component="section"
      className={className}
      sx={{
        py: { xs: 12, md: 16 },
        bgcolor: "background.paper",
        position: "relative",
        overflow: "hidden",
      }}
    >
      <Container maxWidth="lg">
        <SectionHeader content={header} />
        <Grid container spacing={4} sx={{ mt: 6 }}>
          {badges.map((badge) => (
            <Grid size={{ xs: 12, sm: 6, md: 4, lg: 3 }} key={badge.id}>
              <Box
                sx={{
                  p: 4,
                  height: "100%",
                  bgcolor: "background.default",
                  borderRadius: 3,
                  border: "1px solid",
                  borderColor: "divider",
                  textAlign: "center",
                  transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
                  "&:hover": {
                    borderColor: alpha("#475569", 0.3),
                    boxShadow: "0 8px 24px rgba(0, 0, 0, 0.08)",
                    transform: "translateY(-4px)",
                  },
                }}
              >
                <Box
                  sx={{
                    mb: 3,
                    display: "flex",
                    justifyContent: "center",
                  }}
                >
                  {getIcon(badge)}
                </Box>
                <Typography
                  component="h3"
                  sx={{
                    fontWeight: 600,
                    mb: 1,
                    color: "text.primary",
                    fontSize: "1rem",
                  }}
                >
                  {badge.title}
                </Typography>
                {badge.issuer && (
                  <Typography
                    variant="caption"
                    sx={{
                      color: "text.secondary",
                      fontSize: "0.8125rem",
                      display: "block",
                      mb: 1,
                    }}
                  >
                    {badge.issuer}
                  </Typography>
                )}
                {badge.year && (
                  <Typography
                    variant="caption"
                    sx={{
                      color: "text.secondary",
                      fontSize: "0.8125rem",
                      display: "block",
                      mb: 1,
                    }}
                  >
                    {badge.year}
                  </Typography>
                )}
                {badge.description && (
                  <Typography
                    sx={{
                      color: "text.secondary",
                      fontSize: "0.875rem",
                      lineHeight: 1.6,
                      mt: 2,
                    }}
                  >
                    {badge.description}
                  </Typography>
                )}
              </Box>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

export default TrustBadgesSection;
export type { TrustBadge };
