/**
 * Market Comparison Table Component
 * 
 * Compares our rates with market rates
 */

import React from "react";
import {
  Box,
  Container,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  alpha,
  useMediaQuery,
  useTheme,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { marketComparison } from "../../content/pricing";
import { SectionHeader } from "../sections";
import { useCurrency } from "../../contexts/CurrencyContext";

const MarketComparisonTable: React.FC = () => {
  const { t } = useTranslation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const { formatPriceRange } = useCurrency();

  if (isMobile) {
    return (
      <Box component="section" sx={{ py: { xs: 6, md: 8 } }}>
        <Container maxWidth="lg">
          <SectionHeader
            content={{
              badge: "",
              title: t("pricing.comparison.title"),
              description: "",
              alignment: "center",
            }}
          />

          <Box sx={{ display: "flex", flexDirection: "column", gap: 2, mt: 4 }}>
            {marketComparison.map((item, index) => {
              const savingsPercent = ((item.savings.min / item.marketRate.min) * 100).toFixed(0);
              return (
                <Paper
                  key={index}
                  elevation={2}
                  sx={{
                    p: 3,
                    borderRadius: 2,
                    border: "1px solid",
                    borderColor: "divider",
                  }}
                >
                  <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                    {item.role}
                  </Typography>
                  <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
                    <Box sx={{ display: "flex", justifyContent: "space-between" }}>
                      <Typography variant="body2" color="text.secondary">
                        {t("pricing.comparison.marketRate")}
                      </Typography>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>
                        {formatPriceRange(item.marketRate)} / {t("common.month")}
                      </Typography>
                    </Box>
                    <Box sx={{ display: "flex", justifyContent: "space-between" }}>
                      <Typography variant="body2" color="text.secondary">
                        {t("pricing.comparison.ourRate")}
                      </Typography>
                      <Typography variant="body2" sx={{ fontWeight: 600, color: "primary.main" }}>
                        {formatPriceRange(item.ourRate)} / {t("common.month")}
                      </Typography>
                    </Box>
                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <Typography variant="body2" color="text.secondary">
                        {t("pricing.comparison.savings")}
                      </Typography>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600, color: "success.main" }}>
                          {formatPriceRange(item.savings)} / {t("common.month")}
                        </Typography>
                        <Chip label={`-${savingsPercent}%`} size="small" color="success" />
                      </Box>
                    </Box>
                  </Box>
                </Paper>
              );
            })}
          </Box>
        </Container>
      </Box>
    );
  }

  return (
    <Box component="section" sx={{ py: { xs: 6, md: 8 }, bgcolor: alpha("#f1f5f9", 0.3) }}>
      <Container maxWidth="lg">
          <SectionHeader
            content={{
              badge: "",
              title: t("pricing.comparison.title"),
              description: "",
              alignment: "center",
            }}
          />

        <TableContainer
          component={Paper}
          elevation={2}
          sx={{
            mt: 6,
            borderRadius: 2,
            border: "1px solid",
            borderColor: "divider",
          }}
        >
          <Table>
            <TableHead>
              <TableRow sx={{ bgcolor: alpha("#f1f5f9", 0.5) }}>
                <TableCell sx={{ fontWeight: 700 }}>{t("pricing.comparison.role")}</TableCell>
                <TableCell align="center" sx={{ fontWeight: 600 }}>
                  {t("pricing.comparison.marketRate")}
                </TableCell>
                <TableCell align="center" sx={{ fontWeight: 600 }}>
                  {t("pricing.comparison.ourRate")}
                </TableCell>
                <TableCell align="center" sx={{ fontWeight: 600 }}>
                  {t("pricing.comparison.savings")}
                </TableCell>
                <TableCell align="center" sx={{ fontWeight: 600 }}>
                  {t("pricing.comparison.savingsPercent")}
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {marketComparison.map((item, index) => {
                const savingsPercent = ((item.savings.min / item.marketRate.min) * 100).toFixed(0);
                return (
                  <TableRow key={index} hover>
                    <TableCell sx={{ fontWeight: 600 }}>{item.role}</TableCell>
                    <TableCell align="center">
                      {formatPriceRange(item.marketRate)} / {t("common.month")}
                    </TableCell>
                    <TableCell align="center" sx={{ color: "primary.main", fontWeight: 600 }}>
                      {formatPriceRange(item.ourRate)} / {t("common.month")}
                    </TableCell>
                    <TableCell align="center" sx={{ color: "success.main", fontWeight: 600 }}>
                      {formatPriceRange(item.savings)} / {t("common.month")}
                    </TableCell>
                    <TableCell align="center">
                      <Chip label={`-${savingsPercent}%`} size="small" color="success" />
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </TableContainer>
      </Container>
    </Box>
  );
};

export default MarketComparisonTable;
