/**
 * Case Studies Page
 * 
 * Displays detailed case studies with metrics, challenges, solutions, and results
 * Demonstrates real-world impact and value delivered
 */

import React, { useState } from "react";
import {
  Box,
  Container,
  Grid,
  Card,
  CardContent,
  Typography,
  Chip,
  Divider,
  alpha,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  useMediaQuery,
  useTheme,
} from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import TrendingUpIcon from "@mui/icons-material/TrendingUp";
import TrendingDownIcon from "@mui/icons-material/TrendingDown";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import { SectionHeader } from "../components/sections";
import SEO from "../components/SEO";
import { caseStudies, CaseStudy } from "../content/caseStudies";
import { useTranslation } from "react-i18next";

const CaseStudies: React.FC = () => {
  const { t, i18n } = useTranslation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const [selectedStudy, setSelectedStudy] = useState<CaseStudy | null>(null);
  const [openDialog, setOpenDialog] = useState(false);

  const handleOpenDialog = (study: CaseStudy) => {
    setSelectedStudy(study);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedStudy(null);
  };

  return (
    <>
      <SEO
        content={{
          meta: {
            title: t("caseStudies.meta.title"),
            description: t("caseStudies.meta.description"),
            keywords: t("caseStudies.meta.keywords", { returnObjects: true }) as string[],
          },
        }}
      />
      <Box component="main" sx={{ bgcolor: "background.default" }}>
        {/* Hero Section */}
        <Box
          component="section"
          sx={{
            py: { xs: 8, md: 12 },
            bgcolor: "background.paper",
          }}
        >
          <Container maxWidth="lg">
            <SectionHeader
              content={{
                badge: t("caseStudies.hero.badge"),
                title: t("caseStudies.hero.title"),
                description: t("caseStudies.hero.description"),
                alignment: "center",
              }}
            />
          </Container>
        </Box>

        {/* Case Studies Grid */}
        <Box
          component="section"
          sx={{
            py: { xs: 8, md: 12 },
            bgcolor: "background.default",
          }}
        >
          <Container maxWidth="lg">
            <Grid container spacing={4}>
              {caseStudies.map((study) => (
                <Grid size={{ xs: 12, md: 6 }} key={study.id}>
                  <Card
                    sx={{
                      height: "100%",
                      display: "flex",
                      flexDirection: "column",
                      transition: "all 200ms ease",
                      cursor: "pointer",
                      "&:hover": {
                        transform: "translateY(-4px)",
                        boxShadow: "0 8px 16px rgba(0, 0, 0, 0.1)",
                      },
                    }}
                    onClick={() => handleOpenDialog(study)}
                  >
                    <CardContent sx={{ flexGrow: 1, p: 3 }}>
                      {/* Header */}
                      <Box sx={{ mb: 2 }}>
                        {study.featured && (
                          <Chip
                            label={t("caseStudies.labels.featured")}
                            size="small"
                            sx={{
                              mb: 1,
                              bgcolor: alpha("#0ea5e9", 0.1),
                              color: "primary.main",
                              fontWeight: 600,
                            }}
                          />
                        )}
                        <Typography
                          variant="h5"
                          sx={{
                            fontWeight: 600,
                            mb: 1,
                            color: "text.primary",
                          }}
                        >
                          {study.title}
                        </Typography>
                        <Typography
                          variant="body2"
                          sx={{ color: "text.secondary", mb: 0.5 }}
                        >
                          {study.client} • {study.industry}
                        </Typography>
                        <Typography
                          variant="caption"
                          sx={{ color: "text.secondary" }}
                        >
                          {t("caseStudies.labels.duration")}: {study.duration}
                        </Typography>
                      </Box>

                      <Divider sx={{ my: 2 }} />

                      {/* Challenge Preview */}
                      <Typography
                        variant="body2"
                        sx={{
                          color: "text.secondary",
                          mb: 2,
                          display: "-webkit-box",
                          WebkitLineClamp: 3,
                          WebkitBoxOrient: "vertical",
                          overflow: "hidden",
                        }}
                      >
                        <strong>{t("caseStudies.labels.challenge")}:</strong> {study.challenge}
                      </Typography>

                      {/* Key Metrics Preview */}
                      <Box sx={{ mb: 2 }}>
                        <Typography
                          variant="caption"
                          sx={{
                            fontWeight: 600,
                            color: "text.secondary",
                            mb: 1,
                            display: "block",
                          }}
                        >
                          {t("caseStudies.labels.keyResults")}:
                        </Typography>
                        <Box
                          sx={{
                            display: "flex",
                            flexWrap: "wrap",
                            gap: 1,
                          }}
                        >
                          {study.results.metrics.slice(0, 3).map((metric, idx) => (
                            <Chip
                              key={idx}
                              label={`${metric.label}: ${metric.improvement}`}
                              size="small"
                              sx={{
                                bgcolor: alpha("#10b981", 0.1),
                                color: "success.main",
                                fontSize: "0.7rem",
                              }}
                            />
                          ))}
                        </Box>
                      </Box>

                      {/* Tech Stack Preview */}
                      <Box sx={{ mb: 2 }}>
                        <Typography
                          variant="caption"
                          sx={{
                            fontWeight: 600,
                            color: "text.secondary",
                            mb: 0.5,
                            display: "block",
                          }}
                        >
                          {t("caseStudies.labels.techStack")}:
                        </Typography>
                        <Box
                          sx={{
                            display: "flex",
                            flexWrap: "wrap",
                            gap: 0.5,
                          }}
                        >
                          {study.techStack.slice(0, 4).map((tech) => (
                            <Chip
                              key={tech}
                              label={tech}
                              size="small"
                              sx={{
                                fontSize: "0.7rem",
                                height: 24,
                              }}
                            />
                          ))}
                          {study.techStack.length > 4 && (
                            <Chip
                              label={`+${study.techStack.length - 4} ${i18n.language === "vi" ? "khác" : i18n.language === "ja" ? "その他" : "more"}`}
                              size="small"
                              sx={{
                                fontSize: "0.7rem",
                                height: 24,
                              }}
                            />
                          )}
                        </Box>
                      </Box>

                      {/* View Details Button */}
                      <Button
                        endIcon={<ArrowForwardIcon />}
                        sx={{
                          mt: "auto",
                          textTransform: "none",
                          fontWeight: 500,
                        }}
                        onClick={(e) => {
                          e.stopPropagation();
                          handleOpenDialog(study);
                        }}
                      >
                        {t("caseStudies.labels.viewFull")}
                      </Button>
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Container>
        </Box>
      </Box>

      {/* Case Study Detail Dialog */}
      <Dialog
        open={openDialog}
        onClose={handleCloseDialog}
        maxWidth="md"
        fullWidth
        fullScreen={isMobile}
      >
        {selectedStudy && (
          <>
            <DialogTitle>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "flex-start",
                }}
              >
                <Box sx={{ flex: 1 }}>
                  <Typography variant="h5" sx={{ fontWeight: 600, mb: 1 }}>
                    {selectedStudy.title}
                  </Typography>
                  <Typography variant="body2" sx={{ color: "text.secondary" }}>
                    {selectedStudy.client} • {selectedStudy.industry} • {t("caseStudies.labels.duration")}: {selectedStudy.duration}
                  </Typography>
                </Box>
                <IconButton
                  onClick={handleCloseDialog}
                  sx={{ ml: 2 }}
                  aria-label={t("caseStudies.labels.close")}
                >
                  <CloseIcon />
                </IconButton>
              </Box>
            </DialogTitle>
            <DialogContent dividers>
              <Box sx={{ display: "flex", flexDirection: "column", gap: 4 }}>
                {/* Challenge */}
                <Box>
                  <Typography
                    variant="h6"
                    sx={{ fontWeight: 600, mb: 1.5, color: "text.primary" }}
                  >
                    {t("caseStudies.labels.challenge")}
                  </Typography>
                  <Typography variant="body1" sx={{ color: "text.secondary", lineHeight: 1.8 }}>
                    {selectedStudy.challenge}
                  </Typography>
                </Box>

                {/* Solution */}
                <Box>
                  <Typography
                    variant="h6"
                    sx={{ fontWeight: 600, mb: 1.5, color: "text.primary" }}
                  >
                    {t("caseStudies.labels.solution")}
                  </Typography>
                  <Typography variant="body1" sx={{ color: "text.secondary", lineHeight: 1.8 }}>
                    {selectedStudy.solution}
                  </Typography>
                </Box>

                {/* Results */}
                <Box>
                  <Typography
                    variant="h6"
                    sx={{ fontWeight: 600, mb: 1.5, color: "text.primary" }}
                  >
                    {t("caseStudies.labels.results")}
                  </Typography>
                  <Typography
                    variant="body1"
                    sx={{
                      color: "text.secondary",
                      mb: 2,
                      fontWeight: 500,
                      lineHeight: 1.8,
                    }}
                  >
                    {selectedStudy.results.summary}
                  </Typography>

                  {/* Metrics Table */}
                  <Box
                    sx={{
                      mt: 3,
                      borderRadius: 2,
                      border: "1px solid",
                      borderColor: "divider",
                      overflow: "hidden",
                    }}
                  >
                    {selectedStudy.results.metrics.map((metric, idx) => {
                      const isImprovement = metric.improvement.includes("+") || 
                                           metric.improvement.includes("faster") ||
                                           metric.improvement.includes("New");
                      return (
                        <Box
                          key={idx}
                          sx={{
                            p: 2,
                            borderBottom:
                              idx < selectedStudy.results.metrics.length - 1
                                ? "1px solid"
                                : "none",
                            borderColor: "divider",
                            bgcolor: idx % 2 === 0 ? "background.paper" : alpha("#f1f5f9", 0.3),
                            display: "flex",
                            justifyContent: "space-between",
                            alignItems: "center",
                          }}
                        >
                          <Box sx={{ flex: 1 }}>
                            <Typography
                              variant="body2"
                              sx={{ fontWeight: 600, mb: 0.5 }}
                            >
                              {metric.label}
                            </Typography>
                            <Box
                              sx={{
                                display: "flex",
                                gap: 2,
                                alignItems: "center",
                              }}
                            >
                              <Typography
                                variant="body2"
                                sx={{ color: "text.secondary" }}
                              >
                                {t("caseStudies.labels.before")}: {metric.before} {metric.unit || ""}
                              </Typography>
                              <Typography
                                variant="body2"
                                sx={{ color: "text.secondary" }}
                              >
                                {t("caseStudies.labels.after")}: {metric.after} {metric.unit || ""}
                              </Typography>
                            </Box>
                          </Box>
                          <Box
                            sx={{
                              display: "flex",
                              alignItems: "center",
                              gap: 0.5,
                              ml: 2,
                            }}
                          >
                            {isImprovement ? (
                              <TrendingUpIcon sx={{ color: "success.main", fontSize: 20 }} />
                            ) : (
                              <TrendingDownIcon sx={{ color: "error.main", fontSize: 20 }} />
                            )}
                            <Typography
                              variant="body2"
                              sx={{
                                fontWeight: 600,
                                color: isImprovement ? "success.main" : "error.main",
                                minWidth: 80,
                                textAlign: "right",
                              }}
                            >
                              {metric.improvement}
                            </Typography>
                          </Box>
                        </Box>
                      );
                    })}
                  </Box>
                </Box>

                {/* Tech Stack */}
                <Box>
                  <Typography
                    variant="h6"
                    sx={{ fontWeight: 600, mb: 1.5, color: "text.primary" }}
                  >
                    {t("caseStudies.labels.techStack")}
                  </Typography>
                  <Box
                    sx={{
                      display: "flex",
                      flexWrap: "wrap",
                      gap: 1,
                    }}
                  >
                    {selectedStudy.techStack.map((tech) => (
                      <Chip
                        key={tech}
                        label={tech}
                        sx={{
                          fontWeight: 500,
                        }}
                      />
                    ))}
                  </Box>
                </Box>

                {/* Testimonial */}
                {selectedStudy.testimonial && (
                  <Box
                    sx={{
                      p: 3,
                      borderRadius: 2,
                      bgcolor: alpha("#f1f5f9", 0.5),
                      borderLeft: "4px solid",
                      borderColor: "primary.main",
                    }}
                  >
                    <Typography
                      variant="h6"
                      sx={{ fontWeight: 600, mb: 1.5, color: "text.primary" }}
                    >
                      {t("caseStudies.labels.testimonial")}
                    </Typography>
                    <Typography
                      variant="body1"
                      sx={{
                        fontStyle: "italic",
                        color: "text.secondary",
                        mb: 2,
                        lineHeight: 1.8,
                      }}
                    >
                      "{selectedStudy.testimonial.quote}"
                    </Typography>
                    <Typography
                      variant="body2"
                      sx={{ fontWeight: 600, color: "text.primary" }}
                    >
                      {selectedStudy.testimonial.author}
                    </Typography>
                    <Typography
                      variant="caption"
                      sx={{ color: "text.secondary" }}
                    >
                      {selectedStudy.testimonial.role}, {selectedStudy.testimonial.company}
                    </Typography>
                  </Box>
                )}
              </Box>
            </DialogContent>
            <DialogActions>
              <Button onClick={handleCloseDialog} variant="contained">
                {t("caseStudies.labels.close")}
              </Button>
            </DialogActions>
          </>
        )}
      </Dialog>
    </>
  );
};

export default CaseStudies;
