/**
 * Blog Detail Page
 * 
 * Displays full article content with related articles
 */

import React, { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import {
  Box,
  Container,
  Typography,
  Button,
  Chip,
  Divider,
  alpha,
  Grid,
  IconButton,
  Tooltip,
} from "@mui/material";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import AccessTimeIcon from "@mui/icons-material/AccessTime";
import PersonIcon from "@mui/icons-material/Person";
import VisibilityIcon from "@mui/icons-material/Visibility";
import FacebookIcon from "@mui/icons-material/Facebook";
import TwitterIcon from "@mui/icons-material/Twitter";
import LinkedInIcon from "@mui/icons-material/LinkedIn";
import LinkIcon from "@mui/icons-material/Link";
import { ArticleCard } from "../components/cards";
import SEO from "../components/SEO";
import Breadcrumbs from "../components/Breadcrumbs";
import { generateArticleSchema, generateBreadcrumbSchema } from "../utils/seo";
import { useBlogContent } from "../utils/contentHelper";
import { useTranslation } from "react-i18next";
import { formatBlogDate } from "../utils/dateUtils";

const BlogDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [readingProgress, setReadingProgress] = useState(0);
  const blogContent = useBlogContent();
  const { t, i18n } = useTranslation();

  // Reading progress calculation
  useEffect(() => {
    const handleScroll = () => {
      const windowHeight = window.innerHeight;
      const documentHeight = document.documentElement.scrollHeight;
      const scrollTop = window.scrollY;
      const progress = (scrollTop / (documentHeight - windowHeight)) * 100;
      setReadingProgress(Math.min(100, Math.max(0, progress)));
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Find article by ID
  const article = blogContent.articles.find((a) => a.id === id);

  // Social sharing functions
  const shareUrl = typeof window !== "undefined" ? window.location.href : "";
  const shareTitle = article?.title || "";

  const handleShare = (platform: string) => {
    const url = encodeURIComponent(shareUrl);
    const title = encodeURIComponent(shareTitle);

    let shareLink = "";
    switch (platform) {
      case "facebook":
        shareLink = `https://www.facebook.com/sharer/sharer.php?u=${url}`;
        break;
      case "twitter":
        shareLink = `https://twitter.com/intent/tweet?url=${url}&text=${title}`;
        break;
      case "linkedin":
        shareLink = `https://www.linkedin.com/sharing/share-offsite/?url=${url}`;
        break;
      case "copy":
        navigator.clipboard.writeText(shareUrl);
        return;
    }

    if (shareLink) {
      window.open(shareLink, "_blank", "width=600,height=400");
    }
  };

  // If article not found, show 404
  if (!article) {
    return (
      <>
        <SEO
          content={{
            meta: {
              title: `${t("blog.detail.notFound.title")} | Blog`,
              description: t("blog.detail.notFound.description"),
              keywords: [],
            },
          }}
        />
        <Box component="main" sx={{ bgcolor: "background.default", minHeight: "60vh" }}>
          <Container maxWidth="lg" sx={{ py: 12, textAlign: "center" }}>
            <Typography variant="h4" sx={{ mb: 2, color: "text.primary" }}>
              {t("blog.detail.notFound.title")}
            </Typography>
            <Typography sx={{ mb: 4, color: "text.secondary" }}>
              {t("blog.detail.notFound.description")}
            </Typography>
            <Button component={Link} to="/blog" variant="contained" startIcon={<ArrowBackIcon />}>
              {t("blog.detail.notFound.backButton")}
            </Button>
          </Container>
        </Box>
      </>
    );
  }

  const categoryLabels: Record<string, string> = t("blog.categories", { returnObjects: true }) as Record<string, string>;

  // Smart related articles algorithm
  const getRelatedArticles = (currentArticle: typeof article, allArticles: typeof blogContent.articles, limit: number = 6) => {
    const calculateScore = (current: typeof article, candidate: typeof article): number => {
      let score = 0;
      
      // Same category: +30 points
      if (current.category === candidate.category) {
        score += 30;
      }
      
      // Shared tags: +10 points per tag
      const sharedTags = current.tags.filter((tag: string) => candidate.tags.includes(tag));
      score += sharedTags.length * 10;
      
      // Featured articles: +5 points
      if (candidate.featured) {
        score += 5;
      }
      
      // Recent articles: +3 points (within 3 months)
      const currentDate = new Date(current.publishedAt);
      const candidateDate = new Date(candidate.publishedAt);
      const monthsDiff = (currentDate.getTime() - candidateDate.getTime()) / (1000 * 60 * 60 * 24 * 30);
      if (monthsDiff <= 3 && monthsDiff >= -3) {
        score += 3;
      }
      
      return score;
    };

    // Calculate scores for all articles
    const scored = allArticles
      .filter((a) => a.id !== currentArticle.id)
      .map((candidate) => ({
        article: candidate,
        score: calculateScore(currentArticle, candidate),
      }))
      .sort((a, b) => b.score - a.score);

    // Get top scored articles
    const topScored = scored.slice(0, limit).map((s) => s.article);

    // Fallback: If not enough, add random articles from other categories
    if (topScored.length < 3) {
      const fallback = allArticles
        .filter(
          (a) =>
            a.id !== currentArticle.id &&
            !topScored.some((ta) => ta.id === a.id)
        )
        .slice(0, 3 - topScored.length);
      topScored.push(...fallback);
    }

    return topScored;
  };

  const relatedArticles = getRelatedArticles(article, blogContent.articles, 6);

  // Breadcrumbs
  const breadcrumbs = [
    { label: t("nav.home"), path: "/" },
    { label: t("nav.blog"), path: "/blog" },
    { label: article.title, path: `/blog/${article.id}` },
  ];

  // Generate schemas
  const articleSchema = generateArticleSchema(
    article.title,
    article.excerpt,
    article.author,
    article.publishedAt,
    shareUrl,
    article.image
  );
  const breadcrumbSchema = generateBreadcrumbSchema(
    breadcrumbs.map((b) => ({
      name: b.label,
      url: b.path,
    }))
  );

  return (
    <>
      <SEO
        content={{
          meta: {
            title: `${article.title} | Blog - Nguyễn Văn An`,
            description: article.excerpt,
            keywords: article.tags,
          },
        }}
        structuredData={[articleSchema, breadcrumbSchema]}
      />
      <Box component="main" sx={{ bgcolor: "background.default", position: "relative" }}>
        {/* Reading Progress Bar */}
        <Box
          sx={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            height: 3,
            bgcolor: alpha("#475569", 0.1),
            zIndex: 1300,
          }}
        >
          <Box
            sx={{
              height: "100%",
              bgcolor: "primary.main",
              width: `${readingProgress}%`,
              transition: "width 0.1s ease",
            }}
          />
        </Box>

        {/* Back Button & Breadcrumbs */}
        <Box
          sx={{
            py: 3,
            borderBottom: "1px solid",
            borderColor: "divider",
            bgcolor: "background.paper",
          }}
        >
          <Container maxWidth="lg">
            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 2 }}>
              <Button
                startIcon={<ArrowBackIcon />}
                onClick={() => navigate("/blog")}
                sx={{ color: "text.secondary" }}
              >
                {t("blog.detail.backButton")}
              </Button>
              <Breadcrumbs items={breadcrumbs.slice(0, -1)} />
            </Box>
          </Container>
        </Box>

        {/* Article Content */}
        <Box
          component="article"
          sx={{
            py: { xs: 6, md: 10 },
            bgcolor: "background.default",
          }}
        >
          <Container maxWidth="md">
            {/* Category & Date */}
            <Box sx={{ display: "flex", gap: 2, alignItems: "center", mb: 3, flexWrap: "wrap" }}>
              <Chip
                label={categoryLabels[article.category] || article.category}
                size="small"
                sx={{
                  bgcolor: article.featured ? alpha("#f1f5f9", 0.8) : alpha("#f8fafc", 0.8),
                  color: "text.secondary",
                  fontSize: "0.875rem",
                  height: 28,
                }}
              />
              <Typography variant="caption" sx={{ color: "text.secondary", fontSize: "0.875rem" }}>
                {formatBlogDate(article.publishedAt, i18n.language)}
              </Typography>
              {article.views && (
                <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
                  <VisibilityIcon sx={{ fontSize: 16, color: "text.secondary" }} />
                  <Typography variant="caption" sx={{ color: "text.secondary", fontSize: "0.875rem" }}>
                    {article.views.toLocaleString()} {t("blog.detail.views")}
                  </Typography>
                </Box>
              )}
            </Box>

            {/* Title */}
            <Typography
              component="h1"
              variant="h3"
              sx={{
                fontWeight: 700,
                mb: 3,
                color: "text.primary",
                fontSize: { xs: "2rem", md: "2.75rem" },
                lineHeight: 1.2,
              }}
            >
              {article.title}
            </Typography>

            {/* Meta Info */}
            <Box
              sx={{
                display: "flex",
                gap: 3,
                alignItems: "center",
                mb: 4,
                flexWrap: "wrap",
                pb: 3,
                borderBottom: "1px solid",
                borderColor: "divider",
              }}
            >
              <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                <PersonIcon sx={{ fontSize: 18, color: "text.secondary" }} />
                <Typography variant="body2" sx={{ color: "text.secondary" }}>
                  {article.author}
                </Typography>
              </Box>
              <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                <AccessTimeIcon sx={{ fontSize: 18, color: "text.secondary" }} />
                <Typography variant="body2" sx={{ color: "text.secondary" }}>
                  {article.readTime} {t("blog.detail.readTime")}
                </Typography>
              </Box>
            </Box>

            {/* Tags & Social Sharing */}
            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 2, mb: 4 }}>
              {article.tags && article.tags.length > 0 && (
                <Box sx={{ display: "flex", flexWrap: "wrap", gap: 1 }}>
                  {article.tags.map((tag: string) => (
                    <Chip
                      key={tag}
                      label={tag}
                      size="small"
                      sx={{
                        bgcolor: "transparent",
                        color: "text.secondary",
                        fontSize: "0.8125rem",
                        height: 28,
                        border: "1px solid",
                        borderColor: "divider",
                      }}
                    />
                  ))}
                </Box>
              )}
              
              {/* Social Sharing Buttons */}
              <Box sx={{ display: "flex", gap: 1 }}>
                <Tooltip title={t("blog.detail.share.facebook")}>
                  <IconButton
                    size="small"
                    onClick={() => handleShare("facebook")}
                    sx={{
                      color: "text.secondary",
                      "&:hover": { color: "#1877F2", bgcolor: alpha("#1877F2", 0.1) },
                    }}
                  >
                    <FacebookIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
                <Tooltip title={t("blog.detail.share.twitter")}>
                  <IconButton
                    size="small"
                    onClick={() => handleShare("twitter")}
                    sx={{
                      color: "text.secondary",
                      "&:hover": { color: "#1DA1F2", bgcolor: alpha("#1DA1F2", 0.1) },
                    }}
                  >
                    <TwitterIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
                <Tooltip title={t("blog.detail.share.linkedin")}>
                  <IconButton
                    size="small"
                    onClick={() => handleShare("linkedin")}
                    sx={{
                      color: "text.secondary",
                      "&:hover": { color: "#0077B5", bgcolor: alpha("#0077B5", 0.1) },
                    }}
                  >
                    <LinkedInIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
                <Tooltip title={t("blog.detail.share.copy")}>
                  <IconButton
                    size="small"
                    onClick={() => handleShare("copy")}
                    sx={{
                      color: "text.secondary",
                      "&:hover": { color: "primary.main", bgcolor: alpha("#475569", 0.1) },
                    }}
                  >
                    <LinkIcon fontSize="small" />
                  </IconButton>
                </Tooltip>
              </Box>
            </Box>

            {/* Featured Image */}
            {article.image && (
              <Box
                sx={{
                  mb: 5,
                  borderRadius: 2,
                  overflow: "hidden",
                  bgcolor: "background.paper",
                  border: "1px solid",
                  borderColor: "divider",
                }}
              >
                <Box
                  component="img"
                  src={article.image}
                  alt={article.title}
                  sx={{
                    width: "100%",
                    height: "auto",
                    display: "block",
                  }}
                />
              </Box>
            )}

            {/* Article Content */}
            <Box
              sx={{
                "& p": {
                  mb: 3,
                  fontSize: "1.125rem",
                  lineHeight: 1.8,
                  color: "text.secondary",
                },
                "& h2": {
                  mt: 5,
                  mb: 3,
                  fontSize: "1.875rem",
                  fontWeight: 600,
                  color: "text.primary",
                },
                "& h3": {
                  mt: 4,
                  mb: 2,
                  fontSize: "1.5rem",
                  fontWeight: 600,
                  color: "text.primary",
                },
                "& ul, & ol": {
                  mb: 3,
                  pl: 4,
                  "& li": {
                    mb: 1.5,
                    fontSize: "1.125rem",
                    lineHeight: 1.8,
                    color: "text.secondary",
                  },
                },
                "& code": {
                  bgcolor: alpha("#f1f5f9", 0.8),
                  px: 1,
                  py: 0.5,
                  borderRadius: 1,
                  fontSize: "0.9375rem",
                  fontFamily: "monospace",
                },
                "& pre": {
                  bgcolor: "background.paper",
                  p: 3,
                  borderRadius: 2,
                  border: "1px solid",
                  borderColor: "divider",
                  overflow: "auto",
                  mb: 3,
                  "& code": {
                    bgcolor: "transparent",
                    p: 0,
                  },
                },
                "& blockquote": {
                  borderLeft: "4px solid",
                  borderColor: "primary.main",
                  pl: 3,
                  py: 2,
                  my: 3,
                  bgcolor: alpha("#f1f5f9", 0.3),
                  fontStyle: "italic",
                  color: "text.secondary",
                },
              }}
            >
              {article.content ? (
                <div dangerouslySetInnerHTML={{ __html: article.content }} />
              ) : (
                <Typography
                  component="p"
                  sx={{
                    fontSize: "1.125rem",
                    lineHeight: 1.8,
                    color: "text.secondary",
                  }}
                >
                  {article.excerpt}
                </Typography>
              )}
            </Box>

            <Divider sx={{ my: 6, borderColor: "divider" }} />

            {/* Author Info */}
            <Box
              sx={{
                p: 4,
                bgcolor: "background.paper",
                borderRadius: 2,
                border: "1px solid",
                borderColor: "divider",
                mb: 6,
              }}
            >
              <Typography
                component="h3"
                sx={{
                  fontWeight: 600,
                  mb: 2,
                  color: "text.primary",
                  fontSize: "1.25rem",
                }}
              >
                {t("blog.detail.author.title")}
              </Typography>
              <Typography sx={{ color: "text.secondary", lineHeight: 1.7 }}>
                {article.author} {t("blog.detail.author.description")}
              </Typography>
            </Box>
          </Container>
        </Box>

        {/* Related Articles */}
        {relatedArticles.length > 0 && (
          <>
            <Divider sx={{ borderColor: "divider" }} />
            <Box
              component="section"
              sx={{
                py: { xs: 8, md: 12 },
                bgcolor: "background.paper",
              }}
            >
              <Container maxWidth="lg">
                <Typography
                  component="h2"
                  variant="h4"
                  sx={{
                    fontWeight: 600,
                    mb: 4,
                    color: "text.primary",
                    textAlign: "center",
                  }}
                >
                  {t("blog.detail.relatedArticles")}
                </Typography>
                <Grid container spacing={4}>
                  {relatedArticles.map((relatedArticle) => (
                    <Grid size={{ xs: 12, md: 4 }} key={relatedArticle.id}>
                      <ArticleCard article={relatedArticle} />
                    </Grid>
                  ))}
                </Grid>
              </Container>
            </Box>
          </>
        )}
      </Box>
    </>
  );
};

export default BlogDetail;
