/**
 * Savings Calculator Component
 * 
 * Interactive calculator to calculate savings
 */

import React, { useState, useMemo } from "react";
import {
  Box,
  Container,
  Typography,
  Paper,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Grid,
  Card,
  CardContent,
  Button,
  Divider,
  alpha,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import { rolePricing } from "../../content/pricing";
import {
  calculateTotalCost,
  getDiscountForDuration,
  hasFirstMonthDiscount,
} from "../../utils/pricingUtils";
import { SectionHeader } from "../sections";
import { useCurrency } from "../../contexts/CurrencyContext";

const SavingsCalculator: React.FC = () => {
  const { t } = useTranslation();
  const { formatPrice } = useCurrency();
  const [selectedRoleId, setSelectedRoleId] = useState<string>("developer");
  const [selectedLevel, setSelectedLevel] = useState<"junior" | "mid" | "senior" | "lead" | "principal">("mid");
  const [duration, setDuration] = useState<number>(6);

  const selectedRole = rolePricing.find((r) => r.id === selectedRoleId) || rolePricing[3];
  const priceRange = selectedRole[selectedLevel];

  const calculation = useMemo(() => {
    if (!priceRange) {
      return null;
    }

    const basePrice = priceRange.min; // Use min for calculation
    const marketPrice = priceRange.marketMin;

    const firstMonthDiscount = hasFirstMonthDiscount(duration) ? 0.25 : 0;
    const firstMonthPrice = firstMonthDiscount > 0 ? basePrice * 0.75 : basePrice;

    const monthlyDiscount = getDiscountForDuration(duration);
    const monthlyPrice = basePrice * (1 - monthlyDiscount);

    const totalCost = calculateTotalCost(basePrice, duration, firstMonthDiscount);
    const marketTotal = marketPrice * duration;
    const savings = marketTotal - totalCost;
    const savingsPercentage = (savings / marketTotal) * 100;

    return {
      basePrice,
      marketPrice,
      firstMonthPrice,
      monthlyPrice,
      totalCost,
      marketTotal,
      savings,
      savingsPercentage,
      firstMonthDiscount,
      monthlyDiscount,
    };
  }, [priceRange, duration]);

  if (!calculation) {
    return null;
  }

  return (
    <Box component="section" sx={{ py: { xs: 6, md: 8 }, bgcolor: alpha("#f1f5f9", 0.3) }}>
      <Container maxWidth="md">
        <SectionHeader
          content={{
            badge: "",
            title: t("pricing.calculator.title"),
            description: "",
            alignment: "center",
          }}
        />

        <Paper
          elevation={3}
          sx={{
            mt: 6,
            p: { xs: 3, md: 4 },
            borderRadius: 2,
            border: "1px solid",
            borderColor: "divider",
          }}
        >
          <Grid container spacing={3}>
            <Grid size={{ xs: 12, md: 4 }}>
              <FormControl fullWidth>
                <InputLabel>{t("pricing.calculator.selectRole")}</InputLabel>
                <Select
                  value={selectedRoleId}
                  label={t("pricing.calculator.selectRole")}
                  onChange={(e) => setSelectedRoleId(e.target.value)}
                >
                  {rolePricing.map((role) => {
                    const roleMap: { [key: string]: string } = {
                      'ba': 'businessAnalyst',
                      'system-analyst': 'systemAnalyst',
                      'ui-ux': 'uiUxDesigner',
                      'developer': 'developer',
                      'qa': 'qaEngineer',
                      'devops': 'devopsEngineer',
                      'pm': 'projectManager',
                      'tech-lead': 'technicalLead',
                    };
                    const translationKey = roleMap[role.id] || role.id;
                    return (
                      <MenuItem key={role.id} value={role.id}>
                        {t(`pricing.roles.${translationKey}`) || role.name}
                      </MenuItem>
                    );
                  })}
                </Select>
              </FormControl>
            </Grid>

            <Grid size={{ xs: 12, md: 4 }}>
              <FormControl fullWidth>
                <InputLabel>{t("pricing.calculator.selectLevel")}</InputLabel>
                <Select
                  value={selectedLevel}
                  label={t("pricing.calculator.selectLevel")}
                  onChange={(e) =>
                    setSelectedLevel(e.target.value as "junior" | "mid" | "senior" | "lead" | "principal")
                  }
                >
                  {selectedRole.junior && (
                    <MenuItem value="junior">{t("pricing.levels.junior")}</MenuItem>
                  )}
                  <MenuItem value="mid">{t("pricing.levels.mid")}</MenuItem>
                  <MenuItem value="senior">{t("pricing.levels.senior")}</MenuItem>
                  {selectedRole.lead && <MenuItem value="lead">{t("pricing.levels.lead")}</MenuItem>}
                  {selectedRole.principal && (
                    <MenuItem value="principal">{t("pricing.levels.principal")}</MenuItem>
                  )}
                </Select>
              </FormControl>
            </Grid>

            <Grid size={{ xs: 12, md: 4 }}>
              <FormControl fullWidth>
                <InputLabel>{t("pricing.calculator.selectDuration")}</InputLabel>
                <Select
                  value={duration}
                  label={t("pricing.calculator.selectDuration")}
                  onChange={(e) => setDuration(Number(e.target.value))}
                >
                  <MenuItem value={1}>1 {t("common.month")}</MenuItem>
                  <MenuItem value={3}>3 {t("common.months")}</MenuItem>
                  <MenuItem value={6}>6 {t("common.months")}</MenuItem>
                  <MenuItem value={12}>12 {t("common.months")}</MenuItem>
                </Select>
              </FormControl>
            </Grid>
          </Grid>

          <Divider sx={{ my: 4 }} />

          <Grid container spacing={2}>
            <Grid size={{ xs: 12, sm: 6 }}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="body2" color="text.secondary" gutterBottom>
                    {t("pricing.calculator.basePrice")}
                  </Typography>
                  <Typography variant="h6" sx={{ fontWeight: 600 }}>
                    {formatPrice(calculation.basePrice)} / {t("common.month")}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            {calculation.firstMonthDiscount > 0 && (
              <Grid size={{ xs: 12, sm: 6 }}>
                <Card variant="outlined" sx={{ bgcolor: alpha("#0ea5e9", 0.05) }}>
                  <CardContent>
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      {t("pricing.calculator.firstMonth")} (25% OFF)
                    </Typography>
                    <Typography variant="h6" sx={{ fontWeight: 600, color: "primary.main" }}>
                      {formatPrice(calculation.firstMonthPrice)}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            )}

            {calculation.monthlyDiscount > 0 && (
              <Grid size={{ xs: 12, sm: 6 }}>
                <Card variant="outlined" sx={{ bgcolor: alpha("#0ea5e9", 0.05) }}>
                  <CardContent>
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      {t("pricing.calculator.monthlyDiscount")} ({calculation.monthlyDiscount * 100}% OFF)
                    </Typography>
                    <Typography variant="h6" sx={{ fontWeight: 600, color: "primary.main" }}>
                      {formatPrice(calculation.monthlyPrice)} / {t("common.month")}
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            )}

            <Grid size={{ xs: 12, sm: 6 }}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="body2" color="text.secondary" gutterBottom>
                    {t("pricing.calculator.totalCost")}
                  </Typography>
                  <Typography variant="h6" sx={{ fontWeight: 600 }}>
                    {formatPrice(calculation.totalCost)}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid size={{ xs: 12, sm: 6 }}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="body2" color="text.secondary" gutterBottom>
                    {t("pricing.calculator.marketRate")}
                  </Typography>
                  <Typography variant="h6" sx={{ fontWeight: 600, color: "text.secondary" }}>
                    {formatPrice(calculation.marketTotal)}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid size={{ xs: 12 }}>
              <Card
                variant="outlined"
                sx={{
                  bgcolor: alpha("#10b981", 0.15),
                  borderColor: "success.main",
                  borderWidth: 3,
                  boxShadow: `0 4px 12px ${alpha("#10b981", 0.2)}`,
                  position: "relative",
                  overflow: "hidden",
                  "&::before": {
                    content: '""',
                    position: "absolute",
                    top: 0,
                    left: 0,
                    right: 0,
                    height: "4px",
                    bgcolor: "success.main",
                  },
                }}
              >
                <CardContent sx={{ p: { xs: 3, sm: 4 } }}>
                  <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center" }}>
                    <Typography 
                      variant="body1" 
                      sx={{ 
                        color: "text.secondary", 
                        mb: 1.5,
                        fontWeight: 600,
                        fontSize: "1rem",
                      }}
                    >
                      {t("pricing.calculator.youSave")}
                    </Typography>
                    <Typography 
                      variant="h3" 
                      sx={{ 
                        fontWeight: 700, 
                        color: "success.main",
                        mb: 1,
                        fontSize: { xs: "2rem", sm: "2.5rem", md: "3rem" },
                        lineHeight: 1.2,
                      }}
                    >
                      {formatPrice(calculation.savings)}
                    </Typography>
                    <Typography 
                      variant="h6" 
                      sx={{ 
                        color: "success.main", 
                        fontWeight: 600,
                        fontSize: { xs: "1.125rem", sm: "1.25rem" },
                      }}
                    >
                      ({calculation.savingsPercentage.toFixed(1)}%)
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          <Box sx={{ display: "flex", gap: 2, mt: 4, flexDirection: { xs: "column", sm: "row" } }}>
            <Button
              component={Link}
              to="/job-request"
              variant="contained"
              size="large"
              fullWidth={false}
              sx={{ flex: 1 }}
            >
              {t("pricing.calculator.getQuote")}
            </Button>
            <Button
              component={Link}
              to="/contact"
              variant="outlined"
              size="large"
              fullWidth={false}
              sx={{ flex: 1 }}
            >
              {t("pricing.calculator.contactUs")}
            </Button>
          </Box>
        </Paper>
      </Container>
    </Box>
  );
};

export default SavingsCalculator;
