/**
 * Workflow Process Section
 * 
 * Displays 6-step workflow process from requirement gathering to maintenance
 * Critical for Japanese market - they fear ambiguity, need clear process
 */

import React from "react";
import { Box, Container, Typography, Stepper, Step, StepLabel, StepContent, Grid, alpha } from "@mui/material";
import { useTranslation } from "react-i18next";
import SectionHeader from "./SectionHeader";
import AssignmentIcon from "@mui/icons-material/Assignment";
import DescriptionIcon from "@mui/icons-material/Description";
import DesignServicesIcon from "@mui/icons-material/DesignServices";
import CodeIcon from "@mui/icons-material/Code";
import BugReportIcon from "@mui/icons-material/BugReport";
import DeliveryDiningIcon from "@mui/icons-material/DeliveryDining";

const WorkflowProcessSection: React.FC = () => {
  const { t } = useTranslation();

  const steps = [
    {
      id: "requirement-gathering",
      icon: <AssignmentIcon sx={{ fontSize: 28, color: "primary.main" }} />,
      title: t("workflow.steps.requirementGathering.title"),
      duration: t("workflow.steps.requirementGathering.duration"),
      description: t("workflow.steps.requirementGathering.description"),
      deliverables: t("workflow.steps.requirementGathering.deliverables", { returnObjects: true }) as string[],
    },
    {
      id: "proposal-estimation",
      icon: <DescriptionIcon sx={{ fontSize: 28, color: "primary.main" }} />,
      title: t("workflow.steps.proposalEstimation.title"),
      duration: t("workflow.steps.proposalEstimation.duration"),
      description: t("workflow.steps.proposalEstimation.description"),
      deliverables: t("workflow.steps.proposalEstimation.deliverables", { returnObjects: true }) as string[],
    },
    {
      id: "design-planning",
      icon: <DesignServicesIcon sx={{ fontSize: 28, color: "primary.main" }} />,
      title: t("workflow.steps.designPlanning.title"),
      duration: t("workflow.steps.designPlanning.duration"),
      description: t("workflow.steps.designPlanning.description"),
      deliverables: t("workflow.steps.designPlanning.deliverables", { returnObjects: true }) as string[],
    },
    {
      id: "development",
      icon: <CodeIcon sx={{ fontSize: 28, color: "primary.main" }} />,
      title: t("workflow.steps.development.title"),
      duration: t("workflow.steps.development.duration"),
      description: t("workflow.steps.development.description"),
      deliverables: t("workflow.steps.development.deliverables", { returnObjects: true }) as string[],
    },
    {
      id: "testing-qa",
      icon: <BugReportIcon sx={{ fontSize: 28, color: "primary.main" }} />,
      title: t("workflow.steps.testingQa.title"),
      duration: t("workflow.steps.testingQa.duration"),
      description: t("workflow.steps.testingQa.description"),
      deliverables: t("workflow.steps.testingQa.deliverables", { returnObjects: true }) as string[],
    },
    {
      id: "delivery-maintenance",
      icon: <DeliveryDiningIcon sx={{ fontSize: 28, color: "primary.main" }} />,
      title: t("workflow.steps.deliveryMaintenance.title"),
      duration: t("workflow.steps.deliveryMaintenance.duration"),
      description: t("workflow.steps.deliveryMaintenance.description"),
      deliverables: t("workflow.steps.deliveryMaintenance.deliverables", { returnObjects: true }) as string[],
    },
  ];

  return (
    <Box
      component="section"
      sx={{
        py: { xs: 12, md: 16 },
        bgcolor: "background.paper",
      }}
    >
      <Container maxWidth="lg">
        <SectionHeader
          content={{
            badge: t("workflow.badge"),
            title: t("workflow.title"),
            description: t("workflow.description"),
            alignment: "center",
          }}
        />

        <Box sx={{ mt: 6, maxWidth: "900px", mx: "auto" }}>
          <Stepper orientation="vertical" sx={{ position: "relative" }}>
            {steps.map((step, index) => (
              <Step key={step.id} active={true} completed={false}>
                <StepLabel
                  icon={step.icon}
                  sx={{
                    "& .MuiStepLabel-label": {
                      fontSize: "1.125rem",
                      fontWeight: 600,
                      color: "text.primary",
                    },
                    "& .MuiStepLabel-iconContainer": {
                      paddingRight: 2,
                    },
                  }}
                >
                  <Box sx={{ display: "flex", alignItems: "center", gap: 2, flexWrap: "wrap" }}>
                    <Typography
                      component="span"
                      sx={{
                        fontWeight: 600,
                        fontSize: "1.125rem",
                        color: "text.primary",
                      }}
                    >
                      {step.title}
                    </Typography>
                    <Typography
                      component="span"
                      variant="caption"
                      sx={{
                        color: "text.secondary",
                        fontSize: "0.875rem",
                        bgcolor: alpha("#f1f5f9", 0.8),
                        px: 1.5,
                        py: 0.5,
                        borderRadius: 1,
                        border: "1px solid",
                        borderColor: "divider",
                      }}
                    >
                      {step.duration}
                    </Typography>
                  </Box>
                </StepLabel>
                <StepContent>
                  <Box
                    sx={{
                      mt: 2,
                      mb: 4,
                      pl: { xs: 0, md: 8 },
                    }}
                  >
                    <Typography
                      sx={{
                        color: "text.secondary",
                        mb: 2,
                        fontSize: "0.9375rem",
                        lineHeight: 1.7,
                      }}
                    >
                      {step.description}
                    </Typography>
                    {step.deliverables && step.deliverables.length > 0 && (
                      <Box>
                        <Typography
                          variant="caption"
                          sx={{
                            color: "text.secondary",
                            fontSize: "0.8125rem",
                            fontWeight: 600,
                            display: "block",
                            mb: 1,
                          }}
                        >
                          {t("workflow.deliverables")}:
                        </Typography>
                        <Grid container spacing={1}>
                          {step.deliverables.map((deliverable, idx) => (
                            <Grid size={{ xs: 12, sm: 6 }} key={`${step.id}-deliverable-${idx}`}>
                              <Box
                                sx={{
                                  display: "flex",
                                  alignItems: "flex-start",
                                  gap: 1,
                                  p: 1.5,
                                  bgcolor: alpha("#f8fafc", 0.5),
                                  borderRadius: 1,
                                  border: "1px solid",
                                  borderColor: "divider",
                                }}
                              >
                                <Typography
                                  component="span"
                                  sx={{
                                    color: "primary.main",
                                    fontSize: "0.75rem",
                                    mt: 0.5,
                                  }}
                                >
                                  ✓
                                </Typography>
                                <Typography
                                  variant="caption"
                                  sx={{
                                    color: "text.secondary",
                                    fontSize: "0.8125rem",
                                    lineHeight: 1.6,
                                  }}
                                >
                                  {deliverable}
                                </Typography>
                              </Box>
                            </Grid>
                          ))}
                        </Grid>
                      </Box>
                    )}
                  </Box>
                </StepContent>
              </Step>
            ))}
          </Stepper>
        </Box>
      </Container>
    </Box>
  );
};

export default WorkflowProcessSection;
