/**
 * Testimonial Card Component
 * 
 * Displays client testimonials with rating, avatar, and content
 */

import React from "react";
import { useTranslation } from "react-i18next";
import { Card, CardContent, Box, Typography, Avatar, alpha } from "@mui/material";
import StarIcon from "@mui/icons-material/Star";
import VerifiedIcon from "@mui/icons-material/Verified";

export interface TestimonialContent {
  id: string;
  name: string;
  position: string;
  company: string;
  avatar?: string;
  rating: number;
  content: string;
  project?: string;
  verified?: boolean;
}

interface TestimonialCardProps {
  testimonial: TestimonialContent;
  className?: string;
}

const TestimonialCard: React.FC<TestimonialCardProps> = ({
  testimonial,
  className,
}) => {
  const { t } = useTranslation();
  const { name, position, company, avatar, rating, content, project, verified } = testimonial;

  // Generate avatar initials if no avatar
  const getInitials = (name: string) => {
    return name
      .split(" ")
      .map((n) => n[0])
      .join("")
      .toUpperCase()
      .slice(0, 2);
  };

  return (
    <Card
      className={className}
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        bgcolor: "background.paper",
        border: "1px solid",
        borderColor: "divider",
        borderRadius: 3,
        transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
        "&:hover": {
          borderColor: alpha("#475569", 0.3),
          boxShadow: "0 8px 24px rgba(0, 0, 0, 0.08)",
          transform: "translateY(-4px)",
        },
      }}
    >
      <CardContent sx={{ p: 4, flexGrow: 1, display: "flex", flexDirection: "column" }}>
        {/* Rating Stars */}
        <Box sx={{ display: "flex", gap: 0.5, mb: 3 }}>
          {[...Array(5)].map((_, index) => (
            <StarIcon
              key={index}
              sx={{
                fontSize: 20,
                color: index < rating ? "#fbbf24" : alpha("#cbd5e1", 0.5),
              }}
            />
          ))}
        </Box>

        {/* Content */}
        <Box
          component="blockquote"
          sx={{
            position: "relative",
            mb: 3,
            flexGrow: 1,
          }}
        >
          <Typography
            component="span"
            sx={{
              position: "absolute",
              top: -8,
              left: -12,
              fontSize: "3rem",
              lineHeight: 1,
              color: alpha("#475569", 0.1),
              zIndex: 0,
              pointerEvents: "none",
              fontFamily: "serif",
            }}
          >
            "
          </Typography>
          <Typography
            component="span"
            sx={{
              color: "text.secondary",
              fontSize: "0.9375rem",
              lineHeight: 1.8,
              fontStyle: "italic",
              position: "relative",
              zIndex: 1,
              display: "block",
            }}
          >
            {content}
          </Typography>
        </Box>

        {/* Project (if available) */}
        {project && (
          <Box
            sx={{
              mb: 3,
              px: 2,
              py: 1,
              bgcolor: alpha("#475569", 0.05),
              borderRadius: 2,
              border: `1px solid ${alpha("#475569", 0.1)}`,
            }}
          >
            <Typography
              variant="caption"
              sx={{
                color: "text.secondary",
                fontSize: "0.8125rem",
                fontWeight: 500,
              }}
            >
              {t("common.project")}: {project}
            </Typography>
          </Box>
        )}

        {/* Author Info */}
        <Box sx={{ display: "flex", alignItems: "center", gap: 2, mt: "auto" }}>
          <Avatar
            src={avatar}
            alt={name}
            sx={{
              width: 48,
              height: 48,
              bgcolor: "primary.main",
              fontSize: "1rem",
              fontWeight: 600,
            }}
          >
            {!avatar && getInitials(name)}
          </Avatar>
          <Box sx={{ flex: 1 }}>
            <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 0.5 }}>
              <Typography
                component="p"
                sx={{
                  fontWeight: 600,
                  color: "text.primary",
                  fontSize: "0.9375rem",
                }}
              >
                {name}
              </Typography>
              {verified && (
                <VerifiedIcon
                  sx={{
                    fontSize: 18,
                    color: "primary.main",
                  }}
                />
              )}
            </Box>
            <Typography
              variant="caption"
              sx={{
                color: "text.secondary",
                fontSize: "0.8125rem",
              }}
            >
              {position}
            </Typography>
            <Typography
              variant="caption"
              sx={{
                color: "text.secondary",
                fontSize: "0.8125rem",
                display: "block",
              }}
            >
              {company}
            </Typography>
          </Box>
        </Box>
      </CardContent>
    </Card>
  );
};

export default TestimonialCard;
