/**
 * Custom hook for auto-saving form data to localStorage
 * 
 * Features:
 * - Auto-saves form data on change
 * - Restores data on mount
 * - Clears data after successful submission
 */

import { useEffect, useRef } from "react";

interface UseFormAutoSaveOptions {
  formKey: string;
  formData: any;
  enabled?: boolean;
  debounceMs?: number;
}

export const useFormAutoSave = ({
  formKey,
  formData,
  enabled = true,
  debounceMs = 500,
}: UseFormAutoSaveOptions) => {
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const isInitialMount = useRef(true);

  // Save to localStorage
  useEffect(() => {
    if (!enabled) return;

    // Skip save on initial mount (data will be restored)
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    // Debounce save
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      try {
        localStorage.setItem(`form_${formKey}`, JSON.stringify(formData));
      } catch (error) {
        console.warn("Failed to save form data to localStorage:", error);
      }
    }, debounceMs);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [formData, formKey, enabled, debounceMs]);

  // Restore from localStorage
  const restoreData = (): any | null => {
    if (!enabled) return null;

    try {
      const saved = localStorage.getItem(`form_${formKey}`);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (error) {
      console.warn("Failed to restore form data from localStorage:", error);
    }
    return null;
  };

  // Clear saved data
  const clearSavedData = () => {
    try {
      localStorage.removeItem(`form_${formKey}`);
    } catch (error) {
      console.warn("Failed to clear form data from localStorage:", error);
    }
  };

  return {
    restoreData,
    clearSavedData,
  };
};
