/**
 * Client Logos Section Component
 * 
 * Displays logos of companies/clients worked with
 */

import React from "react";
import { Box, Container, Typography } from "@mui/material";
import SectionHeader from "./SectionHeader";
import { SectionHeader as SectionHeaderType } from "../../content/types";

interface ClientLogo {
  id: string;
  name: string;
  logo?: string; // URL to logo image
  url?: string; // Company website
}

interface ClientLogosSectionProps {
  header: SectionHeaderType;
  logos: ClientLogo[];
  className?: string;
}

const ClientLogosSection: React.FC<ClientLogosSectionProps> = ({
  header,
  logos,
  className,
}) => {
  return (
    <Box
      component="section"
      className={className}
      sx={{
        py: { xs: 8, md: 12 },
        bgcolor: "background.default",
        position: "relative",
      }}
    >
      <Container maxWidth="lg">
        <SectionHeader content={header} />
        <Box
          sx={{
            mt: 6,
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "center",
            alignItems: "center",
            gap: { xs: 4, md: 6 },
          }}
        >
          {logos.map((client) => (
            <Box
              key={client.id}
              component={client.url ? "a" : "div"}
              href={client.url}
              target={client.url ? "_blank" : undefined}
              rel={client.url ? "noopener noreferrer" : undefined}
              sx={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                width: { xs: 120, md: 150 },
                height: { xs: 60, md: 80 },
                opacity: 0.6,
                transition: "all 0.3s ease",
                "&:hover": {
                  opacity: 1,
                  transform: "scale(1.05)",
                },
              }}
            >
              {client.logo ? (
                <Box
                  component="img"
                  src={client.logo}
                  alt={client.name}
                  sx={{
                    maxWidth: "100%",
                    maxHeight: "100%",
                    objectFit: "contain",
                    filter: "grayscale(100%)",
                    transition: "filter 0.3s ease",
                    "&:hover": {
                      filter: "grayscale(0%)",
                    },
                  }}
                />
              ) : (
                <Typography
                  sx={{
                    color: "text.secondary",
                    fontSize: "0.875rem",
                    fontWeight: 500,
                    textAlign: "center",
                  }}
                >
                  {client.name}
                </Typography>
              )}
            </Box>
          ))}
        </Box>
      </Container>
    </Box>
  );
};

export default ClientLogosSection;
export type { ClientLogo };
