/**
 * Role Pricing Table Component
 * 
 * Displays pricing table by role and level
 */

import React from "react";
import {
  Box,
  Container,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  alpha,
  useMediaQuery,
  useTheme,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { rolePricing, RolePricing, PriceRange } from "../../content/pricing";
import { SectionHeader } from "../sections";
import { useCurrency } from "../../contexts/CurrencyContext";

const RolePricingTable: React.FC = () => {
  const { t } = useTranslation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const { formatPriceRange } = useCurrency();

  // Map role.id to translation key
  const getRoleTranslationKey = (roleId: string): string => {
    const roleMap: { [key: string]: string } = {
      'ba': 'businessAnalyst',
      'system-analyst': 'systemAnalyst',
      'ui-ux': 'uiUxDesigner',
      'developer': 'developer',
      'qa': 'qaEngineer',
      'devops': 'devopsEngineer',
      'pm': 'projectManager',
      'tech-lead': 'technicalLead',
    };
    return roleMap[roleId] || roleId;
  };

  const getLevelPrice = (role: RolePricing, level: "junior" | "mid" | "senior" | "lead" | "principal") => {
    const priceRange = role[level];
    if (!priceRange) return "-";
    // Prices in pricing.ts are in JPY, formatPriceRange will convert
    return formatPriceRange({ min: priceRange.min, max: priceRange.max });
  };

  // Calculate discount percentage based on market rate
  const getDiscount = (priceRange: PriceRange): number => {
    if (!priceRange.marketMin || !priceRange.marketMax) return 20; // Default 20%
    const avgPrice = (priceRange.min + priceRange.max) / 2;
    const avgMarket = (priceRange.marketMin + priceRange.marketMax) / 2;
    const discount = ((avgMarket - avgPrice) / avgMarket) * 100;
    return Math.round(discount);
  };

  if (isMobile) {
    // Mobile: Card-based layout
    return (
      <Box component="section" sx={{ py: { xs: 6, md: 8 } }}>
        <Container maxWidth="lg">
          <SectionHeader
            content={{
              badge: "",
              title: t("pricing.competitive.title"),
              description: t("pricing.competitive.description"),
              alignment: "center",
            }}
          />

          <Box sx={{ display: "flex", flexDirection: "column", gap: 3, mt: 6 }}>
            {rolePricing.map((role) => (
              <Paper
                key={role.id}
                elevation={2}
                sx={{
                  p: 3,
                  borderRadius: 2,
                  border: "1px solid",
                  borderColor: "divider",
                }}
              >
                <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
                  {t(`pricing.roles.${getRoleTranslationKey(role.id)}`) || role.name}
                </Typography>
                <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
                  {role.junior && (
                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <Typography variant="body2">{t("pricing.levels.junior")}</Typography>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "junior")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.junior)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </Box>
                  )}
                  {role.mid && (
                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <Typography variant="body2">{t("pricing.levels.mid")}</Typography>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "mid")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.mid)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </Box>
                  )}
                  <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <Typography variant="body2">{t("pricing.levels.senior")}</Typography>
                    <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>
                        {getLevelPrice(role, "senior")}
                      </Typography>
                      <Chip 
                        label={`-${getDiscount(role.senior)}%`} 
                        size="small" 
                        color="success" 
                        sx={{ fontSize: "0.7rem" }} 
                      />
                    </Box>
                  </Box>
                  {role.lead && (
                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <Typography variant="body2">{t("pricing.levels.lead")}</Typography>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "lead")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.lead)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </Box>
                  )}
                  {role.principal && (
                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <Typography variant="body2">{t("pricing.levels.principal")}</Typography>
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "principal")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.principal)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </Box>
                  )}
                </Box>
              </Paper>
            ))}
          </Box>
        </Container>
      </Box>
    );
  }

  // Desktop: Full table
  return (
      <Box component="section" sx={{ py: { xs: 6, md: 8 } }}>
        <Container maxWidth="lg">
          <SectionHeader
            content={{
              badge: "",
              title: t("pricing.competitive.title"),
              description: t("pricing.competitive.description"),
              alignment: "center",
            }}
          />

        <TableContainer
          component={Paper}
          elevation={2}
          sx={{
            mt: 6,
            borderRadius: 2,
            border: "1px solid",
            borderColor: "divider",
            overflowX: "auto",
          }}
        >
          <Table>
            <TableHead>
              <TableRow sx={{ bgcolor: alpha("#f1f5f9", 0.5) }}>
                <TableCell sx={{ fontWeight: 700 }}>{t("pricing.comparison.role")}</TableCell>
                {rolePricing[0].junior && (
                  <TableCell align="center" sx={{ fontWeight: 600 }}>
                    {t("pricing.levels.junior")}
                  </TableCell>
                )}
                <TableCell align="center" sx={{ fontWeight: 600 }}>
                  {t("pricing.levels.mid")}
                </TableCell>
                <TableCell align="center" sx={{ fontWeight: 600 }}>
                  {t("pricing.levels.senior")}
                </TableCell>
                  {rolePricing.find((r) => r.lead) && (
                  <TableCell align="center" sx={{ fontWeight: 600 }}>
                    {t("pricing.levels.lead")}
                  </TableCell>
                )}
                {rolePricing.find((r) => r.principal) && (
                  <TableCell align="center" sx={{ fontWeight: 600 }}>
                    {t("pricing.levels.principal")}
                  </TableCell>
                )}
              </TableRow>
            </TableHead>
            <TableBody>
              {rolePricing.map((role) => (
                <TableRow key={role.id} hover>
                  <TableCell sx={{ fontWeight: 600 }}>
                    {t(`pricing.roles.${getRoleTranslationKey(role.id)}`) || role.name}
                  </TableCell>
                  {role.junior && (
                    <TableCell align="center">
                      <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 0.5 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "junior")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.junior)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </TableCell>
                  )}
                  {role.mid && (
                    <TableCell align="center">
                      <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 0.5 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "mid")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.mid)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </TableCell>
                  )}
                  <TableCell align="center">
                    <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 0.5 }}>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>
                        {getLevelPrice(role, "senior")}
                      </Typography>
                      <Chip 
                        label={`-${getDiscount(role.senior)}%`} 
                        size="small" 
                        color="success" 
                        sx={{ fontSize: "0.7rem" }} 
                      />
                    </Box>
                  </TableCell>
                  {role.lead && (
                    <TableCell align="center">
                      <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 0.5 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "lead")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.lead)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </TableCell>
                  )}
                  {role.principal && (
                    <TableCell align="center">
                      <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 0.5 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {getLevelPrice(role, "principal")}
                        </Typography>
                        <Chip 
                          label={`-${getDiscount(role.principal)}%`} 
                          size="small" 
                          color="success" 
                          sx={{ fontSize: "0.7rem" }} 
                        />
                      </Box>
                    </TableCell>
                  )}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <Typography variant="body2" sx={{ mt: 3, textAlign: "center", color: "text.secondary" }}>
          * {t("pricing.competitive.description")}
        </Typography>
      </Container>
    </Box>
  );
};

export default RolePricingTable;
