/**
 * Blog Page - Content-Driven Architecture
 * 
 * Lists blog articles and allows filtering by category
 */

import React, { useState } from "react";
import { Box, Container, Grid, Chip, Typography, alpha } from "@mui/material";
import { SectionHeader } from "../components/sections";
import { ArticleCard } from "../components/cards";
import SEO from "../components/SEO";
import {
  blogPageConfig,
  blogCategories,
} from "../content";
import { useBlogContent } from "../utils/contentHelper";
import { useTranslation } from "react-i18next";

const Blog: React.FC = () => {
  const { t } = useTranslation();
  const blogContent = useBlogContent();
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  const filteredArticles = Array.isArray(blogContent.articles)
    ? (selectedCategory === "all"
        ? blogContent.articles
        : blogContent.articles.filter((a) => a.category === selectedCategory))
    : [];

  // Show loading state
  if (blogContent.loading) {
    return (
      <>
        <SEO
          content={{
            meta: {
              title: blogContent.meta.title,
              description: blogContent.meta.description,
              keywords: blogContent.meta.keywords,
            },
          }}
        />
        <Box component="main" sx={{ bgcolor: "background.default", minHeight: "60vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Typography>{t("common.loading")}</Typography>
        </Box>
      </>
    );
  }

  return (
    <>
      <SEO
        content={{
          meta: {
            title: blogContent.meta.title,
            description: blogContent.meta.description,
            keywords: blogContent.meta.keywords,
          },
        }}
      />
      <Box component="main" sx={{ bgcolor: "background.default" }}>
      {/* Hero Section - Có thể ẩn/hiện qua config */}
      {blogPageConfig.showHero && (
        <Box
          component="section"
          sx={{
            py: { xs: 8, md: 12 },
            bgcolor: "background.paper",
          }}
        >
          <Container maxWidth="lg">
            <SectionHeader content={blogContent.section} />
          </Container>
        </Box>
      )}

      {/* Category Filter */}
      <Box sx={{ borderBottom: "1px solid", borderColor: "divider", bgcolor: "background.paper" }}>
        <Container maxWidth="lg">
          <Box
            sx={{
              display: "flex",
              flexWrap: "wrap",
              gap: 1,
              justifyContent: "center",
              py: 3,
            }}
          >
            {blogCategories.map((cat) => (
              <Chip
                key={cat.id}
                label={`${blogContent.categories[cat.id] || cat.label} (${cat.count})`}
                onClick={() => setSelectedCategory(cat.id)}
                sx={{
                  bgcolor: selectedCategory === cat.id ? alpha("#f1f5f9", 0.8) : "transparent",
                  color: selectedCategory === cat.id ? "text.primary" : "text.secondary",
                  border: "1px solid",
                  borderColor: "divider",
                  fontWeight: selectedCategory === cat.id ? 500 : 400,
                  cursor: "pointer",
                  transition: "all 150ms ease",
                  "&:hover": {
                    bgcolor: alpha("#f8fafc", 0.8),
                    color: "text.primary",
                  },
                }}
              />
            ))}
          </Box>
        </Container>
      </Box>

      {/* Articles Grid */}
      <Box
        component="section"
        aria-labelledby="blog-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: "background.default",
        }}
      >
        <Container maxWidth="lg">
          {filteredArticles.length > 0 ? (
            <Grid container spacing={4}>
              {filteredArticles.map((article: any) => (
                <Grid size={{ xs: 12, md: 6, lg: 4 }} key={article.id}>
                  <ArticleCard article={article} />
                </Grid>
              ))}
            </Grid>
          ) : (
            <Box sx={{ textAlign: "center", py: 8 }}>
              <Typography sx={{ color: "text.secondary" }}>
                {blogContent.emptyState}
              </Typography>
            </Box>
          )}
        </Container>
      </Box>
      </Box>
    </>
  );
};

export default Blog;
