/**
 * Feature Card Component
 * 
 * Reusable feature card for displaying benefits/features
 * Used in "Why Choose Me" and similar sections
 */

import React from "react";
import { Card, Typography, Box, alpha } from "@mui/material";
import Icon from "../Icon";
import { FeatureContent } from "../../content/types";
import { normalizeIconName } from "../../utils/iconMapping";

interface FeatureCardProps {
  feature: FeatureContent;
  className?: string;
}

const FeatureCard: React.FC<FeatureCardProps> = ({ feature, className }) => {
  const { icon, title, description, value } = feature;

  return (
    <Card
      component="article"
      className={className}
      sx={{
        p: 4,
        textAlign: "center",
        bgcolor: "background.paper",
        border: "1px solid",
        borderColor: "divider",
        borderRadius: 2,
        transition: "all 180ms cubic-bezier(0.4, 0, 0.2, 1)",
        "&:hover": {
          borderColor: alpha("#475569", 0.3),
          boxShadow:
            "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1)",
          transform: "translateY(-2px)",
        },
      }}
    >
      <Box
        sx={{
          mb: 2,
          display: "flex",
          justifyContent: "center",
        }}
        aria-hidden="true"
      >
        <Icon
          name={normalizeIconName(icon)}
          size="xxlarge"
          color="primary"
          hoverEffect="scale"
        />
      </Box>
      {value && (
        <Typography
          variant="h3"
          component="div"
          sx={{
            fontSize: { xs: "2rem", md: "2.5rem" },
            fontWeight: 600,
            mb: 1,
            color: "text.primary",
          }}
        >
          {value}
        </Typography>
      )}
      <Typography
        component="h3"
        sx={{
          fontWeight: 500,
          fontSize: "1rem",
          lineHeight: 1.6,
          color: "text.primary",
        }}
      >
        {title}
      </Typography>
      {description && (
        <Typography
          component="p"
          sx={{
            mt: 1,
            color: "text.secondary",
            fontSize: "0.875rem",
            lineHeight: 1.6,
          }}
        >
          {description}
        </Typography>
      )}
    </Card>
  );
};

export default FeatureCard;
