/**
 * i18n Configuration
 * 
 * Internationalization setup for Vietnamese, English, and Japanese
 */

import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import LanguageDetector from "i18next-browser-languagedetector";

// Import translation files
import viTranslations from "./locales/vi/translation.json";
import enTranslations from "./locales/en/translation.json";
import jaTranslations from "./locales/ja/translation.json";

// Supported languages
export const SUPPORTED_LANGUAGES = [
  { code: "vi", name: "Tiếng Việt", nativeName: "Tiếng Việt" },
  { code: "en", name: "English", nativeName: "English" },
  { code: "ja", name: "日本語", nativeName: "日本語" },
] as const;

export type LanguageCode = "vi" | "en" | "ja";

i18n
  // Detect user language
  .use(LanguageDetector)
  // Pass the i18n instance to react-i18next
  .use(initReactI18next)
  // Initialize i18next
  .init({
    resources: {
      vi: {
        translation: viTranslations,
      },
      en: {
        translation: enTranslations,
      },
      ja: {
        translation: jaTranslations,
      },
    },
    // Default language when không khớp vi/en/ja -> dùng English
    fallbackLng: "en",
    debug: process.env.NODE_ENV === "development",
    interpolation: {
      escapeValue: false, // React already escapes values
    },
    detection: {
      // Order of language detection
      order: ["localStorage", "navigator", "htmlTag"],
      // Cache user language
      caches: ["localStorage"],
      // Look for language in localStorage
      lookupLocalStorage: "i18nextLng",
    },
  });

export default i18n;
