/**
 * Breadcrumbs Component
 * 
 * Reusable breadcrumb navigation with schema support
 */

import React from "react";
import { Link } from "react-router-dom";
import { Box, Typography } from "@mui/material";
import HomeIcon from "@mui/icons-material/Home";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";

export interface BreadcrumbItem {
  label: string;
  path: string;
}

interface BreadcrumbsProps {
  items: BreadcrumbItem[];
  className?: string;
}

const Breadcrumbs: React.FC<BreadcrumbsProps> = ({ items, className }) => {
  return (
    <Box
      component="nav"
      aria-label="Breadcrumb"
      className={className}
      sx={{
        display: "flex",
        alignItems: "center",
        gap: 1,
        flexWrap: "wrap",
        py: 2,
      }}
    >
      <Link
        to="/"
        style={{
          display: "flex",
          alignItems: "center",
          textDecoration: "none",
          color: "inherit",
        }}
      >
        <HomeIcon sx={{ fontSize: 18, color: "text.secondary" }} />
      </Link>
      {items.map((item, index) => (
        <React.Fragment key={item.path}>
          <ChevronRightIcon
            sx={{
              fontSize: 16,
              color: "text.secondary",
              opacity: 0.5,
            }}
          />
          {index === items.length - 1 ? (
            <Typography
              component="span"
              sx={{
                color: "text.primary",
                fontSize: "0.875rem",
                fontWeight: 500,
              }}
            >
              {item.label}
            </Typography>
          ) : (
            <Link
              to={item.path}
              style={{
                textDecoration: "none",
                color: "inherit",
              }}
            >
              <Typography
                component="span"
                sx={{
                  color: "text.secondary",
                  fontSize: "0.875rem",
                  "&:hover": {
                    color: "text.primary",
                  },
                }}
              >
                {item.label}
              </Typography>
            </Link>
          )}
        </React.Fragment>
      ))}
    </Box>
  );
};

export default Breadcrumbs;
