/**
 * Icon Mapping Utilities
 * 
 * Helper functions for icon mapping and migration
 */

import { IconName, emojiToIcon } from "../components/Icon";

/**
 * Convert emoji to icon name
 */
export const getIconFromEmoji = (emoji: string): IconName | null => {
  return (emojiToIcon[emoji] as IconName) || null;
};

/**
 * Get icon name from string (supports both emoji and icon name)
 */
export const normalizeIconName = (icon: string): IconName => {
  // If it's an emoji, convert it
  if (emojiToIcon[icon]) {
    return emojiToIcon[icon] as IconName;
  }
  // Otherwise, assume it's already an icon name
  return icon as IconName;
};

