/**
 * Japan Market Section
 * 
 * Highlights services optimized for Japanese clients
 */

import React from "react";
import { Box, Container, Typography, Grid, Card, CardContent } from "@mui/material";
import { useTranslation } from "react-i18next";
import SectionHeader from "./SectionHeader";
import { Button } from "@mui/material";
import { Link } from "react-router-dom";
import AccessTimeIcon from "@mui/icons-material/AccessTime";
import LanguageIcon from "@mui/icons-material/Language";
import WorkIcon from "@mui/icons-material/Work";
import PaymentIcon from "@mui/icons-material/Payment";
import BusinessIcon from "@mui/icons-material/Business";
import TranslateIcon from "@mui/icons-material/Translate";
import EngineeringIcon from "@mui/icons-material/Engineering";

const JapanMarketSection: React.FC = () => {
  const { t, i18n } = useTranslation();

  // Only show in Japanese language
  if (i18n.language !== "ja") {
    return null;
  }

  const features = [
    {
      id: "timezone",
      icon: <AccessTimeIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("japan.features.timezone.title"),
      description: t("japan.features.timezone.description"),
    },
    {
      id: "language",
      icon: <LanguageIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("japan.features.language.title"),
      description: t("japan.features.language.description"),
    },
    {
      id: "communication",
      icon: <TranslateIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("japan.features.communication.title"),
      description: t("japan.features.communication.description"),
    },
    {
      id: "brse",
      icon: <EngineeringIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("japan.features.brse.title"),
      description: t("japan.features.brse.description"),
    },
    {
      id: "remote",
      icon: <WorkIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("japan.features.remote.title"),
      description: t("japan.features.remote.description"),
    },
    {
      id: "payment",
      icon: <PaymentIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("japan.features.payment.title"),
      description: t("japan.features.payment.description"),
    },
    {
      id: "culture",
      icon: <BusinessIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("japan.features.culture.title"),
      description: t("japan.features.culture.description"),
    },
  ];

  return (
    <Box
      component="section"
      sx={{
        py: { xs: 8, md: 12 },
        bgcolor: "background.default",
      }}
    >
      <Container maxWidth="lg">
        <SectionHeader
          content={{
            badge: "日本市場",
            title: t("japan.title"),
            description: t("japan.description"),
            alignment: "center",
          }}
        />

        <Grid container spacing={4} sx={{ mt: 2 }}>
          {features.map((feature) => (
            <Grid size={{ xs: 12, sm: 6, md: 4, lg: 3.4 }} key={feature.id}>
              <Card
                sx={{
                  height: "100%",
                  bgcolor: "background.paper",
                  border: "1px solid",
                  borderColor: "divider",
                  borderRadius: 2,
                  transition: "all 200ms ease",
                  "&:hover": {
                    boxShadow: 2,
                    transform: "translateY(-2px)",
                  },
                }}
              >
                <CardContent sx={{ p: 3 }}>
                  <Box sx={{ mb: 2 }}>{feature.icon}</Box>
                  <Typography
                    variant="h6"
                    sx={{
                      fontWeight: 600,
                      mb: 1.5,
                      color: "text.primary",
                      fontSize: "1.125rem",
                    }}
                  >
                    {feature.title}
                  </Typography>
                  <Typography
                    sx={{
                      color: "text.secondary",
                      fontSize: "0.9375rem",
                      lineHeight: 1.7,
                    }}
                  >
                    {feature.description}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Box sx={{ textAlign: "center", mt: 6 }}>
          <Typography
            variant="h5"
            sx={{
              fontWeight: 600,
              mb: 2,
              color: "text.primary",
            }}
          >
            {t("japan.cta.title")}
          </Typography>
          <Typography
            sx={{
              color: "text.secondary",
              mb: 4,
              fontSize: "1rem",
              maxWidth: 600,
              mx: "auto",
            }}
          >
            {t("japan.cta.description")}
          </Typography>
          <Button
            component={Link}
            to="/contact"
            variant="contained"
            size="large"
            sx={{
              px: 4,
              py: 1.5,
              borderRadius: 2,
              fontWeight: 500,
              fontSize: "1rem",
            }}
          >
            {t("japan.cta.button")}
          </Button>
        </Box>
      </Container>
    </Box>
  );
};

export default JapanMarketSection;
