/**
 * Offshore Development Section
 * 
 * Highlights offshore development services in Vietnam
 * Keywords: オフショア開発, ベトナム オフショア 開発
 */

import React from "react";
import { Box, Container, Grid, Typography, Card, CardContent, alpha } from "@mui/material";
import { useTranslation } from "react-i18next";
import SectionHeader from "./SectionHeader";
import AttachMoneyIcon from "@mui/icons-material/AttachMoney";
import QualityIcon from "@mui/icons-material/HighQuality";
import AccessTimeIcon from "@mui/icons-material/AccessTime";
import LanguageIcon from "@mui/icons-material/Language";

const OffshoreDevelopmentSection: React.FC = () => {
  const { t } = useTranslation();

  const benefits = [
    {
      id: "cost",
      icon: <AttachMoneyIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("offshore.benefits.cost.title"),
      description: t("offshore.benefits.cost.description"),
    },
    {
      id: "quality",
      icon: <QualityIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("offshore.benefits.quality.title"),
      description: t("offshore.benefits.quality.description"),
    },
    {
      id: "timezone",
      icon: <AccessTimeIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("offshore.benefits.timezone.title"),
      description: t("offshore.benefits.timezone.description"),
    },
    {
      id: "communication",
      icon: <LanguageIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("offshore.benefits.communication.title"),
      description: t("offshore.benefits.communication.description"),
    },
  ];

  return (
    <Box
      component="section"
      sx={{
        py: { xs: 12, md: 16 },
        bgcolor: "background.default",
      }}
    >
      <Container maxWidth="lg">
        <SectionHeader
          content={{
            badge: t("offshore.badge"),
            title: t("offshore.title"),
            description: t("offshore.description"),
            alignment: "center",
          }}
        />

        <Grid container spacing={4} sx={{ mt: 6 }}>
          {benefits.map((benefit) => (
            <Grid size={{ xs: 12, sm: 6, md: 3 }} key={benefit.id}>
              <Card
                sx={{
                  height: "100%",
                  bgcolor: "background.paper",
                  border: "1px solid",
                  borderColor: "divider",
                  borderRadius: 2,
                  transition: "all 0.3s ease",
                  "&:hover": {
                    borderColor: alpha("#475569", 0.3),
                    boxShadow: "0 4px 12px rgba(0, 0, 0, 0.08)",
                    transform: "translateY(-2px)",
                  },
                }}
              >
                <CardContent sx={{ p: 3, textAlign: "center" }}>
                  <Box sx={{ mb: 2, display: "flex", justifyContent: "center" }}>
                    {benefit.icon}
                  </Box>
                  <Typography
                    component="h3"
                    sx={{
                      fontWeight: 600,
                      mb: 1.5,
                      color: "text.primary",
                      fontSize: "1.125rem",
                    }}
                  >
                    {benefit.title}
                  </Typography>
                  <Typography
                    sx={{
                      color: "text.secondary",
                      fontSize: "0.9375rem",
                      lineHeight: 1.7,
                    }}
                  >
                    {benefit.description}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>

        <Box sx={{ mt: 6, textAlign: "center" }}>
          <Typography
            sx={{
              color: "text.secondary",
              fontSize: "0.9375rem",
              maxWidth: "800px",
              mx: "auto",
              lineHeight: 1.8,
            }}
          >
            {t("offshore.summary")}
          </Typography>
        </Box>
      </Container>
    </Box>
  );
};

export default OffshoreDevelopmentSection;
