/**
 * Pricing Content
 * 
 * Competitive pricing structure with 20% lower than market rate
 * Includes role-based pricing, package pricing, and promotional discounts
 */

export interface PriceRange {
  min: number; // JPY
  max: number; // JPY
  marketMin: number; // JPY - Market rate for comparison
  marketMax: number; // JPY - Market rate for comparison
}

export interface RolePricing {
  id: string;
  name: string;
  junior?: PriceRange;
  mid?: PriceRange;
  senior: PriceRange;
  lead?: PriceRange;
  principal?: PriceRange;
}

export interface TeamMember {
  role: string;
  level: 'junior' | 'mid' | 'senior' | 'lead';
  count: number;
}

export interface PackagePricing {
  id: string;
  name: string;
  duration: string;
  team: TeamMember[];
  baseCost: PriceRange;
  withDiscounts: PriceRange;
  marketRate: PriceRange;
  savings: PriceRange;
}

export interface DiscountRule {
  type: 'first-month' | '6-month' | '12-month';
  percentage: number;
  minDuration: number;
  description: string;
}

