/**
 * Package Pricing Section Component
 * 
 * Displays package pricing with team composition
 */

import React from "react";
import {
  Box,
  Container,
  Typography,
  Grid,
  Card,
  CardContent,
  Chip,
  Divider,
  alpha,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import { packagePricing } from "../../content/pricing";
import { SectionHeader } from "../sections";
import { useCurrency } from "../../contexts/CurrencyContext";
import { Button } from "@mui/material";

const PackagePricingSection: React.FC = () => {
  const { t } = useTranslation();
  const { formatPriceRange } = useCurrency();

  const getPackageName = (id: string): string => {
    const keyMap: Record<string, string> = {
      "mvp-small": "mvpSmall",
      "mvp-medium": "mvpMedium",
      ecommerce: "ecommerce",
      saas: "saas",
    };
    return t(`pricing.packages.${keyMap[id] || id}`);
  };

  return (
    <Box component="section" sx={{ py: { xs: 6, md: 8 } }}>
      <Container maxWidth="lg">
          <SectionHeader
            content={{
              badge: "",
              title: t("pricing.packages.title"),
              description: "",
              alignment: "center",
            }}
          />

        <Grid container spacing={3} sx={{ mt: 4 }}>
          {packagePricing.map((pkg) => (
            <Grid size={{ xs: 12, md: 6 }} key={pkg.id}>
              <Card
                elevation={3}
                sx={{
                  height: "100%",
                  display: "flex",
                  flexDirection: "column",
                  borderRadius: 2,
                  border: "1px solid",
                  borderColor: "divider",
                  transition: "transform 0.2s, box-shadow 0.2s",
                  "&:hover": {
                    transform: "translateY(-4px)",
                    boxShadow: 6,
                  },
                }}
              >
                <CardContent sx={{ flexGrow: 1, p: 3, display: "flex", flexDirection: "column" }}>
                  <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "start", mb: 2 }}>
                    <Typography variant="h5" sx={{ fontWeight: 700 }}>
                      {getPackageName(pkg.id)}
                    </Typography>
                    <Chip label={pkg.duration} size="small" color="primary" />
                  </Box>

                  <Divider sx={{ my: 2 }} />

                  <Box sx={{ mb: 3 }}>
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      {t("pricing.packages.team")}
                    </Typography>
                    <Box sx={{ display: "flex", flexDirection: "column", gap: 0.5, mt: 1 }}>
                      {pkg.team.map((member, idx) => {
                        const roleMap: { [key: string]: string } = {
                          'ba': 'businessAnalyst',
                          'system-analyst': 'systemAnalyst',
                          'ui-ux': 'uiUxDesigner',
                          'developer': 'developer',
                          'qa': 'qaEngineer',
                          'devops': 'devopsEngineer',
                          'pm': 'projectManager',
                          'tech-lead': 'technicalLead',
                        };
                        const translationKey = roleMap[member.role] || member.role;
                        return (
                          <Typography key={idx} variant="body2" sx={{ fontSize: "0.875rem" }}>
                            • {member.count}x {t(`pricing.roles.${translationKey}`)} ({t(`pricing.levels.${member.level}`)})
                          </Typography>
                        );
                      })}
                    </Box>
                  </Box>

                  <Divider sx={{ my: 2 }} />

                  <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <Typography variant="body2" color="text.secondary">
                        {t("pricing.packages.baseCost")}
                      </Typography>
                      <Typography variant="body2" sx={{ fontWeight: 600 }}>
                        {formatPriceRange(pkg.baseCost)}
                      </Typography>
                    </Box>
                    <Box
                      sx={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        bgcolor: alpha("#0ea5e9", 0.05),
                        p: 1,
                        borderRadius: 1,
                      }}
                    >
                      <Typography variant="body2" color="text.secondary">
                        {t("pricing.packages.withDiscounts")}
                      </Typography>
                      <Typography variant="body2" sx={{ fontWeight: 600, color: "primary.main" }}>
                        {formatPriceRange(pkg.withDiscounts)}
                      </Typography>
                    </Box>
                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <Typography variant="body2" color="text.secondary">
                        {t("pricing.packages.marketRate")}
                      </Typography>
                      <Typography variant="body2" sx={{ fontWeight: 600, color: "text.secondary" }}>
                        {formatPriceRange(pkg.marketRate)}
                      </Typography>
                    </Box>
                    <Box
                      sx={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        bgcolor: alpha("#10b981", 0.1),
                        p: 1,
                        borderRadius: 1,
                        border: "1px solid",
                        borderColor: "success.main",
                      }}
                    >
                      <Typography variant="body2" sx={{ fontWeight: 600, color: "success.main" }}>
                        {t("pricing.packages.savings")}
                      </Typography>
                      <Typography variant="body2" sx={{ fontWeight: 700, color: "success.main" }}>
                        {formatPriceRange(pkg.savings)}
                      </Typography>
                    </Box>
                  </Box>

                  <Box sx={{ mt: "auto", pt: 2, borderTop: "1px solid", borderColor: "divider" }}>
                    <Button
                      component={Link}
                      to="/job-request"
                      variant="contained"
                      fullWidth
                      size="large"
                    >
                      {t("pricing.calculator.getQuote")}
                    </Button>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

export default PackagePricingSection;
