/**
 * Security Commitment Section
 * 
 * Displays security standards, compliance, and commitments
 * Critical for Japanese market - P-Mark, GDPR, NDA
 */

import React from "react";
import { Box, Container, Grid, Typography, alpha } from "@mui/material";
import { useTranslation } from "react-i18next";
import SectionHeader from "./SectionHeader";
import SecurityIcon from "@mui/icons-material/Security";
import VerifiedUserIcon from "@mui/icons-material/VerifiedUser";
import LockIcon from "@mui/icons-material/Lock";
import GavelIcon from "@mui/icons-material/Gavel";

const SecurityCommitmentSection: React.FC = () => {
  const { t } = useTranslation();

  const commitments = [
    {
      id: "standards",
      icon: <SecurityIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("security.commitments.standards.title"),
      items: t("security.commitments.standards.items", { returnObjects: true }) as string[],
    },
    {
      id: "data-protection",
      icon: <LockIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("security.commitments.dataProtection.title"),
      items: t("security.commitments.dataProtection.items", { returnObjects: true }) as string[],
    },
    {
      id: "nda",
      icon: <VerifiedUserIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("security.commitments.nda.title"),
      items: t("security.commitments.nda.items", { returnObjects: true }) as string[],
    },
    {
      id: "compliance",
      icon: <GavelIcon sx={{ fontSize: 32, color: "primary.main" }} />,
      title: t("security.commitments.compliance.title"),
      items: t("security.commitments.compliance.items", { returnObjects: true }) as string[],
    },
  ];

  return (
    <Box
      component="section"
      sx={{
        py: { xs: 12, md: 16 },
        bgcolor: "background.default",
      }}
    >
      <Container maxWidth="lg">
        <SectionHeader
          content={{
            badge: t("security.badge"),
            title: t("security.title"),
            description: t("security.description"),
            alignment: "center",
          }}
        />

        <Grid container spacing={4} sx={{ mt: 6 }}>
          {commitments.map((commitment) => (
            <Grid size={{ xs: 12, sm: 6, md: 3 }} key={commitment.id}>
              <Box
                sx={{
                  p: 4,
                  height: "100%",
                  bgcolor: "background.paper",
                  borderRadius: 2,
                  border: "1px solid",
                  borderColor: "divider",
                  transition: "all 0.3s ease",
                  "&:hover": {
                    borderColor: alpha("#475569", 0.3),
                    boxShadow: "0 4px 12px rgba(0, 0, 0, 0.08)",
                  },
                }}
              >
                <Box sx={{ display: "flex", alignItems: "center", gap: 2, mb: 3 }}>
                  {commitment.icon}
                  <Typography
                    component="h3"
                    sx={{
                      fontWeight: 600,
                      fontSize: "1.125rem",
                      color: "text.primary",
                    }}
                  >
                    {commitment.title}
                  </Typography>
                </Box>
                <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
                  {commitment.items.map((item, idx) => (
                    <Box
                      key={`${commitment.id}-${idx}`}
                      sx={{
                        display: "flex",
                        alignItems: "flex-start",
                        gap: 1,
                      }}
                    >
                      <Typography
                        component="span"
                        sx={{
                          color: "primary.main",
                          fontSize: "0.875rem",
                          mt: 0.5,
                        }}
                      >
                        ✓
                      </Typography>
                      <Typography
                        sx={{
                          color: "text.secondary",
                          fontSize: "0.875rem",
                          lineHeight: 1.6,
                        }}
                      >
                        {item}
                      </Typography>
                    </Box>
                  ))}
                </Box>
              </Box>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

export default SecurityCommitmentSection;
