/**
 * Currency Switcher Component
 * 
 * Allows users to switch between different currencies
 * Supports: VND, USD, JPY
 */

import React, { useState } from "react";
import {
  IconButton,
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText,
  Typography,
  Box,
} from "@mui/material";
import AttachMoneyIcon from "@mui/icons-material/AttachMoney";
import CheckIcon from "@mui/icons-material/Check";
import { useCurrency } from "../contexts/CurrencyContext";

export type CurrencyCode = "VND" | "USD" | "JPY";

export interface Currency {
  code: CurrencyCode;
  symbol: string;
  name: string;
  rate: number; // Exchange rate to VND (base currency)
}

export const CURRENCIES: Currency[] = [
  { code: "VND", symbol: "₫", name: "Vietnamese Dong", rate: 1 },
  { code: "USD", symbol: "$", name: "US Dollar", rate: 25000 }, // Approximate
  { code: "JPY", symbol: "¥", name: "Japanese Yen", rate: 170 }, // Approximate
];

interface CurrencySwitcherProps {
  onCurrencyChange?: (currency: CurrencyCode) => void;
}

const CurrencySwitcher: React.FC<CurrencySwitcherProps> = ({
  onCurrencyChange,
}) => {
  const { currency, setCurrency: setCurrencyContext } = useCurrency();
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const open = Boolean(anchorEl);

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleCurrencyChange = (newCurrency: CurrencyCode) => {
    setCurrencyContext(newCurrency);
    if (onCurrencyChange) {
      onCurrencyChange(newCurrency);
    }
    handleClose();
  };

  return (
    <>
      <IconButton
        onClick={handleClick}
        sx={{
          color: "text.primary",
          minWidth: 44, // WCAG: Minimum 44px touch target
          minHeight: 44, // WCAG: Minimum 44px touch target
          "&:hover": {
            bgcolor: "action.hover",
          },
        }}
        aria-label="Change currency"
        aria-controls={open ? "currency-menu" : undefined}
        aria-haspopup="true"
        aria-expanded={open ? "true" : undefined}
      >
        <AttachMoneyIcon />
      </IconButton>
      <Menu
        id="currency-menu"
        anchorEl={anchorEl}
        open={open}
        onClose={handleClose}
        MenuListProps={{
          "aria-labelledby": "currency-button",
        }}
        transformOrigin={{ horizontal: "right", vertical: "top" }}
        anchorOrigin={{ horizontal: "right", vertical: "bottom" }}
      >
        {CURRENCIES.map((curr) => (
          <MenuItem
            key={curr.code}
            onClick={() => handleCurrencyChange(curr.code)}
            selected={currency === curr.code}
            sx={{
              minWidth: 160,
            }}
          >
            <ListItemIcon>
              {currency === curr.code && (
                <CheckIcon sx={{ fontSize: 20 }} />
              )}
            </ListItemIcon>
            <ListItemText
              primary={
                <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                  <Typography variant="body2" sx={{ fontWeight: 500 }}>
                    {curr.symbol} {curr.code}
                  </Typography>
                  <Typography
                    variant="caption"
                    sx={{ color: "text.secondary" }}
                  >
                    {curr.name}
                  </Typography>
                </Box>
              }
            />
          </MenuItem>
        ))}
      </Menu>
    </>
  );
};

export default CurrencySwitcher;
