/**
 * FAQ Page
 * 
 * Frequently Asked Questions with search and categories
 */

import React, { useState, useMemo } from "react";
import {
  Box,
  Container,
  Typography,
  TextField,
  InputAdornment,
  Chip,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  alpha,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import { Helmet } from "react-helmet-async";
import { HeroSection } from "../components/sections";
import { allFAQs, faqCategories } from "../content/faq";
import { useTranslation } from "react-i18next";

const FAQ: React.FC = () => {
  const { t } = useTranslation();
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  // Filter FAQs based on search and category
  const filteredFAQs = useMemo(() => {
    let filtered = allFAQs;

    // Filter by category
    if (selectedCategory !== "all") {
      filtered = filtered.filter((faq) => faq.category === selectedCategory);
    }

    // Filter by search query
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(
        (faq) =>
          faq.question.toLowerCase().includes(query) ||
          faq.answer.toLowerCase().includes(query)
      );
    }

    return filtered;
  }, [searchQuery, selectedCategory]);

  const heroContent = {
    badge: t("faqPage.hero.badge"),
    headline: {
      primary: t("faqPage.hero.title"),
      highlight: t("faqPage.hero.highlight"),
    },
    subheadline: t("faqPage.hero.subheadline"),
    cta: {
      primary: {
        text: t("faqPage.help.ctaRequest"),
        link: "/job-request",
        variant: "contained" as const,
      },
      secondary: {
        text: t("faqPage.help.ctaContact"),
        link: "/contact",
        variant: "outlined" as const,
      },
    },
  };

  return (
    <>
      <Helmet>
        <title>{t("faqPage.meta.title")}</title>
        <meta name="description" content={t("faqPage.meta.description")} />
        <meta
          name="keywords"
          content={(t("faqPage.meta.keywords", { returnObjects: true }) as string[]).join(", ")}
        />
        <link rel="canonical" href={`${window.location.origin}/faq`} />
      </Helmet>

      <Box component="main" sx={{ bgcolor: "background.default" }}>
        <HeroSection content={heroContent} />

        <Box
          component="section"
          sx={{
            py: { xs: 6, md: 8 },
            bgcolor: "background.paper",
          }}
        >
          <Container maxWidth="lg">
            {/* Search Bar */}
            <Box sx={{ mb: 4 }}>
              <TextField
                fullWidth
                placeholder={t("faqPage.search.placeholder")}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: "text.secondary" }} />
                    </InputAdornment>
                  ),
                }}
                sx={{
                  "& .MuiOutlinedInput-root": {
                    borderRadius: 2,
                    bgcolor: "background.default",
                  },
                }}
              />
            </Box>

            {/* Category Filters */}
            <Box
              sx={{
                display: "flex",
                flexWrap: "wrap",
                gap: 1.5,
                mb: 4,
              }}
            >
              {faqCategories.map((category) => (
                <Chip
                  key={category.id}
                  label={t(`faqPage.categories.${category.id}`)}
                  onClick={() => setSelectedCategory(category.id)}
                  sx={{
                    cursor: "pointer",
                    bgcolor:
                      selectedCategory === category.id
                        ? "text.primary"
                        : alpha("#f1f5f9", 0.6),
                    color:
                      selectedCategory === category.id
                        ? "background.paper"
                        : "text.secondary",
                    fontWeight: selectedCategory === category.id ? 600 : 400,
                    transition: "all 150ms ease",
                    "&:hover": {
                      bgcolor:
                        selectedCategory === category.id
                          ? "text.primary"
                          : alpha("#f1f5f9", 0.8),
                    },
                  }}
                />
              ))}
            </Box>

            {/* FAQ Results */}
            {filteredFAQs.length > 0 ? (
              <Box sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
                {filteredFAQs.map((faq, index) => (
                  <Accordion
                    key={index}
                    sx={{
                      borderRadius: 2,
                      border: "1px solid",
                      borderColor: "divider",
                      boxShadow: "none",
                      "&:before": {
                        display: "none",
                      },
                      "&.Mui-expanded": {
                        bgcolor: alpha("#f8fafc", 0.5),
                      },
                    }}
                  >
                    <AccordionSummary
                      expandIcon={<ExpandMoreIcon sx={{ color: "text.secondary" }} />}
                      sx={{
                        px: 3,
                        py: 2,
                        "&:hover": {
                          bgcolor: alpha("#f8fafc", 0.3),
                        },
                      }}
                    >
                      <Typography
                        variant="h6"
                        sx={{
                          fontWeight: 600,
                          fontSize: "1rem",
                          color: "text.primary",
                        }}
                      >
                        {faq.question}
                      </Typography>
                    </AccordionSummary>
                    <AccordionDetails sx={{ px: 3, pb: 3 }}>
                      <Typography
                        variant="body1"
                        sx={{
                          color: "text.secondary",
                          lineHeight: 1.75,
                          whiteSpace: "pre-line",
                        }}
                      >
                        {faq.answer}
                      </Typography>
                    </AccordionDetails>
                  </Accordion>
                ))}
              </Box>
            ) : (
              <Box
                sx={{
                  textAlign: "center",
                  py: 8,
                }}
              >
                <Typography
                  variant="h6"
                  sx={{
                    color: "text.secondary",
                    mb: 2,
                  }}
                >
                  {t("faqPage.empty.title")}
                </Typography>
                <Typography
                  variant="body2"
                  sx={{
                    color: "text.secondary",
                  }}
                >
                  {t("faqPage.empty.description")}
                </Typography>
              </Box>
            )}

            {/* Help Section */}
            <Box
              sx={{
                mt: 6,
                p: 4,
                borderRadius: 2,
                bgcolor: alpha("#f8fafc", 0.5),
                border: "1px solid",
                borderColor: "divider",
                textAlign: "center",
              }}
            >
              <Typography
                variant="h6"
                sx={{
                  fontWeight: 600,
                  mb: 2,
                  color: "text.primary",
                }}
              >
                {t("faqPage.help.title")}
              </Typography>
              <Typography
                variant="body1"
                sx={{
                  color: "text.secondary",
                  mb: 3,
                }}
              >
                {t("faqPage.help.description")}
              </Typography>
              <Box sx={{ display: "flex", gap: 2, justifyContent: "center" }}>
                <Chip
                  label={t("faqPage.help.ctaRequest")}
                  component="a"
                  href="/job-request"
                  clickable
                  sx={{
                    bgcolor: "text.primary",
                    color: "background.paper",
                    fontWeight: 600,
                    "&:hover": {
                      bgcolor: "text.primary",
                      opacity: 0.9,
                    },
                  }}
                />
                <Chip
                  label={t("faqPage.help.ctaContact")}
                  component="a"
                  href="/contact"
                  clickable
                  sx={{
                    bgcolor: "transparent",
                    color: "text.primary",
                    border: "1px solid",
                    borderColor: "text.primary",
                    fontWeight: 600,
                    "&:hover": {
                      bgcolor: alpha("#f8fafc", 0.8),
                    },
                  }}
                />
              </Box>
            </Box>
          </Container>
        </Box>
      </Box>
    </>
  );
};

export default FAQ;
