/**
 * Section Header Component
 * 
 * Reusable section header with badge, title, and description
 * Consistent styling across all sections
 */

import React from "react";
import { Box, Typography, Chip, alpha } from "@mui/material";
import { SectionHeader as SectionHeaderType } from "../../content/types";

interface SectionHeaderProps {
  content: SectionHeaderType;
  className?: string;
}

const SectionHeader: React.FC<SectionHeaderProps> = ({ content, className }) => {
  const { badge, title, description, alignment = "center" } = content;

  return (
    <Box
      className={className}
      sx={{
        textAlign: alignment,
        mb: { xs: 8, md: 10 },
      }}
    >
      {badge && (
        <Chip
          label={badge}
          sx={{
            mb: 3,
            bgcolor: alpha("#f1f5f9", 0.6),
            color: "text.secondary",
            fontWeight: 500,
            fontSize: "0.875rem",
            border: "1px solid",
            borderColor: "divider",
          }}
        />
      )}
      <Typography
        component="h2"
        variant="h2"
        sx={{
          fontSize: { xs: "2rem", md: "2.5rem" },
          fontWeight: 600,
          mb: description ? 2 : 0,
          color: "text.primary",
          lineHeight: 1.3,
        }}
      >
        {title}
      </Typography>
      {description && (
        <Typography
          variant="body1"
          component="p"
          sx={{
            fontSize: "1.125rem",
            color: "text.secondary",
            maxWidth: "600px",
            mx: alignment === "center" ? "auto" : 0,
            lineHeight: 1.7,
          }}
        >
          {description}
        </Typography>
      )}
    </Box>
  );
};

export default SectionHeader;
