/**
 * Testimonials Section Component
 * 
 * Displays client testimonials in a grid or carousel layout
 */

import React from "react";
import { Box, Container, Grid, alpha } from "@mui/material";
import SectionHeader from "./SectionHeader";
import { TestimonialCard, TestimonialContent } from "../cards";
import { SectionHeader as SectionHeaderType } from "../../content/types";

interface TestimonialsSectionProps {
  header: SectionHeaderType;
  testimonials: TestimonialContent[];
  maxItems?: number;
  className?: string;
}

const TestimonialsSection: React.FC<TestimonialsSectionProps> = ({
  header,
  testimonials,
  maxItems,
  className,
}) => {
  const displayTestimonials = maxItems
    ? testimonials.slice(0, maxItems)
    : testimonials;

  return (
    <Box
      component="section"
      className={className}
      sx={{
        py: { xs: 12, md: 16 },
        bgcolor: "background.default",
        position: "relative",
        overflow: "hidden",
        "&::before": {
          content: '""',
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: `radial-gradient(circle at 20% 30%, ${alpha("#475569", 0.03)} 0%, transparent 50%)`,
          zIndex: 0,
        },
      }}
    >
      <Container maxWidth="lg" sx={{ position: "relative", zIndex: 1 }}>
        <SectionHeader content={header} />
        <Grid container spacing={4} sx={{ mt: 6 }}>
          {displayTestimonials.map((testimonial) => (
            <Grid size={{ xs: 12, md: 6, lg: 4 }} key={testimonial.id}>
              <TestimonialCard testimonial={testimonial} />
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
};

export default TestimonialsSection;
