/**
 * Language Switcher Component
 * 
 * Allows users to switch between Vietnamese, English, and Japanese
 */

import React, { useState } from "react";
import {
  IconButton,
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText,
  Typography,
  Box,
} from "@mui/material";
import LanguageIcon from "@mui/icons-material/Language";
import CheckIcon from "@mui/icons-material/Check";
import { useTranslation } from "react-i18next";
import { SUPPORTED_LANGUAGES, LanguageCode } from "../i18n/config";
import { useCurrency } from "../contexts/CurrencyContext";
import type { CurrencyCode } from "./CurrencySwitcher";

const LanguageSwitcher: React.FC = () => {
  const { i18n } = useTranslation();
  const { setCurrency } = useCurrency();
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const open = Boolean(anchorEl);

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleLanguageChange = (langCode: LanguageCode) => {
    i18n.changeLanguage(langCode);

    // Sync currency with selected language (vi -> VND, en -> USD, ja -> JPY)
    const langToCurrency: Record<LanguageCode, CurrencyCode> = {
      vi: "VND",
      en: "USD",
      ja: "JPY",
    };
    setCurrency(langToCurrency[langCode]);

    handleClose();
  };

  return (
    <>
      <IconButton
        onClick={handleClick}
        sx={{
          color: "text.primary",
          "&:hover": {
            bgcolor: "action.hover",
          },
        }}
        aria-label="Change language"
        aria-controls={open ? "language-menu" : undefined}
        aria-haspopup="true"
        aria-expanded={open ? "true" : undefined}
      >
        <LanguageIcon />
      </IconButton>
      <Menu
        id="language-menu"
        anchorEl={anchorEl}
        open={open}
        onClose={handleClose}
        MenuListProps={{
          "aria-labelledby": "language-button",
        }}
        transformOrigin={{ horizontal: "right", vertical: "top" }}
        anchorOrigin={{ horizontal: "right", vertical: "bottom" }}
      >
        {SUPPORTED_LANGUAGES.map((lang) => (
          <MenuItem
            key={lang.code}
            onClick={() => handleLanguageChange(lang.code)}
            selected={i18n.language === lang.code}
            sx={{
              minWidth: 160,
            }}
          >
            <ListItemIcon>
              {i18n.language === lang.code && (
                <CheckIcon sx={{ fontSize: 20 }} />
              )}
            </ListItemIcon>
            <ListItemText
              primary={
                <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                  <Typography variant="body2" sx={{ fontWeight: 500 }}>
                    {lang.nativeName}
                  </Typography>
                  <Typography
                    variant="caption"
                    sx={{ color: "text.secondary" }}
                  >
                    {lang.name}
                  </Typography>
                </Box>
              }
            />
          </MenuItem>
        ))}
      </Menu>
    </>
  );
};

export default LanguageSwitcher;
