/**
 * Privacy Policy Page
 * 
 * Privacy policy in multiple languages
 */

import React from "react";
import { Box, Container, Typography, Divider } from "@mui/material";
import { useTranslation } from "react-i18next";
import Seo from "../components/SEO";
import Breadcrumbs from "../components/Breadcrumbs";

const PrivacyPolicy: React.FC = () => {
  const { t, i18n } = useTranslation();

  const breadcrumbs = [
    { label: t("nav.home"), path: "/" },
    { label: t("nav.privacyPolicy"), path: "/privacy-policy" },
  ];

  // Content based on language
  const content = {
    ja: {
      title: "プライバシーポリシー",
      lastUpdated: "最終更新日: 2024年1月",
      sections: [
        {
          title: "1. 個人情報の収集",
          content: "当サイトでは、お問い合わせフォーム、メール、電話を通じて以下の個人情報を収集する場合があります：お名前、メールアドレス、電話番号、会社名、プロジェクトに関する情報。",
        },
        {
          title: "2. 個人情報の使用目的",
          content: "収集した個人情報は、以下の目的で使用いたします：お問い合わせへの対応、サービス提供、プロジェクトの見積もり、コミュニケーション、サービス改善。",
        },
        {
          title: "3. 個人情報の保護",
          content: "お客様の個人情報を保護するため、適切なセキュリティ対策を実施しています。個人情報への不正アクセス、紛失、破壊、改ざんを防ぐための措置を講じています。",
        },
        {
          title: "4. 個人情報の第三者提供",
          content: "お客様の同意なく、個人情報を第三者に提供することはありません。ただし、法的義務がある場合や、お客様の安全を保護するために必要な場合を除きます。",
        },
        {
          title: "5. お客様の権利",
          content: "お客様は、ご自身の個人情報について、アクセス、訂正、削除、利用停止を要求する権利があります。ご要望がございましたら、お問い合わせください。",
        },
        {
          title: "6. Cookieの使用",
          content: "当サイトでは、ユーザー体験向上のため、Cookieを使用する場合があります。ブラウザの設定でCookieを無効にすることができます。",
        },
        {
          title: "7. お問い合わせ",
          content: "プライバシーポリシーに関するご質問は、お問い合わせページからご連絡ください。",
        },
      ],
    },
    en: {
      title: "Privacy Policy",
      lastUpdated: "Last Updated: January 2024",
      sections: [
        {
          title: "1. Information We Collect",
          content: "We may collect the following personal information through contact forms, email, or phone: name, email address, phone number, company name, and project-related information.",
        },
        {
          title: "2. How We Use Your Information",
          content: "We use collected information for: responding to inquiries, providing services, project quotations, communication, and service improvement.",
        },
        {
          title: "3. Data Protection",
          content: "We implement appropriate security measures to protect your personal information against unauthorized access, loss, destruction, or alteration.",
        },
        {
          title: "4. Third-Party Disclosure",
          content: "We do not share your personal information with third parties without your consent, except when required by law or to protect your safety.",
        },
        {
          title: "5. Your Rights",
          content: "You have the right to access, correct, delete, or restrict the use of your personal information. Please contact us for any requests.",
        },
        {
          title: "6. Cookies",
          content: "We may use cookies to improve user experience. You can disable cookies in your browser settings.",
        },
        {
          title: "7. Contact",
          content: "For questions about this privacy policy, please contact us through the contact page.",
        },
      ],
    },
    vi: {
      title: "Chính Sách Bảo Mật",
      lastUpdated: "Cập nhật lần cuối: Tháng 1, 2024",
      sections: [
        {
          title: "1. Thông Tin Chúng Tôi Thu Thập",
          content: "Chúng tôi có thể thu thập thông tin cá nhân sau đây thông qua form liên hệ, email, hoặc điện thoại: tên, email, số điện thoại, tên công ty, và thông tin về dự án.",
        },
        {
          title: "2. Cách Chúng Tôi Sử Dụng Thông Tin",
          content: "Chúng tôi sử dụng thông tin đã thu thập để: trả lời yêu cầu, cung cấp dịch vụ, báo giá dự án, giao tiếp, và cải thiện dịch vụ.",
        },
        {
          title: "3. Bảo Vệ Dữ Liệu",
          content: "Chúng tôi thực hiện các biện pháp bảo mật phù hợp để bảo vệ thông tin cá nhân của bạn khỏi truy cập trái phép, mất mát, phá hủy, hoặc thay đổi.",
        },
        {
          title: "4. Chia Sẻ Với Bên Thứ Ba",
          content: "Chúng tôi không chia sẻ thông tin cá nhân của bạn với bên thứ ba mà không có sự đồng ý của bạn, trừ khi được yêu cầu bởi pháp luật hoặc để bảo vệ an toàn của bạn.",
        },
        {
          title: "5. Quyền Của Bạn",
          content: "Bạn có quyền truy cập, chỉnh sửa, xóa, hoặc hạn chế việc sử dụng thông tin cá nhân của bạn. Vui lòng liên hệ với chúng tôi cho bất kỳ yêu cầu nào.",
        },
        {
          title: "6. Cookie",
          content: "Chúng tôi có thể sử dụng cookie để cải thiện trải nghiệm người dùng. Bạn có thể vô hiệu hóa cookie trong cài đặt trình duyệt của mình.",
        },
        {
          title: "7. Liên Hệ",
          content: "Đối với các câu hỏi về chính sách bảo mật này, vui lòng liên hệ với chúng tôi qua trang liên hệ.",
        },
      ],
    },
  };

  const currentContent = content[i18n.language as keyof typeof content] || content.en;

  return (
    <>
      <Seo
        content={{
          meta: {
            title: `${currentContent.title} | Nguyễn Văn An`,
            description: i18n.language === "ja"
              ? "プライバシーポリシー - 個人情報の保護と使用に関する方針"
              : i18n.language === "en"
              ? "Privacy Policy - How we collect, use, and protect your personal information"
              : "Chính Sách Bảo Mật - Cách chúng tôi thu thập, sử dụng và bảo vệ thông tin cá nhân của bạn",
            keywords: [],
          },
        }}
      />
      <Box component="main" sx={{ bgcolor: "background.default" }}>
        <Container maxWidth="md" sx={{ py: { xs: 6, md: 8 } }}>
          <Breadcrumbs items={breadcrumbs.slice(0, -1)} />
          
          <Typography
            component="h1"
            variant="h3"
            sx={{
              fontWeight: 700,
              mb: 2,
              color: "text.primary",
              mt: 4,
            }}
          >
            {currentContent.title}
          </Typography>

          <Typography
            variant="body2"
            sx={{
              color: "text.secondary",
              mb: 4,
            }}
          >
            {currentContent.lastUpdated}
          </Typography>

          <Divider sx={{ mb: 4 }} />

          {currentContent.sections.map((section, index) => (
            <Box key={index} sx={{ mb: 4 }}>
              <Typography
                component="h2"
                variant="h5"
                sx={{
                  fontWeight: 600,
                  mb: 2,
                  color: "text.primary",
                }}
              >
                {section.title}
              </Typography>
              <Typography
                sx={{
                  color: "text.secondary",
                  lineHeight: 1.8,
                  fontSize: "1rem",
                }}
              >
                {section.content}
              </Typography>
            </Box>
          ))}

          <Divider sx={{ my: 4 }} />

          <Typography
            variant="body2"
            sx={{
              color: "text.secondary",
              fontStyle: "italic",
            }}
          >
            {i18n.language === "ja"
              ? "このプライバシーポリシーは、当サイトの利用に関する重要な情報を含んでいます。ご不明な点がございましたら、お気軽にお問い合わせください。"
              : i18n.language === "en"
              ? "This privacy policy contains important information about the use of this website. If you have any questions, please feel free to contact us."
              : "Chính sách bảo mật này chứa thông tin quan trọng về việc sử dụng website này. Nếu bạn có bất kỳ câu hỏi nào, vui lòng liên hệ với chúng tôi."}
          </Typography>
        </Container>
      </Box>
    </>
  );
};

export default PrivacyPolicy;
