/**
 * Services Page - Content-Driven Architecture
 * 
 * Lists all available services with detailed information
 */

import React from "react";
import { Box, Container, Grid, Divider, Typography } from "@mui/material";
import { SectionHeader, CTASection } from "../components/sections";
import { ServiceCard } from "../components/cards";
import Icon from "../components/Icon";
import SEO from "../components/SEO";
import {
  servicesPageConfig,
  servicesPageContent,
  servicesPageSection,
  servicesContent,
  processSection,
  servicesFAQs,
  ctaSection,
} from "../content";
import { generateServiceSchema, generateFAQSchema } from "../utils/seo";
import { processIconMap } from "../utils/iconMapping";
import { useTranslation } from "react-i18next";

const Services: React.FC = () => {
  const { t } = useTranslation();
  // Generate Service schemas for all services
  const serviceSchemas = servicesContent.map((service) =>
    generateServiceSchema(
      service.title,
      service.description,
      service.title
    )
  );

  // Generate FAQ schema
  const faqSchema = generateFAQSchema(servicesFAQs);

  return (
    <>
      <SEO
        content={servicesPageContent}
        structuredData={[...serviceSchemas, faqSchema]}
      />
      <Box component="main" sx={{ bgcolor: "background.default" }}>
      {/* Hero Section - Có thể ẩn/hiện qua config */}
      {servicesPageConfig.showHero && (
        <>
          <Box
            component="section"
            sx={{
              py: { xs: 8, md: 12 },
              bgcolor: "background.paper",
            }}
          >
            <Container maxWidth="lg">
              <SectionHeader content={servicesPageSection} />
            </Container>
          </Box>
          <Divider sx={{ borderColor: "divider" }} />
        </>
      )}

      {/* Services Grid */}
      <Box
        component="section"
        aria-labelledby="services-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: "background.default",
        }}
      >
        <Container maxWidth="lg">
          <Grid container spacing={3}>
            {servicesContent.map((service) => (
              <Grid size={{ xs: 6, md: 6, lg: 4 }} key={service.id}>
                <ServiceCard service={service} showFeatures={4} />
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      <Divider sx={{ borderColor: "divider" }} />

      {/* Process Section */}
      <Box
        component="section"
        aria-labelledby="process-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: "background.paper",
        }}
      >
        <Container maxWidth="lg">
          <SectionHeader
            content={{
              title: processSection.title,
              description: processSection.description,
              alignment: "center",
            }}
          />
          <Grid container spacing={4}>
            {processSection.steps.map((step) => (
              <Grid size={{ xs: 12, sm: 6, lg: 3 }} key={step.step}>
                <Box
                  sx={{
                    textAlign: "center",
                    p: 4,
                    bgcolor: "background.default",
                    borderRadius: 2,
                    border: "1px solid",
                    borderColor: "divider",
                    height: "100%",
                  }}
                >
                  <Box
                    sx={{
                      mb: 2,
                      display: "flex",
                      justifyContent: "center",
                    }}
                    aria-hidden="true"
                  >
                    <Icon
                      name={processIconMap[step.step]}
                      size="xxlarge"
                      color="primary"
                    />
                  </Box>
                  <Typography
                    component="h3"
                    sx={{
                      fontWeight: 600,
                      mb: 1,
                      color: "text.primary",
                      fontSize: "1.125rem",
                    }}
                    >
                    {t("services.process.step")} {step.step}
                  </Typography>
                  <Typography
                    component="h4"
                    sx={{
                      fontWeight: 500,
                      mb: 1,
                      color: "text.primary",
                      fontSize: "1rem",
                    }}
                  >
                    {step.title}
                  </Typography>
                  <Typography
                    component="p"
                    sx={{
                      color: "text.secondary",
                      fontSize: "0.875rem",
                      lineHeight: 1.6,
                    }}
                  >
                    {step.description}
                  </Typography>
                </Box>
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      <Divider sx={{ borderColor: "divider" }} />

      {/* FAQ Section */}
      <Box
        component="section"
        aria-labelledby="faq-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: "background.default",
        }}
      >
        <Container maxWidth="lg">
          <SectionHeader
            content={{
              title: t("services.faq.title"),
              description: t("services.faq.description"),
              alignment: "center",
            }}
          />
          <Box sx={{ mt: 6, maxWidth: "800px", mx: "auto" }}>
            {servicesFAQs.map((faq, index) => (
              <Box
                key={index}
                sx={{
                  mb: 4,
                  p: 4,
                  bgcolor: "background.paper",
                  borderRadius: 2,
                  border: "1px solid",
                  borderColor: "divider",
                }}
              >
                <Typography
                  component="h3"
                  sx={{
                    fontWeight: 600,
                    mb: 2,
                    color: "text.primary",
                    fontSize: "1.125rem",
                  }}
                >
                  {faq.question}
                </Typography>
                <Typography
                  component="p"
                  sx={{
                    color: "text.secondary",
                    fontSize: "0.9375rem",
                    lineHeight: 1.7,
                  }}
                >
                  {faq.answer}
                </Typography>
              </Box>
            ))}
          </Box>
        </Container>
      </Box>

      <Divider sx={{ borderColor: "divider" }} />

      {/* CTA Section */}
      <CTASection content={ctaSection} />
      </Box>
    </>
  );
};

export default Services;
