import React, { useState, useMemo } from "react";
import { Link, useLocation } from "react-router-dom";
import {
  AppBar,
  Toolbar,
  Box,
  Button,
  IconButton,
  Menu,
  MenuItem,
  Container,
  Typography,
  Collapse,
  alpha,
} from "@mui/material";
import MenuIcon from "@mui/icons-material/Menu";
import CloseIcon from "@mui/icons-material/Close";
import { useNavContent, useServicesContent } from "../utils/contentHelper";
import { headerContent, navMicroCopy } from "../content";
import LanguageSwitcher from "./LanguageSwitcher";
import CurrencySwitcher from "./CurrencySwitcher";

/**
 * Header - Japanese Minimal Design
 * 
 * Design Principles:
 * - Clean, unobtrusive navigation
 * - Subtle elevation, soft shadows
 * - Purposeful interactions (< 200ms)
 * - Balanced typography
 */

const Header: React.FC = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState<{ [key: string]: HTMLElement | null }>({});
  const location = useLocation();
  const navContent = useNavContent();
  const servicesContent = useServicesContent();

  // Build NAV_ITEMS from translations - Optimized menu structure
  const NAV_ITEMS = useMemo(() => [
    { label: navContent.home, path: "/" },
    {
      label: navContent.services,
      path: "/services",
      children: [
        ...servicesContent.servicesList.map((service) => ({
          label: service.title,
          path: service.link,
        })),
      ],
    },
    { label: navContent.portfolio, path: "/portfolio" },
    { label: navContent.pricing, path: "/pricing" },
    { label: navContent.contact, path: "/contact" },
    {
      label: navContent.more,
      path: "/more",
      children: [
        { label: navContent.blog, path: "/blog" },
        { label: navContent.about, path: "/about" },
        { label: navContent.faq, path: "/faq" },
        { label: navContent.caseStudies, path: "/case-studies" },
      ],
    },
  ], [navContent, servicesContent]);

  const isActive = (path: string) => {
    return location.pathname === path;
  };

  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>, itemPath: string) => {
    setAnchorEl({ ...anchorEl, [itemPath]: event.currentTarget });
  };

  const handleMenuClose = (itemPath: string) => {
    setAnchorEl({ ...anchorEl, [itemPath]: null });
  };

  return (
    <AppBar
      position="sticky"
      elevation={0}
      sx={{
        bgcolor: alpha("#ffffff", 0.8),
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
        borderBottom: "1px solid",
        borderColor: "divider",
        zIndex: 50,
      }}
    >
      <Container maxWidth="lg">
        <Toolbar
          sx={{
            minHeight: { xs: "64px !important", md: "72px !important" },
            justifyContent: "space-between",
            px: { xs: 2, md: 0 },
            gap: 2,
          }}
        >
                {/* Logo */}
                <Box
                  component={Link}
                  to="/"
                  aria-label={`${headerContent.logo.text} - Home`}
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1.5,
                    textDecoration: "none",
                    transition: "opacity 150ms ease",
                    "&:hover": {
                      opacity: 0.8,
                    },
                  }}
                >
                  <Box
                    component="img"
                    src="/logo/logo.png"
                    alt={headerContent.logo.text}
                    sx={{
                      height: { xs: 36, md: 55 },
                      width: { xs: 36, md: 60 },
                      borderRadius: "50%",
                      "&:hover": {
                        transform: "scale(1.05)",
                      },
                    }}
                  />
                  <Typography
                    component="span"
                    variant="h6"
                    sx={{
                      display: { xs: "none", sm: "block" },
                      fontWeight: 600,
                      color: "text.primary",
                      fontSize: "1.125rem",
                    }}
                  >
                    {headerContent.logo.text}
                  </Typography>
                </Box>

          {/* Desktop Menu - Clean Navigation */}
          <Box sx={{ 
            display: { xs: "none", md: "flex" }, 
            alignItems: "center", 
            gap: 0.5, 
            flexWrap: "nowrap",
            flex: 1,
            justifyContent: "center",
            mx: 4,
          }}>
            {NAV_ITEMS.map((item) => (
              <Box key={item.path} sx={{ position: "relative", flexShrink: 0 }}>
                {item.children ? (
                  <>
                    <Button
                      id={`${item.path}-menu-button`}
                      aria-label={`${item.label} menu`}
                      aria-haspopup="true"
                      aria-expanded={Boolean(anchorEl[item.path])}
                      onMouseEnter={(e: React.MouseEvent<HTMLElement>) => handleMenuOpen(e, item.path)}
                      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
                        // For "More" menu, prevent navigation
                        if (item.path === "/more") {
                          e.preventDefault();
                        }
                      }}
                      component={item.path !== "/more" ? Link : "button"}
                      to={item.path !== "/more" ? item.path : undefined}
                      sx={{
                        px: 1.75,
                        py: 1,
                        minHeight: 44, // WCAG: Minimum 44px touch target
                        borderRadius: 1.5,
                        fontSize: "0.875rem",
                        fontWeight: isActive(item.path) ? 600 : 400,
                        color: isActive(item.path) ? "text.primary" : "text.secondary",
                        bgcolor: isActive(item.path) ? alpha("#f1f5f9", 0.6) : "transparent",
                        transition: "all 200ms cubic-bezier(0.4, 0, 0.2, 1)",
                        textTransform: "none",
                        whiteSpace: "nowrap",
                        "&:hover": {
                          color: "text.primary",
                          bgcolor: alpha("#f8fafc", 0.8),
                          transform: "translateY(-1px)",
                        },
                      }}
                    >
                      {item.label}
                    </Button>
                    <Menu
                      anchorEl={anchorEl[item.path]}
                      open={Boolean(anchorEl[item.path])}
                      onClose={() => handleMenuClose(item.path)}
                      anchorOrigin={{
                        vertical: "bottom",
                        horizontal: "left",
                      }}
                      transformOrigin={{
                        vertical: "top",
                        horizontal: "left",
                      }}
                      slotProps={{
                        paper: {
                          sx: {
                            mt: 1.5,
                            minWidth: 240,
                            borderRadius: 2,
                            bgcolor: "background.paper",
                            border: "1px solid",
                            borderColor: "divider",
                            boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1)",
                            py: 0.5,
                          },
                        },
                        root: {
                          onMouseLeave: () => handleMenuClose(item.path),
                          "aria-labelledby": `${item.path}-menu-button`,
                        },
                      }}
                    >
                      {item.children.map((child, index) => (
                        <MenuItem
                          key={child.path}
                          component={Link}
                          to={child.path}
                          onClick={() => handleMenuClose(item.path)}
                          aria-label={`Navigate to ${child.label}`}
                          sx={{
                            mx: 1,
                            my: 0.5,
                            minHeight: 44, // WCAG: Minimum 44px touch target
                            borderRadius: 1.5,
                            color: "text.secondary",
                            fontSize: "0.9375rem",
                            transition: "all 150ms ease",
                            textTransform: "none",
                            "&:hover": {
                              bgcolor: alpha("#f8fafc", 0.8),
                              color: "text.primary",
                              transform: "translateX(4px)",
                            },
                          }}
                        >
                          {child.label}
                        </MenuItem>
                      ))}
                    </Menu>
                  </>
                ) : (
                    <Button
                      component={Link}
                      to={item.path}
                      sx={{
                        px: 1.75,
                        py: 1,
                        minHeight: 44, // WCAG: Minimum 44px touch target
                        borderRadius: 1.5,
                        fontSize: "0.875rem",
                        fontWeight: isActive(item.path) ? 600 : 400,
                        color: isActive(item.path) ? "text.primary" : "text.secondary",
                        bgcolor: isActive(item.path) ? alpha("#f1f5f9", 0.6) : "transparent",
                        transition: "all 200ms cubic-bezier(0.4, 0, 0.2, 1)",
                        textTransform: "none",
                        whiteSpace: "nowrap",
                        "&:hover": {
                          color: "text.primary",
                          bgcolor: alpha("#f8fafc", 0.8),
                          transform: "translateY(-1px)",
                        },
                      }}
                    >
                      {item.label}
                    </Button>
                )}
              </Box>
            ))}
          </Box>

          {/* Right Side Actions - Request Quote + Switchers */}
          <Box sx={{ 
            display: { xs: "none", md: "flex" }, 
            alignItems: "center", 
            gap: 1.5,
            flexShrink: 0,
          }}>
            <CurrencySwitcher />
            <LanguageSwitcher />
            <Button
              component={Link}
              to="/job-request"
              variant="contained"
              sx={{
                px: 3,
                py: 1.25,
                minHeight: 44, // WCAG: Minimum 44px touch target
                borderRadius: 2.5,
                fontWeight: 600,
                fontSize: "0.875rem",
                bgcolor: "text.primary",
                color: "background.paper",
                boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
                border: "1px solid",
                borderColor: "text.primary",
                textTransform: "none",
                whiteSpace: "nowrap",
                transition: "all 200ms cubic-bezier(0.4, 0, 0.2, 1)",
                "&:hover": {
                  bgcolor: "text.primary",
                  color: "background.paper",
                  boxShadow: "0 4px 12px rgba(0, 0, 0, 0.15)",
                  transform: "translateY(-2px)",
                },
              }}
            >
              {navContent.jobRequest}
            </Button>
          </Box>

          {/* Mobile Menu Button */}
          <Box sx={{ display: { xs: "flex", md: "none" }, alignItems: "center", gap: 1 }}>
            <CurrencySwitcher />
            <LanguageSwitcher />
            <IconButton
              sx={{
                color: "text.primary",
                minWidth: 44,
                minHeight: 44,
                transition: "all 150ms ease",
                "&:hover": {
                  bgcolor: alpha("#f8fafc", 0.8),
                },
              }}
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              aria-label={navMicroCopy.ariaLabels.menuToggle}
            >
              {isMenuOpen ? <CloseIcon /> : <MenuIcon />}
            </IconButton>
          </Box>
        </Toolbar>

               {/* Mobile Menu - Clean */}
               <Collapse in={isMenuOpen} sx={{ display: { xs: "block", md: "none" } }}>
                 <Box
                   id="mobile-menu"
                   role="navigation"
                   aria-label="Main navigation"
                   sx={{
                     py: 3,
                     borderTop: "1px solid",
                     borderColor: "divider",
                     bgcolor: "background.paper",
                   }}
                 >
                   {NAV_ITEMS.map((item) => (
                     <Box key={item.path} sx={{ mb: 1.5 }}>
                       <Button
                         component={Link}
                         to={item.path}
                         fullWidth
                         onClick={() => setIsMenuOpen(false)}
                         aria-label={`Navigate to ${item.label}`}
                         aria-current={isActive(item.path) ? "page" : undefined}
                         sx={{
                           px: 3,
                           py: 1.75,
                           minHeight: 44, // WCAG: Minimum 44px touch target
                           borderRadius: 2,
                           fontSize: "0.9375rem",
                           fontWeight: isActive(item.path) ? 600 : 400,
                           color: isActive(item.path) ? "text.primary" : "text.secondary",
                           bgcolor: isActive(item.path) ? alpha("#f1f5f9", 0.6) : "transparent",
                           justifyContent: "flex-start",
                           textTransform: "none",
                           transition: "all 200ms ease",
                           "&:hover": {
                             color: "text.primary",
                             bgcolor: alpha("#f8fafc", 0.8),
                           },
                         }}
                       >
                         {item.label}
                       </Button>
                       {item.children && (
                         <Box 
                           role="group"
                           aria-label={`${item.label} submenu`}
                           sx={{ pl: 3, mt: 1 }}
                         >
                           {item.children.map((child) => (
                             <Button
                               key={child.path}
                               component={Link}
                               to={child.path}
                               fullWidth
                               onClick={() => setIsMenuOpen(false)}
                               aria-label={`Navigate to ${child.label}`}
                               sx={{
                                 px: 3,
                                 py: 1.5,
                                 minHeight: 44, // WCAG: Minimum 44px touch target
                                 borderRadius: 2,
                                 fontSize: "0.875rem",
                                 fontWeight: 400,
                                 color: "text.secondary",
                                 justifyContent: "flex-start",
                                 textTransform: "none",
                                 transition: "all 200ms ease",
                                 "&:hover": {
                                   color: "text.primary",
                                   bgcolor: alpha("#f8fafc", 0.8),
                                   transform: "translateX(4px)",
                                 },
                               }}
                             >
                               {child.label}
                             </Button>
                           ))}
                         </Box>
                       )}
              </Box>
            ))}
            <Button
              component={Link}
              to="/job-request"
              variant="contained"
              fullWidth
              onClick={() => setIsMenuOpen(false)}
              sx={{
                mt: 3,
                px: 3,
                py: 1.75,
                minHeight: 44, // WCAG: Minimum 44px touch target
                borderRadius: 2,
                fontWeight: 600,
                fontSize: "0.9375rem",
                bgcolor: "text.primary",
                color: "background.paper",
                boxShadow: "none",
                border: "1px solid",
                borderColor: "text.primary",
                textTransform: "none",
                transition: "all 200ms cubic-bezier(0.4, 0, 0.2, 1)",
                "&:hover": {
                  bgcolor: "text.primary",
                  color: "background.paper",
                  boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1)",
                  transform: "translateY(-2px)",
                },
              }}
            >
              {navContent.jobRequest}
            </Button>
          </Box>
        </Collapse>
      </Container>
    </AppBar>
  );
};

export default Header;
