/**
 * Service Detail Page
 * 
 * Displays detailed information about a specific service
 * Uses translations for multi-language support
 */

import React from "react";
import { useParams, Link } from "react-router-dom";
import {
  Box,
  Container,
  Grid,
  Typography,
  Button,
  Divider,
  ListItemIcon,
  alpha,
} from "@mui/material";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import { useTranslation } from "react-i18next";
import { useServicesContent, useNavContent } from "../utils/contentHelper";
import SEO from "../components/SEO";
import Icon from "../components/Icon";
import { normalizeIconName } from "../utils/iconMapping";
import { generateServiceSchema, generateBreadcrumbSchema } from "../utils/seo";
import Breadcrumbs from "../components/Breadcrumbs";
import { ServiceCard } from "../components/cards";

const ServiceDetail: React.FC = () => {
  const { serviceId } = useParams<{ serviceId: string }>();
  const { t } = useTranslation();
  const servicesContent = useServicesContent();
  const navContent = useNavContent();

  // Find service by ID
  const service = servicesContent.servicesList.find(
    (s) => s.id === serviceId
  );

  // If service not found, show 404
  if (!service) {
    return (
      <>
        <SEO
          content={{
            meta: {
              title: t("services.detail.notFound.title"),
              description: t("services.detail.notFound.description"),
              keywords: [],
            },
          }}
        />
        <Box component="main" sx={{ bgcolor: "background.default", minHeight: "60vh" }}>
          <Container maxWidth="lg" sx={{ py: 12, textAlign: "center" }}>
            <Typography variant="h4" sx={{ mb: 2, color: "text.primary" }}>
              {t("services.detail.notFound.title")}
            </Typography>
            <Typography sx={{ mb: 4, color: "text.secondary" }}>
              {t("services.detail.notFound.description")}
            </Typography>
            <Button component={Link} to="/services" variant="contained">
              {t("services.detail.notFound.backButton")}
            </Button>
          </Container>
        </Box>
      </>
    );
  }

  // Generate SEO schema
  const serviceSchema = generateServiceSchema(
    service.title,
    service.description,
    service.title
  );

  // Breadcrumbs
  const breadcrumbs = [
    { label: t("nav.home"), path: "/" },
    { label: t("nav.services"), path: "/services" },
    { label: service.title, path: service.link },
  ];

  const breadcrumbSchema = generateBreadcrumbSchema(
    breadcrumbs.map((b) => ({
      name: b.label,
      url: b.path,
    }))
  );

  // Smart related services algorithm
  const getRelatedServices = (
    currentService: typeof service,
    allServices: typeof servicesContent.servicesList,
    limit: number = 4
  ) => {
    const calculateScore = (current: typeof service, candidate: typeof service): number => {
      let score = 0;
      
      // Similar technologies (if both have tech stack mentioned)
      if (current.technologies && candidate.technologies) {
        const currentTechs = current.technologies.toLowerCase();
        const candidateTechs = candidate.technologies.toLowerCase();
        const techKeywords = ["react", "node", "python", "aws", "ai", "ml", "typescript"];
        techKeywords.forEach((keyword) => {
          if (currentTechs.includes(keyword) && candidateTechs.includes(keyword)) {
            score += 5;
          }
        });
      }
      
      // Featured services: +3 points
      // (Assuming featured field exists, if not, can be added)
      
      return score;
    };

    // Calculate scores
    const scored = allServices
      .filter((s) => s.id !== currentService.id)
      .map((candidate) => ({
        service: candidate,
        score: calculateScore(currentService, candidate),
      }))
      .sort((a, b) => b.score - a.score);

    // Get top scored services, fallback to all if needed
    const topScored = scored
      .slice(0, limit)
      .map((s) => s.service);

    // Ensure minimum 3 services
    if (topScored.length < 3) {
      const fallback = allServices
        .filter(
          (s) =>
            s.id !== currentService.id &&
            !topScored.some((ts) => ts.id === s.id)
        )
        .slice(0, 3 - topScored.length);
      topScored.push(...fallback);
    }

    return topScored;
  };

  const relatedServices = getRelatedServices(service, servicesContent.servicesList, 4);

  return (
    <>
      <SEO
        content={{
          meta: {
            title: `${service.title} | ${servicesContent.meta.title}`,
            description: service.description,
            keywords: [service.title, service.shortDescription],
          },
        }}
        structuredData={[serviceSchema, breadcrumbSchema]}
      />
      <Box component="main" sx={{ bgcolor: "background.default" }}>
        {/* Back Button */}
        <Box
          sx={{
            py: 3,
            borderBottom: "1px solid",
            borderColor: "divider",
            bgcolor: "background.paper",
          }}
        >
          <Container maxWidth="lg">
            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 2 }}>
              <Button
                component={Link}
                to="/services"
                startIcon={<ArrowBackIcon />}
                sx={{
                  color: "text.secondary",
                  "&:hover": {
                    color: "text.primary",
                  },
                }}
              >
                {t("services.detail.backToServices")}
              </Button>
              <Breadcrumbs items={breadcrumbs.slice(0, -1)} />
            </Box>
          </Container>
        </Box>

        {/* Hero Section */}
        <Box
          component="section"
          sx={{
            py: { xs: 8, md: 12 },
            bgcolor: "background.paper",
          }}
        >
          <Container maxWidth="lg">
            <Grid container spacing={4} alignItems="center">
              <Grid size={{ xs: 12, md: 8 }}>
                <Box sx={{ mb: 3 }}>
                  <Icon
                    name={normalizeIconName(service.icon)}
                    size="xxlarge"
                    container
                    containerSize={80}
                    color="primary"
                  />
                </Box>
                <Typography
                  component="h1"
                  variant="h3"
                  sx={{
                    fontWeight: 600,
                    mb: 2,
                    color: "text.primary",
                    fontSize: { xs: "2rem", md: "2.5rem" },
                  }}
                >
                  {service.title}
                </Typography>
                <Typography
                  component="p"
                  sx={{
                    color: "text.secondary",
                    fontSize: "1.125rem",
                    lineHeight: 1.7,
                    mb: 3,
                  }}
                >
                  {service.description}
                </Typography>
                {service.detailedDescription && (
                  <Typography
                    component="p"
                    sx={{
                      color: "text.secondary",
                      fontSize: "1rem",
                      lineHeight: 1.8,
                      mb: 4,
                    }}
                  >
                    {service.detailedDescription}
                  </Typography>
                )}
                <Button
                  component={Link}
                  to="/job-request"
                  variant="contained"
                  size="large"
                  sx={{
                    px: 4,
                    py: 1.5,
                    fontSize: "1rem",
                    fontWeight: 500,
                  }}
                >
                  {navContent.jobRequest}
                </Button>
              </Grid>
            </Grid>
          </Container>
        </Box>

        <Divider sx={{ borderColor: "divider" }} />

        {/* Benefits Section */}
        {service.benefits && service.benefits.length > 0 && (
          <Box
            component="section"
            sx={{
              py: { xs: 12, md: 16 },
              bgcolor: "background.default",
            }}
          >
            <Container maxWidth="lg">
              <Typography
                component="h2"
                variant="h4"
                sx={{
                  fontWeight: 600,
                  mb: 4,
                  color: "text.primary",
                  textAlign: "center",
                }}
              >
                {t("services.detail.benefits")}
              </Typography>
              <Grid container spacing={3}>
                {service.benefits.map((benefit, index) => (
                  <Grid size={{ xs: 12, sm: 6, md: 4 }} key={index}>
                    <Box
                      sx={{
                        p: 3,
                        bgcolor: "background.paper",
                        borderRadius: 2,
                        border: "1px solid",
                        borderColor: "divider",
                        height: "100%",
                        display: "flex",
                        alignItems: "flex-start",
                        gap: 2,
                      }}
                    >
                      <CheckCircleIcon
                        sx={{
                          fontSize: 24,
                          color: "primary.main",
                          flexShrink: 0,
                          mt: 0.5,
                        }}
                      />
                      <Typography
                        component="p"
                        sx={{
                          fontWeight: 400,
                          color: "text.primary",
                          fontSize: "0.9375rem",
                          lineHeight: 1.7,
                        }}
                      >
                        {benefit}
                      </Typography>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Container>
          </Box>
        )}

        <Divider sx={{ borderColor: "divider" }} />

        {/* Use Cases Section */}
        {service.useCases && service.useCases.length > 0 && (
          <Box
            component="section"
            sx={{
              py: { xs: 12, md: 16 },
              bgcolor: "background.paper",
            }}
          >
            <Container maxWidth="lg">
              <Typography
                component="h2"
                variant="h4"
                sx={{
                  fontWeight: 600,
                  mb: 4,
                  color: "text.primary",
                  textAlign: "center",
                }}
              >
                {t("services.detail.useCases")}
              </Typography>
              <Grid container spacing={2}>
                {service.useCases.map((useCase, index) => (
                  <Grid size={{ xs: 12, md: 6 }} key={index}>
                    <Box
                      sx={{
                        p: 3,
                        bgcolor: "background.default",
                        borderRadius: 2,
                        border: "1px solid",
                        borderColor: "divider",
                        display: "flex",
                        alignItems: "flex-start",
                        gap: 2,
                      }}
                    >
                      <Box
                        sx={{
                          width: 24,
                          height: 24,
                          borderRadius: "50%",
                          bgcolor: "primary.main",
                          color: "background.paper",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          fontSize: "0.75rem",
                          fontWeight: 600,
                          flexShrink: 0,
                          mt: 0.5,
                        }}
                      >
                        {index + 1}
                      </Box>
                      <Typography
                        component="p"
                        sx={{
                          fontWeight: 400,
                          color: "text.primary",
                          fontSize: "0.9375rem",
                          lineHeight: 1.7,
                        }}
                      >
                        {useCase}
                      </Typography>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Container>
          </Box>
        )}

        <Divider sx={{ borderColor: "divider" }} />

        {/* Technologies & Why Choose Section */}
        <Box
          component="section"
          sx={{
            py: { xs: 12, md: 16 },
            bgcolor: "background.default",
          }}
        >
          <Container maxWidth="lg">
            <Grid container spacing={4}>
              {service.technologies && (
                <Grid size={{ xs: 12, md: 6 }}>
                  <Typography
                    component="h2"
                    variant="h5"
                    sx={{
                      fontWeight: 600,
                      mb: 3,
                      color: "text.primary",
                    }}
                  >
                    {t("services.detail.technologies")}
                  </Typography>
                  <Box
                    sx={{
                      p: 3,
                      bgcolor: "background.paper",
                      borderRadius: 2,
                      border: "1px solid",
                      borderColor: "divider",
                    }}
                  >
                    <Typography
                      sx={{
                        color: "text.secondary",
                        fontSize: "0.9375rem",
                        lineHeight: 1.7,
                      }}
                    >
                      {service.technologies}
                    </Typography>
                  </Box>
                </Grid>
              )}
              {service.whyChoose && (
                <Grid size={{ xs: 12, md: 6 }}>
                  <Typography
                    component="h2"
                    variant="h5"
                    sx={{
                      fontWeight: 600,
                      mb: 3,
                      color: "text.primary",
                    }}
                  >
                    {t("services.detail.whyChoose")}
                  </Typography>
                  <Box
                    sx={{
                      p: 3,
                      bgcolor: "background.paper",
                      borderRadius: 2,
                      border: "1px solid",
                      borderColor: "divider",
                    }}
                  >
                    <Typography
                      sx={{
                        color: "text.secondary",
                        fontSize: "0.9375rem",
                        lineHeight: 1.8,
                      }}
                    >
                      {service.whyChoose}
                    </Typography>
                  </Box>
                </Grid>
              )}
            </Grid>
          </Container>
        </Box>

        <Divider sx={{ borderColor: "divider" }} />

        {/* Features Section */}
        {service.features && service.features.length > 0 && (
          <Box
            component="section"
            sx={{
              py: { xs: 12, md: 16 },
              bgcolor: "background.default",
            }}
          >
            <Container maxWidth="lg">
              <Typography
                component="h2"
                variant="h4"
                sx={{
                  fontWeight: 600,
                  mb: 4,
                  color: "text.primary",
                  textAlign: "center",
                }}
              >
                {t("services.detail.features")}
              </Typography>
              <Grid container spacing={3}>
                {service.features.map((feature, index) => (
                  <Grid size={{ xs: 12, sm: 6, md: 4 }} key={index}>
                    <Box
                      sx={{
                        p: 3,
                        bgcolor: "background.paper",
                        borderRadius: 2,
                        border: "1px solid",
                        borderColor: "divider",
                        height: "100%",
                      }}
                    >
                      <ListItemIcon sx={{ minWidth: 40, mb: 1 }}>
                        <CheckCircleIcon
                          sx={{
                            fontSize: 24,
                            color: "primary.main",
                          }}
                        />
                      </ListItemIcon>
                      <Typography
                        component="h3"
                        sx={{
                          fontWeight: 500,
                          color: "text.primary",
                          fontSize: "1rem",
                        }}
                      >
                        {feature}
                      </Typography>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Container>
          </Box>
        )}

        <Divider sx={{ borderColor: "divider" }} />

        {/* Related Services Section */}
        {relatedServices.length > 0 && (
          <Box
            component="section"
            sx={{
              py: { xs: 12, md: 16 },
              bgcolor: "background.paper",
            }}
          >
            <Container maxWidth="lg">
              <Typography
                component="h2"
                variant="h4"
                sx={{
                  fontWeight: 600,
                  mb: 4,
                  color: "text.primary",
                  textAlign: "center",
                }}
              >
                {t("services.detail.relatedServices") || "Dịch Vụ Liên Quan"}
              </Typography>
              <Grid container spacing={4}>
                {relatedServices.map((relatedService) => (
                  <Grid size={{ xs: 12, md: 4 }} key={relatedService.id}>
                    <ServiceCard service={relatedService} showFeatures={2} />
                  </Grid>
                ))}
              </Grid>
            </Container>
          </Box>
        )}

        <Divider sx={{ borderColor: "divider" }} />

        {/* CTA Section with Trust Indicators */}
        <Box
          component="section"
          sx={{
            py: { xs: 12, md: 16 },
            bgcolor: alpha("#f8fafc", 0.5),
          }}
        >
          <Container maxWidth="md" sx={{ textAlign: "center" }}>
            <Typography
              component="h2"
              variant="h4"
              sx={{
                fontWeight: 600,
                mb: 2,
                color: "text.primary",
              }}
            >
              {t("services.detail.readyToStart")}
            </Typography>
            <Typography
              sx={{
                color: "text.secondary",
                mb: 4,
                fontSize: "1.125rem",
              }}
            >
              {t("services.detail.ctaDescription")}
            </Typography>
            
            {/* Trust Indicators */}
            <Box
              sx={{
                display: "flex",
                flexWrap: "wrap",
                justifyContent: "center",
                gap: 3,
                mb: 4,
              }}
            >
              <Box sx={{ textAlign: "center" }}>
                <Typography
                  sx={{
                    fontSize: "0.875rem",
                    color: "text.secondary",
                    mb: 0.5,
                  }}
                >
                  {t("services.detail.trustIndicators.experience")}
                </Typography>
              </Box>
              <Box sx={{ textAlign: "center" }}>
                <Typography
                  sx={{
                    fontSize: "0.875rem",
                    color: "text.secondary",
                    mb: 0.5,
                  }}
                >
                  {t("services.detail.trustIndicators.projects")}
                </Typography>
              </Box>
              <Box sx={{ textAlign: "center" }}>
                <Typography
                  sx={{
                    fontSize: "0.875rem",
                    color: "text.secondary",
                    mb: 0.5,
                  }}
                >
                  {t("services.detail.trustIndicators.satisfaction")}
                </Typography>
              </Box>
              <Box sx={{ textAlign: "center" }}>
                <Typography
                  sx={{
                    fontSize: "0.875rem",
                    color: "text.secondary",
                    mb: 0.5,
                  }}
                >
                  {t("services.detail.trustIndicators.onTime")}
                </Typography>
              </Box>
            </Box>

            <Button
              component={Link}
              to="/job-request"
              variant="contained"
              size="large"
              sx={{
                px: 4,
                py: 1.5,
                fontSize: "1rem",
                fontWeight: 500,
              }}
            >
              {navContent.jobRequest}
            </Button>
          </Container>
        </Box>
      </Box>
    </>
  );
};

export default ServiceDetail;
