/**
 * Pricing Page
 * 
 * Competitive pricing page with role-based pricing, packages, and calculator
 */

import React from "react";
import { Box } from "@mui/material";
import { useTranslation } from "react-i18next";
import { Helmet } from "react-helmet-async";
import { HeroSection } from "../components/sections";
import PromotionalBanner from "../components/pricing/PromotionalBanner";
import RolePricingTable from "../components/pricing/RolePricingTable";
import MarketComparisonTable from "../components/pricing/MarketComparisonTable";
import PackagePricingSection from "../components/pricing/PackagePricingSection";
import SavingsCalculator from "../components/pricing/SavingsCalculator";
import { CTASection } from "../components/sections";

const Pricing: React.FC = () => {
  const { t } = useTranslation();

  const heroContent = {
    badge: t("pricing.hero.badge"),
    headline: {
      primary: t("pricing.hero.headline.primary"),
      highlight: t("pricing.hero.headline.highlight"),
    },
    subheadline: t("pricing.hero.subheadline"),
    cta: {
      primary: {
        text: t("pricing.calculator.getQuote"),
        link: "/job-request",
        variant: "contained" as const,
      },
      secondary: {
        text: t("pricing.calculator.contactUs"),
        link: "/contact",
        variant: "outlined" as const,
      },
    },
  };

  const ctaContent = {
    badge: t("pricing.cta.badge"),
    headline: {
      primary: t("pricing.cta.title"),
      highlight: "",
    },
    description: t("pricing.cta.description"),
    button: {
      text: t("pricing.cta.button"),
      link: "/job-request",
      variant: "contained" as const,
    },
    urgency: "",
    trustIndicators: [],
  };

  return (
    <>
      <Helmet>
        <title>{t("pricing.meta.title")}</title>
        <meta name="description" content={t("pricing.meta.description")} />
        <meta name="keywords" content={t("pricing.meta.keywords", { returnObjects: true }).join(", ")} />
        <link rel="canonical" href={`${window.location.origin}/pricing`} />
      </Helmet>

      <Box>
        <HeroSection content={heroContent} />
        <PromotionalBanner />
        <RolePricingTable />
        <MarketComparisonTable />
        <PackagePricingSection />
        <SavingsCalculator />
        <CTASection content={ctaContent} />
      </Box>
    </>
  );
};

export default Pricing;
