/**
 * Portfolio Page - Content-Driven Architecture
 * 
 * Showcases completed projects
 */

import React, { useState } from "react";
import { Box, Container, Grid, Chip, Typography, alpha } from "@mui/material";
import { SectionHeader } from "../components/sections";
import { ProjectCard } from "../components/cards";
import SEO from "../components/SEO";
import {
  portfolioPageConfig,
  portfolioCategories,
} from "../content";
import { usePortfolioContent } from "../utils/contentHelper";

const Portfolio: React.FC = () => {
  const portfolioContent = usePortfolioContent();
  const [selectedCategory, setSelectedCategory] = useState<string>("all");

  const filteredProjects = Array.isArray(portfolioContent.projects)
    ? (selectedCategory === "all"
        ? portfolioContent.projects
        : portfolioContent.projects.filter((p) => p.category === selectedCategory))
    : [];

  return (
    <>
      <SEO
        content={{
          meta: {
            title: portfolioContent.meta.title,
            description: portfolioContent.meta.description,
            keywords: portfolioContent.meta.keywords,
          },
        }}
      />
      <Box component="main" sx={{ bgcolor: "background.default" }}>
      {/* Hero Section - Có thể ẩn/hiện qua config */}
      {portfolioPageConfig.showHero && (
        <Box
          component="section"
          sx={{
            py: { xs: 8, md: 12 },
            bgcolor: "background.paper",
          }}
        >
          <Container maxWidth="lg">
            <SectionHeader content={portfolioContent.section} />
          </Container>
        </Box>
      )}

      <Box sx={{ borderBottom: "1px solid", borderColor: "divider", bgcolor: "background.paper" }}>
        <Container maxWidth="lg">
          <Box
            sx={{
              display: "flex",
              flexWrap: "wrap",
              gap: 1,
              justifyContent: "center",
              py: 3,
            }}
          >
            {portfolioCategories.map((cat) => (
              <Chip
                key={cat.id}
                label={`${portfolioContent.categories[cat.id] || cat.label} (${cat.count})`}
                onClick={() => setSelectedCategory(cat.id)}
                sx={{
                  bgcolor: selectedCategory === cat.id ? alpha("#f1f5f9", 0.8) : "transparent",
                  color: selectedCategory === cat.id ? "text.primary" : "text.secondary",
                  border: "1px solid",
                  borderColor: selectedCategory === cat.id ? "divider" : "divider",
                  fontWeight: selectedCategory === cat.id ? 500 : 400,
                  cursor: "pointer",
                  transition: "all 150ms ease",
                  "&:hover": {
                    bgcolor: alpha("#f8fafc", 0.8),
                    color: "text.primary",
                  },
                }}
              />
            ))}
          </Box>
        </Container>
      </Box>

      {/* Projects Grid */}
      <Box
        component="section"
        aria-labelledby="portfolio-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: "background.default",
        }}
      >
        <Container maxWidth="lg">
          {filteredProjects.length > 0 ? (
            <Grid container spacing={4}>
              {filteredProjects.map((project) => (
                <Grid size={{ xs: 12, md: 6, lg: 4 }} key={project.id}>
                  <ProjectCard project={project} />
                </Grid>
              ))}
            </Grid>
          ) : (
            <Box sx={{ textAlign: "center", py: 8 }}>
              <Typography sx={{ color: "text.secondary" }}>
                {portfolioContent.emptyState}
              </Typography>
            </Box>
          )}
        </Container>
      </Box>
      </Box>
    </>
  );
};

export default Portfolio;
