/**
 * CTA Section Component
 * 
 * Reusable call-to-action section
 * Content-driven with urgency and trust indicators
 */

import React from "react";
import { Link } from "react-router-dom";
import { Box, Container, Typography, Button, Chip, alpha } from "@mui/material";
import { CTAContent } from "../../content/types";

interface CTASectionProps {
  content: CTAContent;
  className?: string;
}

const CTASection: React.FC<CTASectionProps> = ({ content, className }) => {
  const { badge, headline, description, button, urgency, trustIndicators } = content;

  return (
    <Box
      component="section"
      className={className}
      sx={{
        py: { xs: 12, md: 16 },
        bgcolor: "background.paper",
      }}
    >
      <Container maxWidth="md" sx={{ textAlign: "center" }}>
        {badge && (
          <Chip
            label={badge}
            sx={{
              mb: 4,
              bgcolor: alpha("#f1f5f9", 0.6),
              color: "text.secondary",
              fontWeight: 500,
              fontSize: "0.875rem",
              border: "1px solid",
              borderColor: "divider",
            }}
          />
        )}

        <Typography
          component="h2"
          variant="h2"
          sx={{
            fontSize: { xs: "2.5rem", md: "3rem" },
            fontWeight: 600,
            mb: 3,
            color: "text.primary",
            lineHeight: 1.3,
          }}
        >
          {headline.primary}
          {headline.highlight && (
            <Box
              component="span"
              sx={{
                display: "block",
                mt: 1,
                color: "accent.main",
                fontWeight: 500,
              }}
            >
              {headline.highlight}
            </Box>
          )}
        </Typography>

        <Typography
          variant="body1"
          component="p"
          sx={{
            fontSize: "1.125rem",
            color: "text.secondary",
            mb: 6,
            maxWidth: "600px",
            mx: "auto",
            lineHeight: 1.8,
          }}
        >
          {description}
          {urgency && (
            <>
              {" "}
              <Box component="span" sx={{ fontWeight: 500, color: "text.primary" }}>
                {urgency}
              </Box>
            </>
          )}
        </Typography>

        {trustIndicators && trustIndicators.length > 0 && (
          <Box
            component="ul"
            role="list"
            aria-label="Trust indicators"
            sx={{
              mb: 4,
              display: "flex",
              flexWrap: "wrap",
              gap: 2,
              justifyContent: "center",
              listStyle: "none",
              p: 0,
              m: 0,
            }}
          >
            {trustIndicators.map((indicator, index) => (
              <Box
                key={index}
                component="li"
                sx={{
                  display: "flex",
                  alignItems: "center",
                }}
              >
                <Typography
                  variant="body2"
                  aria-label={indicator}
                  sx={{
                    color: "text.secondary",
                    fontSize: "0.875rem",
                  }}
                >
                  <Box component="span" aria-hidden="true">✓</Box>{" "}
                  <Box component="span">{indicator}</Box>
                </Typography>
              </Box>
            ))}
          </Box>
        )}

        <Button
          component={Link}
          to={button.link}
          variant={button.variant}
          size="large"
          aria-label={`${button.text} - ${headline.primary}`}
          sx={{
            px: 5,
            py: 1.75,
            borderRadius: 2,
            fontWeight: 500,
            fontSize: "1.0625rem",
            bgcolor: "text.primary",
            color: "background.paper",
            boxShadow: "none",
            border: "1px solid",
            borderColor: "text.primary",
            transition: "all 150ms cubic-bezier(0.4, 0, 0.2, 1)",
            "&:hover": {
              bgcolor: "text.primary",
              color: "background.paper",
              boxShadow:
                "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1)",
              transform: "translateY(-1px)",
            },
          }}
        >
          {button.text}
        </Button>
      </Container>
    </Box>
  );
};

export default CTASection;
