/**
 * Icon Component - Reusable Icon System
 * 
 * Provides consistent, theme-aware, accessible icons
 * Supports Material Icons with customization
 */

import React from "react";
import { SvgIcon, SvgIconProps, useTheme, alpha } from "@mui/material";
import {
  Code as CodeIcon,
  MenuBook as MenuBookIcon,
  Build as BuildIcon,
  Psychology as PsychologyIcon,
  Assignment as AssignmentIcon,
  TrackChanges as TrackChangesIcon,
  Star as StarIcon,
  People as PeopleIcon,
  BusinessCenter as BusinessCenterIcon,
  Cloud as CloudIcon,
  RocketLaunch as RocketLaunchIcon,
  BarChart as BarChartIcon,
  School as SchoolIcon,
  Chat as ChatIcon,
  Description as DescriptionIcon,
  Bolt as BoltIcon,
  CheckCircle as CheckCircleIcon,
  Computer as ComputerIcon,
  Settings as SettingsIcon,
  SmartToy as SmartToyIcon,
  GpsFixed as GpsFixedIcon,
  StarRate as StarRateIcon,
  Groups as GroupsIcon,
  Work as WorkIcon,
  CloudQueue as CloudQueueIcon,
  TrendingUp as TrendingUpIcon,
  Assessment as AssessmentIcon,
  Message as MessageIcon,
  FlashOn as FlashOnIcon,
  Done as DoneIcon,
} from "@mui/icons-material";

// Icon name type
export type IconName =
  | "code"
  | "computer"
  | "menu-book"
  | "school"
  | "build"
  | "settings"
  | "psychology"
  | "smart-toy"
  | "assignment"
  | "description"
  | "track-changes"
  | "gps-fixed"
  | "star"
  | "star-rate"
  | "people"
  | "groups"
  | "business-center"
  | "work"
  | "cloud"
  | "cloud-queue"
  | "rocket-launch"
  | "trending-up"
  | "bar-chart"
  | "assessment"
  | "chat"
  | "message"
  | "bolt"
  | "flash-on"
  | "check-circle"
  | "done";

// Icon mapping
const iconMap: Record<IconName, React.ComponentType<SvgIconProps>> = {
  code: CodeIcon,
  computer: ComputerIcon,
  "menu-book": MenuBookIcon,
  school: SchoolIcon,
  build: BuildIcon,
  settings: SettingsIcon,
  psychology: PsychologyIcon,
  "smart-toy": SmartToyIcon,
  assignment: AssignmentIcon,
  description: DescriptionIcon,
  "track-changes": TrackChangesIcon,
  "gps-fixed": GpsFixedIcon,
  star: StarIcon,
  "star-rate": StarRateIcon,
  people: PeopleIcon,
  groups: GroupsIcon,
  "business-center": BusinessCenterIcon,
  work: WorkIcon,
  cloud: CloudIcon,
  "cloud-queue": CloudQueueIcon,
  "rocket-launch": RocketLaunchIcon,
  "trending-up": TrendingUpIcon,
  "bar-chart": BarChartIcon,
  assessment: AssessmentIcon,
  chat: ChatIcon,
  message: MessageIcon,
  bolt: BoltIcon,
  "flash-on": FlashOnIcon,
  "check-circle": CheckCircleIcon,
  done: DoneIcon,
};

// Emoji to Icon mapping (for migration)
export const emojiToIcon: Record<string, IconName> = {
  "💻": "code",
  "📚": "menu-book",
  "🛠️": "build",
  "🤖": "psychology",
  "📝": "assignment",
  "🎯": "track-changes",
  "⭐": "star",
  "👥": "people",
  "👔": "business-center",
  "☁️": "cloud",
  "🚀": "rocket-launch",
  "📊": "bar-chart",
  "🎓": "school",
  "💬": "chat",
  "⚡": "bolt",
  "✅": "check-circle",
};

// Icon size presets
export type IconSize = "small" | "medium" | "large" | "xlarge" | "xxlarge" | number;

const sizeMap: Record<IconSize, number> = {
  small: 16,
  medium: 20,
  large: 24,
  xlarge: 32,
  xxlarge: 40,
};

export interface IconProps extends Omit<SvgIconProps, "children" | "color"> {
  name: IconName | string; // Support both icon name and emoji (for migration)
  size?: IconSize;
  color?: "primary" | "secondary" | "accent" | "success" | "error" | "inherit" | string;
  hoverColor?: string;
  hoverEffect?: "scale" | "rotate" | "none";
  container?: boolean; // Wrap in container with background
  containerSize?: number;
}

const Icon: React.FC<IconProps> = ({
  name,
  size = "large",
  color = "inherit",
  hoverColor,
  hoverEffect = "none",
  container = false,
  containerSize,
  sx,
  ...props
}) => {
  const theme = useTheme();

  // Convert emoji to icon name if needed
  const iconName = emojiToIcon[name] || (name as IconName);

  // Get icon component
  const IconComponent = iconMap[iconName];

  if (!IconComponent) {
    console.warn(`Icon "${name}" not found. Using default.`);
    return null;
  }

  // Calculate size
  const iconSize = typeof size === "number" ? size : sizeMap[size];

  // Calculate color
  const iconColor =
    color === "primary"
      ? theme.palette.primary.main
      : color === "secondary"
      ? theme.palette.text.secondary
      : color === "accent"
      ? theme.palette.secondary.main
      : color === "success"
      ? theme.palette.success.main
      : color === "error"
      ? theme.palette.error.main
      : color === "inherit"
      ? "inherit"
      : color;

  // Container size
  const containerSizeValue = containerSize || iconSize + 16;

  // Hover effects
  const hoverStyles =
    hoverEffect === "scale"
      ? {
          "&:hover": {
            transform: "scale(1.1)",
          },
        }
      : hoverEffect === "rotate"
      ? {
          "&:hover": {
            transform: "rotate(5deg)",
          },
        }
      : {};

  const iconElement = (
    <IconComponent
      sx={{
        fontSize: iconSize,
        color: iconColor,
        transition: "all 150ms ease",
        ...(hoverColor && {
          "&:hover": {
            color: hoverColor,
          },
        }),
        ...hoverStyles,
        ...sx,
      }}
      {...(props as SvgIconProps)}
    />
  );

  if (container) {
    return (
      <SvgIcon
        component="div"
        sx={{
          width: containerSizeValue,
          height: containerSizeValue,
          borderRadius: 2,
          bgcolor: alpha(theme.palette.primary.main, 0.08),
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          border: "1px solid",
          borderColor: theme.palette.divider,
          transition: "all 150ms ease",
          "&:hover": {
            bgcolor: alpha(theme.palette.primary.main, 0.12),
            borderColor: alpha(theme.palette.primary.main, 0.3),
          },
        }}
      >
        {iconElement}
      </SvgIcon>
    );
  }

  return iconElement;
};

export default Icon;
