import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import ErrorBoundary from "./components/ErrorBoundary";
import ScrollToTop from "./components/ScrollToTop";
import { CurrencyProvider } from "./contexts/CurrencyContext";
import MainLayout from "./layouts/MainLayout";
import Home from "./pages/Home";
import Services from "./pages/Services";
import ServiceDetail from "./pages/ServiceDetail";
import SoftwareDevelopment from "./pages/services/SoftwareDevelopment";
import Teaching from "./pages/services/Teaching";
import ToolDevelopment from "./pages/services/ToolDevelopment";
import AIImplementation from "./pages/services/AIImplementation";
import ProjectAssignment from "./pages/services/ProjectAssignment";
import Portfolio from "./pages/Portfolio";
import Blog from "./pages/Blog";
import BlogDetail from "./pages/BlogDetail";
import About from "./pages/About";
import Contact from "./pages/Contact";
import Pricing from "./pages/Pricing";
import JobRequest from "./pages/JobRequest";
import FAQ from "./pages/FAQ";
import CaseStudies from "./pages/CaseStudies";
import PrivacyPolicy from "./pages/PrivacyPolicy";
import TermsOfService from "./pages/TermsOfService";

function App() {
  return (
    <CurrencyProvider>
      <Router>
        <ScrollToTop />
        <ErrorBoundary>
          <MainLayout>
            <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/services" element={<Services />} />
          {/* Individual service pages */}
          <Route path="/services/software-development" element={<SoftwareDevelopment />} />
          <Route path="/services/teaching" element={<Teaching />} />
          <Route path="/services/tool-development" element={<ToolDevelopment />} />
          <Route path="/services/ai-implementation" element={<AIImplementation />} />
          <Route path="/services/project-assignment" element={<ProjectAssignment />} />
          {/* Fallback for old routes */}
          <Route path="/services/:serviceId" element={<ServiceDetail />} />
          <Route path="/portfolio" element={<Portfolio />} />
          <Route path="/blog" element={<Blog />} />
          <Route path="/blog/:id" element={<BlogDetail />} />
          <Route path="/about" element={<About />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="/pricing" element={<Pricing />} />
          <Route path="/faq" element={<FAQ />} />
          <Route path="/case-studies" element={<CaseStudies />} />
          <Route path="/job-request" element={<JobRequest />} />
          <Route path="/privacy-policy" element={<PrivacyPolicy />} />
          <Route path="/terms-of-service" element={<TermsOfService />} />
            </Routes>
          </MainLayout>
        </ErrorBoundary>
      </Router>
    </CurrencyProvider>
  );
}

export default App;
