/**
 * Pricing Utility Functions
 * 
 * Functions for pricing calculations and formatting
 */

import { PriceRange } from "../content/pricing";

/**
 * Format JPY currency
 * @param amount - Amount in JPY
 * @returns Formatted string (e.g., "¥640K", "¥1.2M")
 */
export const formatJPY = (amount: number): string => {
  if (amount >= 1000000) {
    return `¥${(amount / 1000000).toFixed(1)}M`;
  }
  return `¥${(amount / 1000).toFixed(0)}K`;
};

/**
 * Format price range
 * @param range - Price range
 * @returns Formatted string (e.g., "¥640K-960K")
 */
export const formatPriceRange = (range: PriceRange): string => {
  return `${formatJPY(range.min)}-${formatJPY(range.max)}`;
};

/**
 * Calculate first month price with discount
 * @param basePrice - Base price in JPY
 * @param discount - Discount percentage (0-1)
 * @returns First month price
 */
export const calculateFirstMonthPrice = (basePrice: number, discount: number): number => {
  return Math.round(basePrice * (1 - discount));
};

/**
 * Calculate monthly price with discount based on duration
 * @param basePrice - Base price in JPY
 * @param duration - Contract duration in months
 * @returns Monthly price with discount
 */
export const calculateMonthlyPrice = (basePrice: number, duration: number): number => {
  let discount = 0;
  if (duration >= 12) {
    discount = 0.20; // 20% OFF
  } else if (duration >= 6) {
    discount = 0.15; // 15% OFF
  }
  return Math.round(basePrice * (1 - discount));
};

/**
 * Calculate total cost for a contract
 * @param basePrice - Base price in JPY
 * @param duration - Contract duration in months
 * @param firstMonthDiscount - First month discount percentage (0-1)
 * @returns Total cost
 */
export const calculateTotalCost = (
  basePrice: number,
  duration: number,
  firstMonthDiscount: number = 0.25
): number => {
  if (duration < 3) {
    // No first month discount for contracts < 3 months
    return basePrice * duration;
  }

  const firstMonth = calculateFirstMonthPrice(basePrice, firstMonthDiscount);
  const monthlyPrice = calculateMonthlyPrice(basePrice, duration);
  return firstMonth + monthlyPrice * (duration - 1);
};

/**
 * Calculate savings compared to market rate
 * @param marketRate - Market rate in JPY
 * @param ourRate - Our rate in JPY
 * @param duration - Contract duration in months
 * @returns Savings amount and percentage
 */
export const calculateSavings = (
  marketRate: number,
  ourRate: number,
  duration: number
): { amount: number; percentage: number } => {
  const marketTotal = marketRate * duration;
  const ourTotal = calculateTotalCost(ourRate, duration);
  const savings = marketTotal - ourTotal;
  const percentage = (savings / marketTotal) * 100;
  return { amount: savings, percentage };
};

/**
 * Get discount percentage for duration
 * @param duration - Contract duration in months
 * @returns Discount percentage (0-1)
 */
export const getDiscountForDuration = (duration: number): number => {
  if (duration >= 12) return 0.20;
  if (duration >= 6) return 0.15;
  return 0;
};

/**
 * Check if first month discount applies
 * @param duration - Contract duration in months
 * @returns True if first month discount applies
 */
export const hasFirstMonthDiscount = (duration: number): boolean => {
  return duration >= 3;
};
