/**
 * Article Card Component
 * 
 * Reusable article card for blog listing
 */

import React from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, Typography, Box, Chip, alpha } from "@mui/material";
import { BlogArticle } from "../../content/blog";
import { useTranslation } from "react-i18next";
import { formatBlogDate } from "../../utils/dateUtils";

interface ArticleCardProps {
  article: BlogArticle;
  className?: string;
}

const ArticleCard: React.FC<ArticleCardProps> = ({ article, className }) => {
  const { title, excerpt, category, tags, publishedAt, readTime, featured } = article;
  const { t, i18n } = useTranslation();

  const categoryLabels: Record<string, string> = t("blog.categories", { returnObjects: true }) as Record<string, string>;

  return (
    <Card
      component={Link}
      to={`/blog/${article.id}`}
      className={className}
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        bgcolor: "background.paper",
        border: "1px solid",
        borderColor: featured ? alpha("#475569", 0.3) : "divider",
        borderRadius: 2,
        textDecoration: "none",
        transition: "all 180ms cubic-bezier(0.4, 0, 0.2, 1)",
        "&:hover": {
          borderColor: alpha("#475569", 0.3),
          boxShadow:
            "0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1)",
          transform: "translateY(-2px)",
        },
      }}
    >
      <CardContent sx={{ p: { xs: 2.5, md: 4 }, flexGrow: 1, display: "flex", flexDirection: "column" }}>
        {/* Category & Date - Date hidden on mobile */}
        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
          <Chip
            label={categoryLabels[category] || category}
            size="small"
            sx={{
              bgcolor: featured ? alpha("#f1f5f9", 0.8) : alpha("#f8fafc", 0.8),
              color: "text.secondary",
              fontSize: { xs: "0.7rem", md: "0.75rem" },
              height: { xs: 22, md: 24 },
            }}
          />
          <Typography 
            variant="caption" 
            sx={{ 
              color: "text.secondary", 
              fontSize: "0.8125rem",
              display: { xs: "none", md: "block" }
            }}
          >
            {formatBlogDate(publishedAt, i18n.language)}
          </Typography>
        </Box>

        {/* Title */}
        <Typography
          component="h3"
          variant="h5"
          sx={{
            fontWeight: 600,
            mb: { xs: 1.5, md: 2 },
            color: "text.primary",
            fontSize: { xs: "1rem", md: "1.375rem" },
            lineHeight: 1.3,
          }}
        >
          {title}
        </Typography>

        {/* Excerpt - Hidden on mobile to reduce cognitive load */}
        <Typography
          component="p"
          sx={{
            color: "text.secondary",
            mb: 3,
            lineHeight: 1.7,
            flexGrow: 1,
            fontSize: "0.9375rem",
            display: { xs: "none", md: "block" },
          }}
        >
          {excerpt}
        </Typography>

        {/* Tags & Read Time - Hidden on mobile to reduce cognitive load */}
        <Box
          sx={{
            mt: "auto",
            pt: 2,
            borderTop: "1px solid",
            borderColor: "divider",
            display: { xs: "none", md: "flex" },
            justifyContent: "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            gap: 1,
          }}
        >
          <Box sx={{ display: "flex", flexWrap: "wrap", gap: 0.75 }}>
            {tags.slice(0, 2).map((tag, idx) => (
              <Chip
                key={idx}
                label={tag}
                size="small"
                sx={{
                  bgcolor: "transparent",
                  color: "text.secondary",
                  fontSize: "0.75rem",
                  height: 22,
                  border: "1px solid",
                  borderColor: "divider",
                }}
              />
            ))}
          </Box>
          <Typography variant="caption" sx={{ color: "text.secondary", fontSize: "0.8125rem" }}>
            {readTime} {t("blog.card.readTime")}
          </Typography>
        </Box>
      </CardContent>
    </Card>
  );
};

export default ArticleCard;
