/**
 * Home Page - Content-Driven Architecture
 *
 * Refactored to use:
 * - Content from src/content/ (separated from UI)
 * - Reusable section components
 * - Semantic HTML for SEO
 * - Improved accessibility
 */

import React from "react";
import {
  Box,
  Container,
  Grid,
  Divider,
  Typography,
  alpha,
} from "@mui/material";
import { useTranslation } from "react-i18next";
import { HeroSection, SectionHeader, CTASection, TestimonialsSection, TrustBadgesSection, ClientLogosSection, JapanMarketSection, WorkflowProcessSection, OffshoreDevelopmentSection } from "../components/sections";
import { ServiceCard, FeatureCard } from "../components/cards";
import Icon from "../components/Icon";
import Seo from "../components/SEO";
import { normalizeIconName } from "../utils/iconMapping";
import { useHomeContent, useServicesContent } from "../utils/contentHelper";
import { generateOrganizationSchema, generateWebSiteSchema, generateLocalBusinessSchema, generateReviewSchema } from "../utils/seo";
import { ServiceContent, FeatureContent, CTAContent, SectionHeader as SectionHeaderType } from "../content/types";

const Home: React.FC = () => {
  const { t } = useTranslation();
  const homeContent = useHomeContent();
  const servicesContent = useServicesContent();

  // Build services section header
  const servicesSection: SectionHeaderType = {
    badge: homeContent.services.badge,
    title: homeContent.services.title,
    description: homeContent.services.description,
    alignment: "center",
  };

  // Build features section header
  const whyChooseMeSection: SectionHeaderType = {
    badge: homeContent.featuresHeader.badge,
    title: homeContent.featuresHeader.title,
    description: homeContent.featuresHeader.description,
    alignment: "center",
  };

  // Build CTA section
  const ctaSection: CTAContent = {
    badge: homeContent.cta.badge,
    headline: homeContent.cta.headline,
    description: homeContent.cta.description,
    button: homeContent.cta.button,
    urgency: homeContent.cta.urgency,
  };

  // Convert services list to ServiceContent format
  const servicesList: ServiceContent[] = servicesContent.servicesList.map((service) => ({
    ...service,
    features: service.features || [],
  }));

  // Convert features to FeatureContent format
  const featuresList: FeatureContent[] = homeContent.features.map((feature) => ({
    id: feature.id,
    icon: feature.icon,
    title: feature.title,
    description: feature.description,
  }));

  return (
    <>
      <Seo
        content={{
          meta: {
            title: homeContent.meta.title,
            description: homeContent.meta.description,
            keywords: homeContent.meta.keywords,
          },
        }}
        structuredData={[
          generateOrganizationSchema(),
          generateWebSiteSchema(),
          generateLocalBusinessSchema(),
          generateReviewSchema(4.9, 100, 5, 1),
        ]}
      />
      <Box component="main" sx={{ bgcolor: "background.default" }}>
        {/* Hero Section */}
        {homeContent.hero && <HeroSection content={homeContent.hero} />}

      {/* Services Section */}
      <Box
        component="section"
        aria-labelledby="services-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: "background.default",
        }}
      >
        <Container maxWidth="lg">
          <SectionHeader content={servicesSection} />
          <Grid container spacing={3}>
            {servicesList.map((service) => (
              <Grid size={{ xs: 6, md: 6, lg: 4 }} key={service.id}>
                <ServiceCard service={service} showFeatures={3} />
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      <Divider sx={{ borderColor: "divider" }} />

      {/* Testimonials Section - Moved up for better visibility and social proof */}
      <TestimonialsSection
        header={{
          badge: homeContent.testimonials.badge,
          title: homeContent.testimonials.title,
          description: homeContent.testimonials.description,
          alignment: "center",
        }}
        testimonials={homeContent.testimonials.items.map((item) => ({
          id: item.id,
          name: item.name,
          position: item.position,
          company: item.company,
          rating: item.rating,
          content: item.content,
          project: item.project,
          verified: item.verified,
        }))}
        maxItems={6}
      />

      <Divider sx={{ borderColor: "divider" }} />

      {/* Offshore Development Section */}
      <OffshoreDevelopmentSection />

      <Divider sx={{ borderColor: "divider" }} />

      {/* Why Choose Me Section */}
      <Box
        component="section"
        aria-labelledby="features-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: "background.paper",
        }}
      >
        <Container maxWidth="lg">
          <SectionHeader content={whyChooseMeSection} />
          <Grid container spacing={3}>
            {featuresList.map((feature) => (
              <Grid size={{ xs: 12, sm: 6, lg: 4 }} key={feature.id}>
                <FeatureCard feature={feature} />
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      <Divider sx={{ borderColor: "divider" }} />

      {/* Workflow Process Section */}
      <WorkflowProcessSection />

      <Divider sx={{ borderColor: "divider" }} />

      {/* Stats Section */}
      <Box
        component="section"
        aria-labelledby="stats-heading"
        sx={{
          py: { xs: 12, md: 16 },
          bgcolor: alpha("#f8fafc", 0.5),
        }}
      >
        <Container maxWidth="lg">
          <Grid container spacing={4}>
            {homeContent.stats.map((stat) => (
              <Grid size={{ xs: 6, md: 3 }} key={stat.id}>
                <Box sx={{ textAlign: "center" }}>
                  <Box
                    sx={{
                      mb: 1,
                      display: "flex",
                      justifyContent: "center",
                    }}
                    aria-hidden="true"
                  >
                    <Icon
                      name={normalizeIconName(stat.icon)}
                      size="xxlarge"
                      color="primary"
                    />
                  </Box>
                  <Typography
                    variant="h3"
                    component="div"
                    sx={{
                      fontSize: { xs: "2rem", md: "2.5rem" },
                      fontWeight: 600,
                      mb: 1,
                      color: "text.primary",
                    }}
                  >
                    {stat.value}
                  </Typography>
                  <Typography
                    component="p"
                    sx={{
                      color: "text.secondary",
                      fontWeight: 400,
                      fontSize: "0.9375rem",
                    }}
                  >
                    {stat.label}
                  </Typography>
                </Box>
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      <Divider sx={{ borderColor: "divider" }} />

      {/* Trust Badges Section */}
      <TrustBadgesSection
        header={{
          badge: homeContent.trustBadges.badge,
          title: homeContent.trustBadges.title,
          description: homeContent.trustBadges.description,
          alignment: "center",
        }}
        badges={homeContent.trustBadges.items.map((item) => ({
          id: item.id,
          type: item.type as "certification" | "award" | "experience" | "achievement",
          title: item.title,
          issuer: item.issuer,
          year: item.year,
          description: item.description,
        }))}
      />

      <Divider sx={{ borderColor: "divider" }} />

      {/* Client Logos Section */}
      <ClientLogosSection
        header={{
          badge: homeContent.clientLogos.badge,
          title: homeContent.clientLogos.title,
          description: homeContent.clientLogos.description,
          alignment: "center",
        }}
        logos={(t("home.clientLogos.categories", { returnObjects: true }) as string[]).map((category, index) => ({
          id: `client-${index + 1}`,
          name: category,
        }))}
      />

      <Divider sx={{ borderColor: "divider" }} />

      {/* CTA Section */}
      <CTASection content={ctaSection} />

      {/* Japan Market Section - Only shows in Japanese */}
      <JapanMarketSection />
      </Box>
    </>
  );
};

export default Home;
