/**
 * Blog Service
 * 
 * Service to fetch blog articles from JSON files or API
 * Supports both file-based and API-based data sources
 */

import { BlogArticle } from "../content/blog";

export interface BlogServiceConfig {
  source: "file" | "api";
  apiEndpoint?: string;
  cacheEnabled?: boolean;
}

interface BlogArticlesResponse {
  articles: BlogArticle[];
  meta?: {
    total?: number;
    lastUpdated?: string;
  };
}

class BlogService {
  private config: BlogServiceConfig;
  private cache: Map<string, BlogArticlesResponse> = new Map();
  private cacheExpiry: Map<string, number> = new Map();
  private readonly CACHE_DURATION = 5 * 60 * 1000; // 5 minutes

  constructor(config: BlogServiceConfig = { source: "file" }) {
    this.config = {
      cacheEnabled: true,
      ...config,
    };
  }

  /**
   * Get all articles for a specific language
   */
  async getArticles(language: string = "vi"): Promise<BlogArticle[]> {
    const cacheKey = `articles-${language}`;

    // Check cache first
    if (this.config.cacheEnabled && this.isCacheValid(cacheKey)) {
      const cached = this.cache.get(cacheKey);
      if (cached) {
        return cached.articles;
      }
    }

    try {
      let response: BlogArticlesResponse;

      if (this.config.source === "api" && this.config.apiEndpoint) {
        response = await this.fetchFromAPI(language);
      } else {
        response = await this.fetchFromFile(language);
      }

      // Cache the response
      if (this.config.cacheEnabled) {
        this.cache.set(cacheKey, response);
        this.cacheExpiry.set(cacheKey, Date.now() + this.CACHE_DURATION);
      }

      return response.articles;
    } catch (error) {
      console.error(`Error fetching blog articles for ${language}:`, error);
      // Return empty array on error
      return [];
    }
  }

  /**
   * Get a single article by ID
   */
  async getArticle(id: string, language: string = "vi"): Promise<BlogArticle | null> {
    const articles = await this.getArticles(language);
    return articles.find((article) => article.id === id) || null;
  }

  /**
   * Search articles by query
   */
  async searchArticles(
    query: string,
    language: string = "vi"
  ): Promise<BlogArticle[]> {
    const articles = await this.getArticles(language);
    const lowerQuery = query.toLowerCase();

    return articles.filter(
      (article) =>
        article.title.toLowerCase().includes(lowerQuery) ||
        article.excerpt.toLowerCase().includes(lowerQuery) ||
        article.tags.some((tag) => tag.toLowerCase().includes(lowerQuery)) ||
        (article.content && article.content.toLowerCase().includes(lowerQuery))
    );
  }

  /**
   * Get featured articles
   */
  async getFeaturedArticles(language: string = "vi"): Promise<BlogArticle[]> {
    const articles = await this.getArticles(language);
    return articles.filter((article) => article.featured);
  }

  /**
   * Get articles by category
   */
  async getArticlesByCategory(
    category: BlogArticle["category"],
    language: string = "vi"
  ): Promise<BlogArticle[]> {
    const articles = await this.getArticles(language);
    return articles.filter((article) => article.category === category);
  }

  /**
   * Fetch articles from JSON file
   */
  private async fetchFromFile(language: string): Promise<BlogArticlesResponse> {
    try {
      // Static imports for JSON files (CRA doesn't support dynamic imports for JSON)
      let data: any;
      
      switch (language) {
        case "vi":
          data = require("../data/blog/articles.vi.json");
          break;
        case "en":
          data = require("../data/blog/articles.en.json");
          break;
        case "ja":
          data = require("../data/blog/articles.ja.json");
          break;
        default:
          data = require("../data/blog/articles.vi.json");
      }

      // Handle both default export and direct export
      const response = (data.default || data) as BlogArticlesResponse;
      
      // Ensure category types are correct
      response.articles = response.articles.map((article) => ({
        ...article,
        category: article.category as BlogArticle["category"],
      }));
      
      return response;
    } catch (error) {
      console.error(`Error loading blog file for ${language}:`, error);
      // Fallback to Vietnamese if file not found
      if (language !== "vi") {
        try {
          const fallbackData: any = require("../data/blog/articles.vi.json");
          const response = (fallbackData.default || fallbackData) as BlogArticlesResponse;
          response.articles = response.articles.map((article) => ({
            ...article,
            category: article.category as BlogArticle["category"],
          }));
          return response;
        } catch (fallbackError) {
          console.error("Error loading fallback blog file:", fallbackError);
        }
      }
      throw error;
    }
  }

  /**
   * Fetch articles from API
   */
  private async fetchFromAPI(language: string): Promise<BlogArticlesResponse> {
    if (!this.config.apiEndpoint) {
      throw new Error("API endpoint not configured");
    }

    const url = `${this.config.apiEndpoint}/articles?lang=${language}`;
    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`API request failed: ${response.statusText}`);
    }

    const data = await response.json();
    return data.success ? data.data : data;
  }

  /**
   * Check if cache is still valid
   */
  private isCacheValid(key: string): boolean {
    const expiry = this.cacheExpiry.get(key);
    if (!expiry) return false;
    return Date.now() < expiry;
  }

  /**
   * Clear cache
   */
  clearCache(): void {
    this.cache.clear();
    this.cacheExpiry.clear();
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<BlogServiceConfig>): void {
    this.config = { ...this.config, ...config };
    // Clear cache when config changes
    this.clearCache();
  }
}

// Create singleton instance
const blogService = new BlogService({
  source: "file", // Default to file-based
  cacheEnabled: true,
});

export default blogService;
